(function (r, d) { r.RHIndexFiches = d; if (typeof module === 'object' && module.exports) module.exports = d; })(typeof self !== 'undefined' ? self : this, {"fiches":[{"id":"colites","url":"fiches/colites.html","titre":"Imagerie des colites","spe":"digestif","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["Les colites sont des atteintes inflammatoires, ischémiques ou infectieuses du colon qui peuvent toucher la muqueuse ou s'étendre dans les différentes structures de la paroi colique, voire son environnement","Les causes de colites sont nombreuses et leur degré de gravité variable.","Diagnostic (+)l'imagerie et principalement la TDM","Signes de gravitéles chercher","Orienter le diagnostic étiologique","Le diagnostic de certitude repose le plus souvent sur l'endoscopie associée à la biopsie."]}]},{"id":"cadre","titre":"Le côlon en 3D : où siège la colite ?","rubriques":[{"titre":"","badge":"","ancre":"cadre","blocs":["Rappel ajouté à la fiche. Choisissez une colite : les segments qu'elle touche le plus souvent s'allument.","6 à 8 cm","Calibre du caecum","3 à 5 cm","pour le sigmoïde"]}]},{"id":"clinique","titre":"Aspects clinico-biologiques","rubriques":[{"titre":"1. Clinique","badge":"inflammatoires ischémiques infectieuses","ancre":"clinique","blocs":["La présentation clinique est variable :","La symptomatologie peut être d'installation brutale ou progressive selon la cause sous-jacente.","La douleur abdominale et la diarrhée sont les symptômes les plus fréquents"]},{"titre":"2. Biologie","badge":"Des douleurs abdominales aiguës Une fièvre Des troubles du transit (diarrhée liquidienne, glairo-sanglante) Occlusion digestive Etat de choc","ancre":"clinique","blocs":["Hyperleucocytose à PNN, SIB (VS et CRP élevées), des troubles ioniques…","Coproculture/ hémoculture/ sérologie → dg étiologique"]}]},{"id":"imagerie","titre":"Moyens d'imagerie","rubriques":[{"titre":"","badge":"","ancre":"imagerie","blocs":["Imagerie de référence","Sans injectionPassage sans injection → Recherche de gaz extra digestif","Temps artériel (25-30s)n'est pas systématique ; si suspicion d'ischémie mésentérique","Temps portal (70s)passage capital, meilleur temps pour explorer le rehaussement pariétal digestif"]},{"titre":"Opacification digestive (coloscan)","badge":"","ancre":"imagerie","blocs":["En dehors du contexte d'URG","Préparation digestive préalable (régime sans résidus et lavement évacuateur)","Lavement à l'eau ou aux produits de contraste hydrosolubles","Facilite la recherche fistules"]}]},{"id":"paroi","titre":"La paroi colique en 3D : les couches","rubriques":[{"titre":"","badge":"","ancre":"paroi","blocs":["Segment de paroi ouvert et emboîté (dessin 3D du site, proportions schématiques). Touchez une couche ; changez de mode pour voir l'aspect en échographie, ou les couches touchées par une atteinte."]}]},{"id":"normal","titre":"Sémiologie radiologique normale","rubriques":[{"titre":"Épaisseur pariétale","badge":"","ancre":"normal","blocs":["3-4mm si côlon collabé","1-2mm si côlon distendu"]},{"titre":"Rehaussement","badge":"","ancre":"normal","blocs":["Paroi rehaussée de manière homogène après injection"]},{"titre":"Calibre","badge":"","ancre":"normal","blocs":["6 à 8cm pour le caecum","Diminue progressivement jusqu'à 3 à 5 cm pour le sigmoïde"]}]},{"id":"positif","titre":"Diagnostic positif et diagnostic de gravité","rubriques":[{"titre":"","badge":"","ancre":"positif","blocs":["V. Diagnostic positif (colite simple)","Épaississement pariétal > 4mm","Infiltration de la graisse péricolique","Anomalie de densité de la paroi","Signes associés","VI. Diagnostic de gravité (colite compliquée)"]}]},{"id":"etiologie","titre":"Diagnostic étiologique","rubriques":[{"titre":"","badge":"","ancre":"etiologie","blocs":["MICI : Crohn et RCH — maladies chroniques évoluant par poussées","Leur diagnostic repose sur un faisceau d'arguments cliniques, radiologiques, endoscopiques, histologiques et évolutifs : Adultes jeunes (20-30 ans) / diarrhée glairo-sanglante récidivante / syndrome rectal (ténesmes, épreintes et faux besoins) surtout en cas de RCH","Les MICI peuvent se compliquer de mégacôlon toxique : distension importante principalement du côlon transverse qui est > 6 cm avec perte des haustrations et présence de pseudopolypes","Crohn","Siège","Touche n'importe quel segment mais prédomine au niveau de : Iléon terminal et colon droit +++","Épaisseur","Important (≈10mm)","Symétrie","Asymétrique","Extension","Discontinu"]}]}]},{"id":"occlusion-intestinale","url":"fiches/occlusion-intestinale.html","titre":"Imagerie de l'occlusion intestinale aiguë","spe":"digestif","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["OIA = arrêt du transit intestinal, qui peut siéger de l'angle duodéno-jéjunal jusqu'au rectum.","Urgence médico-chirurgicale pouvant mettre en jeu le pronostic vital","75 %","Occlusion du grêle : 75% des cas, dominée par l'occlusion sur bride","Côlon","Origine tumorale : principale cause d'occlusion mécanique du côlon","TDM","TDM : examen clé"]},{"titre":"Le radiologue doit essayer de répondre à 5 questions","badge":"","ancre":"introduction","blocs":["Cliquez une question : la partie qui y répond s'ouvre."]}]},{"id":"physiopathologie","titre":"Physiopathologie","rubriques":[{"titre":"1. Mécanisme","badge":"","ancre":"physiopathologie","blocs":["OIA mécanique","Par obstruction : obstacle intraluminal, pariétal ou extrinsèque","Par strangulation : étranglement de l'anse digestive et de son méso","OIA fonctionnelle","= secondaire à une altération de la motilité intestinale en l'absence de tout obstacle mécanique","Réflexepost-opératoire/ post-traumatique/ secondaire à un foyer infectieux abdominal Iatrogènemorphiniques/ Neuroleptiques/ Anti-choline Métaboliquehypo/ hyper-calcémie Maladie généralediabète/ hypothyroïdie","!!! attention à l'ischémie mésentérique si contexte d'hypoperfusion → fiche Ischémie mésentérique"]},{"titre":"2. Conséquences","badge":"","ancre":"physiopathologie","blocs":["OIA mécanique par obstruction du grêle : un cercle vicieux","Distension des anses en amont par les liquides+ gaz","↗ pression intra luminale > Pr. Intraveineuse","Stase veineuse et lymphatique","↗perméabilité vasculaire","Fuite de liquide plasmatique en dehors des Vx vers la cavité plasmatique","Formation d'un 3ème secteur","Hypovolémie","Majoration de la Pr. Intraluminal","Stase vasculaire","Nécrose de l'anse"]}]},{"id":"clinique","titre":"Tableau clinique","rubriques":[{"titre":"","badge":"","ancre":"clinique","blocs":["Le syndrome occlusif associe 4 signes d'expression variable :","L'importance de ces signes et leur délai de survenue dépendent du siège de l'obstacle :"]},{"titre":"OIA haute","badge":"Douleurs abdominales vomissements arrêt des matières et des gaz distension abdominale","ancre":"clinique","blocs":["précocesvomissements","plus tardifAMG","discrète/absentela distension abdominale"]},{"titre":"OIA basse","badge":"","ancre":"clinique","blocs":["précoceAMG","tardifsvomissements","importantedistension abdominale"]},{"titre":"OIA par strangulation","badge":"","ancre":"clinique","blocs":["brutale, intense et permanentedouleur","d'installation précocesignes généraux","absentmétéorisme abdominal","Examen clinque : recherche de signes orientant vers la cause de l'OIA : cicatrice abdominale, TR, orifices herniaires"]}]},{"id":"exploration","titre":"Moyens d'exploration radiologiques","rubriques":[{"titre":"1. ASP","badge":"","ancre":"exploration","blocs":["N'est plus recommandé lorsque la TDM est disponible","Si réalisé : Normal : n'élimine pas le dg ; +/- pneumopéritoine ; +/- orientation étiologique (aspect de double jambage → volvulus du sigmoïde)","Ne dispense pas de la réalisation d'un scanner en urgence pour chercher l'étiologie et les signes de gravité"]},{"titre":"2. Echographie","badge":"","ancre":"exploration","blocs":["Réalisé chez l'enfant dans le cadre d'une IIA."]},{"titre":"4. IRM","badge":"","ancre":"exploration","blocs":["Non adapté au contexte d'urgence"]},{"titre":"","badge":"","ancre":"exploration","blocs":["NHA à l'ASP : grêle ou côlon ?","De type grêle","De type colique"]},{"titre":"3. TDM — C'est l'examen clé pour l'exploration de l'OIA","badge":"peu nombreuxpériphériqueplus haut que large","ancre":"exploration","blocs":["1Acquisition abdomino-pelvienne SPC","2Acquisition abdomino-pelvienne au temps portal (70s) après injection de PDC","✗Pas d'opacification digestive"]}]},{"id":"positif","titre":"Apport de la TDM : diagnostic positif","rubriques":[{"titre":"","badge":"","ancre":"positif","blocs":["Distension des anses digestives de diamètre :","> 2,5 cm","> 2,5cm pour les anses","> 5 cm","> 5cm pour le côlon"]}]},{"id":"mecanisme","titre":"Diagnostic du mécanisme","rubriques":[{"titre":"","badge":"","ancre":"mecanisme","blocs":["Occlusion mécanique","disparité de calibre entre les anses, avec anses dilatées séparées d'anses non dilatées par une « zone transitionnelle »","Occlusion fonctionnelle","distension aérique diffuse des anses + peu ou pas de NHA / pas de ZT"]}]},{"id":"topographie","titre":"Diagnostic topographique","rubriques":[{"titre":"","badge":"","ancre":"topographie","blocs":["Utiliser le mode ciné et le plan coronal","Suivre les anses dilatées","S'aider du « Feces Sign »si occlusion du grêle"]},{"titre":"« Feces Sign »","badge":"","ancre":"topographie","blocs":["il correspond à des granités stercorales dans un anse dilatée (occlusion du grêle)."]},{"titre":"Dg différentiel d'un « Feces Sign »","badge":"","ancre":"topographie","blocs":["Valvule incontinente et reflux de matière","Bézoard","Souffrance ischémique sur bas débit","Diverticule du grêle"]}]},{"id":"etiologie-grele","titre":"Occlusion du grêle : diagnostic étiologique","rubriques":[{"titre":"Extrinsèque","badge":"","ancre":"etiologie-grele","blocs":["Brides et adhérences+++","Masse tumorale de voisinage (carcinose++)","Hernie (interne ou externe)"]},{"titre":"Pariétale","badge":"","ancre":"etiologie-grele","blocs":["Inflammation (crohn/entérite radique)","Tumeur (ADK/TNE…)","Hématome mural"]},{"titre":"Intraluminale","badge":"","ancre":"etiologie-grele","blocs":["Calcul biliaire (iléus biliaire)","Bézoard","IIA"]},{"titre":"","badge":"","ancre":"etiologie-grele","blocs":["Par strangulation","Bride avec occlusion à anse fermée +/- volvulus","Hernie étranglée","Invagination intestinale aiguë","Par obstruction","Extraluminale : bride ++","Iléus biliaire","Tumeur du grêle → peut donner une IIA","Autres : crohn, hématome pariétal, bézoard, parasite, corps étranger, anomalies congénitales (mésentère commun, diverticule de meckel)","Démarche :","Eliminer les causes faciles : Iléus biliaire/ bezoard","Regarder les orifices herniaires+++"]},{"titre":"1. Obstructions intraluminales","badge":"","ancre":"etiologie-grele","blocs":["Complication rare de la cholécystite lithiasique","Migration d'un calcul vésiculaire de taille > 2,5cm à travers une fistule bilio-digestive, qui vient s'enclaver au niveau de l'intestin grêle","TDM :"]},{"titre":"2. Obstructions extrinsèques","badge":"Calcul au niveau de la lumière de l'intestin grêleAérobilie ou pneumocholécyste (en rapport avec la fistule)","ancre":"etiologie-grele","blocs":["2.1. Hernie","Externes","vérifier les orifices pariétaux :","La présence d'une masse douloureuse irréductible au niveau d'un orifice herniaire permet de faire le dg","Imagerie permet de : préciser le contenu du sac herniaire, évaluer les signes de gravité de l'occlusion +/- faire le dg positif de hernie si examen clinique non aisé","Internes","surtt si ATCDS de chirurgie (bariatrique, DPC)","Trans-mésentérique : La plus fréquente","Para-duodénal : (G > D)","TDM : anses dilatées en situation, anormale avec aspect de « sac-like »","Incisionnelle/ parastomiales","2.2. Brides et adhérences"]},{"titre":"3.1. Tumoral/ inflammatoire","badge":"","ancre":"etiologie-grele","blocs":["Epaississement courttumoral++/ ADK > >> TNE","Epaississement longCrohn++"]},{"titre":"3.2. Hématome pariétal","badge":"","ancre":"etiologie-grele","blocs":["Terrain: hémophilie, vascularite, ttt anticoagulant","Siège: jejunum++","TDM : épaississement pariétal régulier, circonférentiel et spontanément hyperdense"]}]},{"id":"gravite","titre":"Diagnostic de gravité","rubriques":[{"titre":"","badge":"","ancre":"gravite","blocs":["2 ou 3 signes = chirurgie !!!"]},{"titre":"","badge":"","ancre":"gravite","blocs":["Pneumopéritoine : témoignant d'une perforation","Aéromésentérie/aéroportie","+/- pneumatose pariétale"]},{"titre":"NB : défaut de rehaussement","badge":"","ancre":"gravite","blocs":["Hyperdensité spontanée : spécificité de 100% de nécrose en association avec closed-loop","Passage SPC : ↗ Se !!!"]}]},{"id":"colon","titre":"Occlusion du côlon : diagnostic étiologique","rubriques":[{"titre":"","badge":"","ancre":"colon","blocs":["Par strangulation","Volvulus du sigmoïde","Volvulus du caecum ou du côlon droit","Par obstruction","Cancer colo-rectal","Autres : sténose inflammatoire/cicatricielle (sigmoïdite), colite ischémique, radique","Fécalome"]},{"titre":"1. Volvulus du sigmoïde","badge":"","ancre":"colon","blocs":["Le colon transverse, le colon sigmoïde et le caecum restent mobiles, unis à la paroi par leur méso qui seront les points de rotation possible."]},{"titre":"a. Facteurs favorisants","badge":"","ancre":"colon","blocs":["Dolico-méga-colon sigmoïde","Constipation chronique : sujet âgé, alitement chronique, ttt psychiatrique","Brides/ adhérences raccourcissant la racine du méso-sigmoïde","Syd de masse pelvienne"]},{"titre":"b. Clinique","badge":"","ancre":"colon","blocs":["Syd occlusif pouvant être aigu, subaigu ou chronique","Distension abdominale asymétrique","Vacuité FIG","Défense/contracture/ rectorragies","Complications (nécrose, perforation, péritonite)"]},{"titre":"","badge":"","ancre":"colon","blocs":["c. Imagerie","ASP","Intérêt limité si accès rapide au scanner. Clichés : face debout +/- centré sur les coupoles ; Face Couché","Volumineuse clarté digestive pelvi-abdominale","Superposition « sigmoïde » à l'ampoule rectale","Perte des haustrations coliques","Vacuité de la FIG et du rectum","Signe de « Grain de café »","Signe « U inversée »","Scanner : 1) Dg positif","Volumineux boucle sigmoïdienne","En position ectopique"]},{"titre":"Signes de souffrance digestive","badge":"","ancre":"colon","blocs":["Degré de distension","Amincissement paroi < 1mm","Epaississement paroi > 3mm, aspect en cible","Défaut de rehaussement","Hyperdensité spontanée","Pneumatose pariétale +- aéroportie (nécrose pariétale)"]},{"titre":"Zone de torsion","badge":"","ancre":"colon","blocs":["Spire apparait serré","Nombre de tours de spire"]},{"titre":"Signes extra-digestifs","badge":"","ancre":"colon","blocs":["Epanchement liquidien","Pneumopéritoine","Souffrance du méso : infiltration/ hyperhémie/ épanchement/ hémorragie"]},{"titre":"d. Dg différentiel","badge":"","ancre":"colon","blocs":["Autres causes d'occlusion colique mécanique : tumeurs ++","Pseudo-obstruction colique aigu","Syd d'Ogilvie"]},{"titre":"e. Traitement","badge":"","ancre":"colon","blocs":["Détorsion endoscopique +++ en URG en l'absence de signes de complicationsTaux de réussite : 50-80% ; Risque de récidive après ttt endoscopique très élevé","ChirurgieAprès ttt endoscopique ou d'emblée si signes de complications"]},{"titre":"2. Syndrome d'Ogilvie","badge":"","ancre":"colon","blocs":["Forme particulière d'occlusion du côlon","Terrain de débilité : sujet âgé alité, patients traités par neuroleptiques, patient intubé-ventilé","Etiopathogénie non encore connue","Dilatation diffuse du cadre colique à contenu majoritairement gazeux sans obstacle mécanique","Risque de perforation caecale"]},{"titre":"3.1. Obstruction pariétale","badge":"","ancre":"colon","blocs":["70 %","ADK colique : 70% des causes d'OIA colique ; siège dans 75% des cas au niveau du sigmoïde ou du côlon gauche","TDM : épaississement pariétal colique court, asymétrique, irrégulier, rehaussé +/- densification de la graisse péri-colique","Sténoses coliques « bénignes » : Crohn/ colite post-radique","Sigmoïdite aigue diverticulaire"]},{"titre":"3.2. Obstruction endoluminale","badge":"","ancre":"colon","blocs":["Fécalome : dg clinique"]}]}]},{"id":"masses-hepatiques","url":"fiches/masses-hepatiques.html","titre":"Masses hépatiques solides","spe":"digestif","sections":[{"id":"introduction","titre":"Objectifs et démarche diagnostique","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["Détecter, localiser, mesurer et préciser le caractère hépatique, solide/kystique, bénin/malin, primitif/secondaire.","Rechercher complications, atteinte vasculaire ou biliaire, extension locorégionale et à distance ; orienter abstention, surveillance, biopsie ou traitement.","Premier filtre : le terrain — foie à risque de CHC, foie sain, cancer primitif connu, sexe/âge, contraception, maladie métabolique et expositions."]},{"titre":"Les 12 lésions de la fiche","badge":"","ancre":"introduction","blocs":["Cliquez sur une lésion pour aller à sa fiche. Les couleurs reprennent celles de la fiche de l'auteur.","Tumeur bénigne","Tumeur maligne primitive","Tumeur maligne secondaire","Tumeur vasculaire maligne rare","1Hémangiome","2Hyperplasie nodulaire focale (HNF)","3Adénome hépatocellulaire","4Angiomyolipome et lésions graisseuses","5Carcinome hépatocellulaire (CHC)","6CHC fibrolamellaire","7Cholangiocarcinome intrahépatique"]}]},{"id":"pseudolesions","titre":"Vraie masse ou pseudolésion ?","rubriques":[{"titre":"","badge":"","ancre":"pseudolesions","blocs":["Vraie masse : forme arrondie/ovalaire, effet de masse, refoulement ou interruption vasculaire, déformation du contour, différence de signal persistante et cinétique propre.","Pseudolésion","Arguments","Stéatose focale","Segment IV, lit vésiculaire, péri-falciforme ; forme géographique ; aucun effet de masse ; vaisseaux traversants ; chute du signal en opposition de phase.","Épargne focale","Zone non stéatosique dans un foie gras ; pas de chute en opposition de phase ; pseudo-nodule, souvent segment IV autour d'une veine gastrique gauche.","Trouble perfusionnel","Hyperrehaussement artériel géographique ; aucun effet de masse ; homogénéisation portale ; cause vasculaire, biliaire ou inflammatoire."]}]},{"id":"exploration","titre":"Protocole d'exploration","rubriques":[{"titre":"A. Échographie-Doppler","badge":"","ancre":"exploration","blocs":["Première intention : foie, contours, échostructure ; nombre, siège, dimensions, échogénicité, homogénéité, limites, renforcement/atténuation postérieure et rapports.","Doppler : vascularisation tumorale, rapports et perméabilité vasculaire. Peut suffire pour un kyste simple ou un hémangiome typique sur foie sain sans contexte oncologique.","Échographie de contraste : améliore caractérisation et cinétique mais ne suit qu'une lésion à la fois et ne remplace pas un bilan d'extension complet."]},{"titre":"B. TDM multiphasique","badge":"","ancre":"exploration","blocs":["Cliquez sur un temps de la frise pour voir la technique et ce qu'il faut rechercher."]},{"titre":"Sans injection","badge":"","ancre":"exploration","blocs":["Foie ; PDC 2 mL/kg, débit 3-4 mL/s. Recherche : graisse, hémorragie, calcifications, densité spontanée et surcharge hépatique."]},{"titre":"C. IRM hépatique — examen de choix","badge":"","ancre":"exploration","blocs":["Séquence","Apport","T1 FS + T1 double écho IP/OP","Graisse macroscopique supprimée en FatSat ; graisse intracellulaire = chute en opposition de phase ; sang = hypersignal T1.","Axial rapide HASTE/SSFSE sans FS ; axial FSE/TSE avec FS ; coronal T2. Très hyperT2 liquidien versus fibrose hypoT2.","Diffusion + ADC","Plusieurs valeurs de b (0-50, 400-500 et 800-1000 s/mm2) ; restriction vraie = DWI élevée + ADC abaissé.","T1 3D EG FS dynamique","Sans contraste, artériel, portal et tardif ; séquences soustraites si besoin.","Cholangio-IRM","Étude des voies biliaires si nécessaire.","Règle : l'IRM est plus performante que la TDM pour la caractérisation tissulaire et la détection de certaines petites lésions ; la TDM garde une excellente valeur pour l'extension, les calcifications et l'urgence."]}]},{"id":"semiologie","titre":"Sémiologie transversale","rubriques":[{"titre":"","badge":"","ancre":"semiologie","blocs":["Quatre termes à employer au sens strict."]},{"titre":"Hypervascularisation","badge":"","ancre":"semiologie","blocs":["Rehaussement supérieur au foie adjacent au temps artériel."]},{"titre":"Wash-out","badge":"","ancre":"semiologie","blocs":["Lésion hyper- ou iso-rehaussée en artériel devenant réellement hypo-rehaussée au temps portal/tardif. Un retour à l'isodensité/isosignal n'est pas un wash-out."]},{"titre":"Capsule","badge":"","ancre":"semiologie","blocs":["Rehaussement annulaire surtout tardif ; un anneau artériel disparaissant au temps tardif n'est pas une capsule."]},{"titre":"Restriction vraie","badge":"","ancre":"semiologie","blocs":["Hypersignal à b élevé avec ADC bas ; si ADC élevé, penser effet shine-through."]}]},{"id":"benignes","titre":"Tumeurs bénignes","rubriques":[{"titre":"1. Hémangiome hépatique","badge":"","ancre":"les-hemangiome","blocs":["Tumeur bénigne solide la plus fréquente ; souvent femme jeune, asymptomatique, < 3 cm, sous-capsulaire ou près des veines hépatiques ; ne dégénère pas.","Échographie typique : hyperéchogène, homogène, bien limité, renforcement postérieur, sans signal Doppler (flux trop lent).","TDM/IRM : hypoT1, hyperT2 franc proche de la bile/LCR, pas de restriction vraie ; rehaussement périphérique discontinu globuleux « en mottes », remplissage centripète progressif, parallèle à l'aorte et sans wash-out.","Diagnostic échographique accepté seulement si aspect typique, foie sain et absence de contexte carcinologique ; sinon confirmer, de préférence en IRM."]},{"titre":"Formes atypiques","badge":"","ancre":"les-hemangiome","blocs":["Forme atypique","Clés","Hypervasculaire rapide","Petit, souvent < 2 cm ; remplissage artériel complet persistant portal/tardif ; hyperT2 franc ; aucun wash-out.","Géant","> 10 cm ; hétérogène ; remaniements centraux ; remplissage incomplet ; syndrome de Kasabach-Merritt exceptionnel.","Scléreux","Perte de l'hyperT2 franc, faible rehaussement, parfois rétraction capsulaire ; diagnostic difficile.","Sur foie stéatosique","Peut devenir hypoéchogène en échographie et iso/hyperdense spontanément en TDM.","Piège : le remplissage centripète n'est pas spécifique. Ce sont les mottes périphériques, parallélisme avec le pool sanguin, hyperT2 franc et absence de wash-out qui sécurisent le diagnostic."]},{"titre":"2. Hyperplasie nodulaire focale (HNF)","badge":"","ancre":"les-hnf","blocs":["Deuxième tumeur bénigne solide ; femme jeune ; toujours bénigne, sans risque hémorragique ni transformation.","Échographie : lésion peu différente du foie ; isoéchogène ou très discrètement hypoéchogène ; élément central hyperéchogène ; vascularisation radiaire en rayon de roue au Doppler couleur.","TDM/IRM : iso ou légèrement hypoT1, iso/discret hyperT2 ; hyperrehaussement artériel intense, précoce et homogène, homogénéisation portale, sans wash-out ni capsule ; contours lobulés au scanner et à l'IRM.","Cicatrice centrale hyperT2, rehaussée tardivement (sa présence seule n'est pas spécifique)."]},{"titre":"HNF typique : cinq critères majeurs","badge":"","ancre":"les-hnf","blocs":["Cochez les critères observés : la jauge se remplit.","Ces critères sont valables en l'absence d'hépatopathie sous-jacente."]},{"titre":"HNF ou CHC fibrolamellaire ?","badge":"","ancre":"les-hnf","blocs":["HNF","CHC fibrolamellaire","Homogène","Hétérogène et lobulée","Cicatrice hyperT2","Cicatrice hypoT2 fibreuse","Calcification exceptionnelle","Calcification centrale fréquente","Pas de capsule ni adénopathie","Capsule et adénopathies possibles","Si aspect formel : pas de traitement ; surveillance à un an possible puis très espacée."]},{"titre":"3. Adénome hépatocellulaire","badge":"","ancre":"les-adenome","blocs":["Terrain : femme en activité génitale ; FDR : contraception œstroprogestative, stéroïdes, glycogénose, obésité/syndrome métabolique.","Pas de signe d'hépatopathie chronique ; pas d'anomalie vasculaire/biliaire.","Risques : hémorragie, rupture et transformation en CHC ; distinction avec HNF indispensable.","Échographie : lésion bien limitée, hétérogène par graisse, sang ou nécrose ; échogénicité variable ; vascularisation plutôt périphérique.","TDM : iso ou discrètement hypodense ; ± zones hyperdenses d'hémorragie ; hyperrehaussement artériel souvent hétérogène ; homogénéisation ou wash-out possible ; capsule tardive possible ; pas de cicatrice typique.","IRM : signal T1 variable (hyposignal, isosignal ou hypersignal), hyperT2 ; rehaussement semblable au scanner (hyperrehaussement artériel hétérogène, wash-out et capsule tardifs possibles).","Complication : douleur aiguë, hématome intratumoral/sous-capsulaire ou hémopéritoine."]},{"titre":"Sous-types","badge":"","ancre":"les-adenome","blocs":["Sous-type","Imagerie / risque","HNF1A-inactivé stéatosique","Graisse intracellulaire diffuse, chute homogène OP ; rehaussement artériel modéré ; wash-out généralement absent ; faible risque malin.","Inflammatoire / Télangiectasique","HyperT2 franc, « atoll sign », hyperrehaussement artériel persistant portal/tardif ; risque hémorragique ; risque de transformation maligne ; DD HNF.","β-caténine activé","Aspect peu spécifique, parfois hypervasculaire ; risque de transformation plus élevé ; diagnostic souvent histologique.","Sonic hedgehog","Risque hémorragique ; sémiologie peu spécifique.","Conduite : si l'imagerie ne permet pas d'affirmer une HNF, considérer la lésion comme suspecte d'adénome ; discussion en RCP, biopsie ciblée ou traitement selon taille, nombre et risque."]},{"titre":"HNF ou adénome ?","badge":"","ancre":"les-adenome","blocs":["Critère","HNF","Adénome","Terrain","Femme jeune, aucun facteur spécifique","Contraception, métabolique, stéroïdes","Structure","Homogène","Hétérogène : graisse/sang/nécrose","Cicatrice","HyperT2, tardive","Pas de cicatrice typique"]},{"titre":"4. Angiomyolipome et lésions graisseuses","badge":"","ancre":"les-aml","blocs":["Tumeur mésenchymateuse associant graisse, vaisseaux et muscle lisse ; femme ; parfois sclérose tubéreuse de Bourneville.","Échographie : hyperéchogène hétérogène avec flux artériel.","TDM : graisse macroscopique, hypervascularisation persistante et vaisseaux centraux.","IRM : hypersignal T1 supprimé en FatSat, sans chute spécifique IP/OP."]},{"titre":"Tumeur à triple composante","badge":"","ancre":"les-aml","blocs":["Composante externe graisseuse : hyperéchogène ; hypodense franc ; chute de signal en fat-sat ; chute partielle en opposition de phase (OP).","Composante interne solide : hypoéchogène ; densité intermédiaire ; hypoT1, hyperT2.","Composante vasculaire : présence d'artères de grande taille.","DD d'une masse graisseuse : adénome stéatosique, CHC graisseux, stéatose focale, lipome et myélolipome."]}]},{"id":"primitives","titre":"Tumeurs malignes primitives","rubriques":[{"titre":"5. Carcinome hépatocellulaire (CHC)","badge":"","ancre":"les-chc","blocs":["Tumeur maligne primitive la plus fréquente ; environ 80 % sur cirrhose, possible sur VHB chronique non cirrhotique.","Échographie de surveillance tous les 6 mois : nodule souvent hypoéchogène, parfois iso/hyperéchogène ; tout nodule sur foie à risque est suspect.","Aspect typique TDM/IRM : hyperrehaussement artériel non périphérique + wash-out portal/tardif + capsule tardive.","IRM : souvent hyperT2 modéré, T1 variable ; architecture en mosaïque ; graisse ou hémorragie ; restriction possible.","Signe très évocateur : thrombose portale ou hépatique tumorale."]},{"titre":"LI-RADS","badge":"","ancre":"les-chc","blocs":["S'applique aux patients cirrhotiques ou à risque de CHC, en TDM/IRM injectée ; ne s'applique pas au foie sain.","Critères majeurs : Taille, Rehaussement artériel, Wash-out, Capsule et Croissance significative.","Mesure du grand axe, de marge externe à marge externe, capsule incluse et trouble perfusionnel exclu.","Croissance significative : ≥ 50 % en ≤ 6 mois ; ≥ 100 % si intervalle > 6 mois ; ou nouvelle lésion ≥ 10 mm.","Contexte validé + lésion > 1 cm + hypervascularisation + wash-out = diagnostic non invasif de CHC. En cas d'aspect non typique : biopsie/discussion.","Calculateur : catégorie LR-3 / LR-4 / LR-5 selon taille et HRPA","Saisissez la taille de la lésion : la case correspondante du tableau s'allume.","Nombre de critères majeurs","Pas de HRPA","HRPA non-périphérique","< 20","≥ 20"]},{"titre":"Catégories LI-RADS","badge":"","ancre":"les-chc","blocs":["Catégorie","Signification","À retenir","LR-NC","Non classé (imagerie de mauvaise qualité ou incomplète)","LR-1","Certainement bénin","Écho de surveillance à 6 mois","LR-2","Probablement bénin","Écho à 6 mois ± TDM/IRM ≤6 mois","LR-3"]},{"titre":"Thrombus tumoral ou cruorique ?","badge":"","ancre":"les-chc","blocs":["Thrombus tumoral","Thrombus cruorique","Expansion veineuse possible","Vaisseau non expansif","Hyperrehaussement artériel du thrombus","Pas de rehaussement","Wash-out et cinétique identique à la tumeur","Pas de cinétique tumorale","Restriction possible","Signal non spécifique","Bilan d'extension : nombre, taille, segments, nodules satellites, état du parenchyme ; veine porte, veines hépatiques, VCI, voies biliaires, adénopathies ; poumons et os (métastases plus tardives).","Nodule sur foie à risque : > 1 cm → TDM ou IRM multiphasique ; < 1 cm → surveillance rapprochée (échographie à 3 mois)."]},{"titre":"6. CHC fibrolamellaire","badge":"","ancre":"les-fibro","blocs":["Sujet jeune, foie non cirrhotique ; grosse masse unique, lobulée, bien limitée mais hétérogène ; AFP normale ou peu élevée.","Hypervascularisation artérielle hétérogène ; wash-out possible ; capsule, rétraction, dilatation biliaire et adénopathies suspectes.","Cicatrice centrale fibreuse : hypoT2, souvent calcifiée, rehaussée tardivement. Ne contient pas de graisse.","DD principal : HNF, qui est homogène avec cicatrice hyperT2, sans capsule ni adénopathie."]},{"titre":"7. Cholangiocarcinome intrahépatique","badge":"","ancre":"les-cholangio","blocs":["Adénocarcinome biliaire ; sujet autour de 60 ans ; facteurs : maladie de Caroli, cholangite sclérosante, lithiase intrahépatique.","Masse périphérique volumineuse, lobulée, non encapsulée ; échographie souvent hyperéchogène mais variable.","HypoT1, T2 variable ; rehaussement périphérique fin puis progressif centripète tardif par la fibrose (parfois maximal à 10-20 min) ; restriction surtout périphérique.","Signes clés : rétraction capsulaire, dilatation biliaire segmentaire modérée, nodules satellites, atrophie homolatérale/hypertrophie controlatérale.","Atteinte vasculaire typique par engainement externe des branches portes ou veines hépatiques, contrairement à l'extension endoluminale du CHC."]},{"titre":"CHC ou cholangiocarcinome ?","badge":"","ancre":"les-cholangio","blocs":["CHC","Cholangiocarcinome","Hyperrehaussement artériel + wash-out","Rehaussement fibreux progressif tardif","Capsule possible","Rétraction capsulaire fréquente","Thrombus tumoral endoluminal","Engainement vasculaire externe","Dilatation biliaire variable","Dilatation périphérique segmentaire","Foie à risque","Foie sain ou malade"]},{"titre":"8. Cholangiocarcinome hilaire (tumeur de Klatskin)","badge":"","ancre":"les-klatskin","blocs":["Tumeur fibreuse : rehaussement progressif.","Principaux facteurs de risque : cholangite sclérosante primitive (CSP), kyste du cholédoque, lithiase intra-hépatique.","Trois formes : nodulaire, infiltrante, polypoïde."]},{"titre":"Classification de Bismuth et Corlette","badge":"","ancre":"les-klatskin","blocs":["Choisissez un type : la zone atteinte s'affiche en rouge sur l'arbre biliaire (vue de face, droite du patient à gauche de l'écran).","Schéma pédagogique réalisé pour le site, proportions schématiques."]},{"titre":"Critères de non résécabilité","badge":"","ancre":"les-klatskin","blocs":["Extension tumorale bilatérale au-delà des convergences biliaires secondaires.","Envahissement du tronc porte ou de l'artère hépatique au hile.","Envahissement controlatéral vasculaire.","Métastases hépatiques bilatérales et à distance.","Insuffisance du volume du foie restant."]}]},{"id":"secondaires","titre":"Tumeurs malignes secondaires / systémiques","rubriques":[{"titre":"9. Métastases hépatiques","badge":"","ancre":"les-metastases","blocs":["Tumeurs malignes du foie les plus fréquentes, environ 18 fois plus fréquentes que les primitives ; souvent multiples, bilobaires et de taille variable.","Échographie : typiquement nodules hypo/isoéchogènes avec halo hypoéchogène en cocarde ; formes hyperéchogènes volontiers colorectales, kystiques ou calcifiées.","Aspect le plus fréquent = métastases hypovasculaires : lésions hypodenses présentant un rehaussement périphérique persistant à la phase portale, avec un centre restant hypodense ; mieux étudiées à la phase portale. Exemples : colorectal, gastrique, pancréas, poumon."]},{"titre":"Autres aspects en TDM","badge":"","ancre":"les-metastases","blocs":["Hypervasculaires : lésions hyperdenses au temps artériel avec wash-out au temps portal ou tardif ; TNE (digestives ou pancréatiques), K du rein, K de la thyroïde."]},{"titre":"IRM","badge":"","ancre":"les-metastases","blocs":["La plupart des métastases sont hypoT1 et modérément hyperT2. Certaines sont hyperT1 : remaniements hémorragiques, contenu riche en protéines ou en mélanine (mélanome (mélanine), côlon (hémorragie), ovaire (protéines)).","Le plus souvent hypovasculaires après injection, avec un rehaussement périphérique persistant ; certaines hypervasculaires, avec la même cinétique qu'à la TDM.","Après chimiothérapie : calcification, fibrose et pseudocirrhose possibles.","DD : hémangiome, stéatose focale et abcès. Une évolution rapide favorise l'infection.","En l'absence de primitif devant une lésion suspecte : explorer notamment côlon/rectum puis TDM thorax-abdomen-pelvis ; biopsie si bilan négatif."]},{"titre":"10. Lymphome hépatique","badge":"","ancre":"les-lymphome","blocs":["Secondaire le plus souvent ; primitif rare, généralement LMNH. Forme diffuse, multinodulaire ou masse solitaire.","Masse/nodules homogènes, hypoéchogènes, hypovasculaires ; hypoT1, hyperT2 modéré et restriction très marquée.","Vaisseaux traversants et engainés mais perméables, peu de thrombose ; peu de dilatation biliaire malgré le volume ; adénopathies et splénomégalie.","Imagerie non spécifique : confirmation histologique indispensable."]}]},{"id":"vasculaires","titre":"Tumeurs vasculaires malignes rares","rubriques":[{"titre":"11. Hémangioendothéliome épithélioïde","badge":"","ancre":"les-hee","blocs":["Femme d'âge moyen ; nodules périphériques sous-capsulaires confluents.","Cible, rétraction, rehaussement annulaire puis progressif ; signe de la sucette ; calcifications possibles."]},{"titre":"12. Angiosarcome","badge":"","ancre":"les-angiosarcome","blocs":["Homme âgé ; chlorure de vinyle / arsenic / stéroïdes.","Lésions multiples ou infiltrantes, hypervascularisation anarchique avec mottes non systématiquement périphériques ; hémorragie/nécrose, rupture ; biopsie à haut risque.","Imagerie non spécifique : confirmation histologique indispensable."]}]},{"id":"reconnaissance","titre":"Tableau final de reconnaissance","rubriques":[{"titre":"","badge":"","ancre":"reconnaissance","blocs":["Filtrez par catégorie ; cliquez sur un nom pour retourner à la fiche de la lésion.","Lésion","Terrain / T2","Cinétique et signe distinctif","Hémangiome","Foie sain ; très hyperT2","Mottes périphériques, centripète, parallèle au sang, sans wash-out.","HNF","Femme jeune ; cicatrice hyperT2","Artériel homogène, iso portal, cicatrice tardive, sans capsule.","Adénome","Contraception ; hétérogène"]}]},{"id":"cat","titre":"CAT devant une lésion focale hyperéchogène","rubriques":[{"titre":"","badge":"","ancre":"cat","blocs":["Objectif : ne jamais conclure « angiome » sur la seule hyperéchogénicité. Vérifier le terrain, le foie, le nombre, la morphologie et la cinétique."]},{"titre":"Vérifier qu'il s'agit d'une vraie lésion","badge":"","ancre":"cat","blocs":["Confirmer sur deux plans ; rechercher forme nodulaire, effet de masse, déviation/interruption vasculaire et contour propre.","Zone géographique sans effet de masse, vaisseaux traversants, siège péri-falciforme/segment IV/lit vésiculaire → stéatose focale ou épargne ; IRM IP/OP si doute.","Multiples microfoyers avec queue de comète → évoquer hamartomes biliaires ; compléter par IRM fortement T2 si nécessaire."]},{"titre":"Classer le contexte","badge":"","ancre":"mh-contexte","blocs":["Choisissez le contexte du patient : l'hypothèse prioritaire et la conduite s'affichent.","Hypothèse prioritaire et conduite selon le contexte."]},{"titre":"Rechercher les signes d'alarme","badge":"","ancre":"cat","blocs":["Malignité : halo hypoéchogène, contours irréguliers/infiltrants, multiplicité, hétérogénéité, nécrose, rétraction capsulaire, dilatation biliaire, adénopathies ou thrombose.","Complication : douleur aiguë, hémorragie intralésionnelle, hématome sous-capsulaire ou hémopéritoine.","Doppler négatif ne prouve pas la bénignité : il est habituel dans l'hémangiome à flux lent mais peut aussi survenir dans une lésion peu vascularisée."]},{"titre":"Choisir l'examen de caractérisation","badge":"","ancre":"cat","blocs":["IRM hépatique multiparamétrique en priorité si l'échographie n'est pas formelle : T1 IP/OP, T1 FS, T2, diffusion/ADC et dynamique multiphasique ± hépatobiliaire.","TDM multiphasique si urgence, extension, calcifications ou IRM impossible.","Biopsie si caractérisation non invasive impossible et si le résultat modifie la prise en charge ; prudence si suspicion de tumeur vasculaire."]}]},{"id":"references","titre":"Références et voir aussi","rubriques":[{"titre":"Pour approfondir","badge":"","ancre":"references","blocs":["2018 — Chernyak V, Fowler KJ, Kamaya A, et al. Liver Imaging Reporting and Data System (LI-RADS) Version 2018: Imaging of Hepatocellular Carcinoma in At-Risk Patients. Radiology. 2018;289(3):816-830. DOI : 10.1148/radiol.2018181494 · PubMed 30251931","2016 — European Association for the Study of the Liver (EASL). EASL Clinical Practice Guidelines on the management of benign liver tumours. J Hepatol. 2016;65(2):386-398. DOI : 10.1016/j.jhep.2016.04.001 · PubMed 27085809","2018 — European Association for the Study of the Liver (EASL). EASL Clinical Practice Guidelines: Management of hepatocellular carcinoma. J Hepatol. 2018;69(1):182-236. DOI : 10.1016/j.jhep.2018.03.019 · PubMed 29628281","Lectures complémentaires publiées en 2016 et 2018, vérifiées dans PubMed. Ce ne sont pas les sources originales du cours de l'auteur, qui ne sont pas citées ici ; le contenu de la fiche suit le cours de l'auteur."]},{"titre":"Voir aussi","badge":"","ancre":"references","blocs":["Adénocarcinome du pancréasMétastases hépatiques, bilan d'extension","IRM du cancer du rectumPrimitif colorectal : bilan avant les métastases","Toutes les fiches DigestifColites, occlusion, ischémie, pancréas…"]}]}]},{"id":"pancreatite-aigue","url":"fiches/pancreatite-aigue.html","titre":"Imagerie de la pancréatite aiguë","spe":"digestif","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["Inflammation aigue de la glande pancréatique en rapport avec son autodigestion par ses propres enzymes.","La PA œdémateuse","œdémateuse généralement bénigne","La PA nécrosante","nécrosante, potentiellement grave en fonction de l'étendue de la nécrose et de la survenue ou non de complications.","URG médico-chirurgicale pouvant mettre en jeu le pronostic vital ou être à l'origine de séquelles","80 %","La lithiase biliaire (migration d'un calcul biliaire) et l'alcoolisme chronique = les deux principales causes (80% des causes), la première étant la 1ère cause en Tunisie."]},{"titre":"","badge":"","ancre":"introduction","blocs":["Le dg (+) peut être porté sur des arguments cliniques et biologiques.","L'imagerie, principalement la TDM, joue un rôle dans :","L'évaluation de la gravité de l'atteinte pancréatique","Recherche des complications + surveillance","Dg (+) si tableau douteux"]},{"titre":"","badge":"","ancre":"introduction","blocs":["L'échographie et l'IRM ont des indications précises (recherche de calculs, caractérisation des collections).","Les collections constituent la principale complication. Elles sont classées selon leur délai d'apparition par rapport à la PA et la présence ou non de nécrose."]}]},{"id":"anatomie","titre":"Rappel anatomique : le pancréas en 3D et en coupes","rubriques":[{"titre":"","badge":"","ancre":"anatomie","blocs":["Rappel ajouté à la fiche : segmentation du pancréas et espaces où diffusent les collections. Touchez un segment (en 3D ou sur la coupe) : il s'allume des deux côtés."]},{"titre":"Coupes axiales : segments et espaces","badge":"","ancre":"anatomie","blocs":["Espaces (cliquez sur la coupe ou ici)","Choisissez un espace : il se colore et ses limites s'affichent.","péritoine pariétal postérieur","fascia rénal antérieur","fascia rénal postérieur","fascia latéro-conal"]}]},{"id":"anapath","titre":"Anatomo-pathologie","rubriques":[{"titre":"","badge":"","ancre":"anapath","blocs":["On distingue deux formes de PA de pronostic différent :","La PA œdémateuse (interstitielle):","Œdème glandulaire sans hémorragie ni nécrose","Évolution vers la guérison","La PA nécrotico-hémorragique/ nécrosante :","En plus de l'œdème : lésions hémorragiques et nécrotiques intra et extra-pancréatiques. Divisée en 3 sous-types :","La nécrose mixte intra et extra parenchymateuse: ++(75-80%)","La nécrose péri-pancréatique isolée (20%)","La nécrose intra-pancréatique isolé (5%) : rare.","L'évolution est imprévisible (résolution complète, surinfection secondaire, fistulisation, persistance d'une collection)."]}]},{"id":"exploration","titre":"Moyens d'exploration radiologiques","rubriques":[{"titre":"1. ASP","badge":"","ancre":"exploration","blocs":["Non recommandé : irradiant, peu sensible et peu spécifique.","Examen peut être normal ou montrer : un aspect d'anse sentinelle ; l'absence de pneumopéritoine."]},{"titre":"2. Échographie","badge":"","ancre":"exploration","blocs":["Examen souvent gêné par un iléus réflexe, rendant l'exploration du pancréas difficile.","Elle a plus d'utilité dans un but étiologique (recherche de lithiase biliaire)."]},{"titre":"3. TDM : examen clé","badge":"","ancre":"exploration","blocs":["1Recherche de complications","2Chercher une éventuelle cause biliaire","3Orienter le diagnostic quand le tableau est atypique","Protocole :","SPC (foie et pancréas) : lithiase et de remaniements ou composantes hémorragiques","Temps pancréatique (45s') : acquisition abdominale","Temps portal (70s) : acquisition abdomino-pelvienne ; +/- temps tardif"]},{"titre":"4. IRM","badge":"","ancre":"exploration","blocs":["Plus performante que la TDM pour la recherche des calculs cholédociens et pour la caractérisation des collections (liquidiennes ou nécrosées)"]},{"titre":"Indications","badge":"","ancre":"exploration","blocs":["Recherche de LVBP","Bilan étiologique négatif (éliminer une tm isodense)","Bilan d'une rupture canalaire","Analyse des collections","CI au PDC (grossesse, insuffisance rénale)"]},{"titre":"Protocole","badge":"","ancre":"exploration","blocs":["T2T2 FST1 EG + FS3D dynamique pré et post GadoWirsungo-IRM 2D – 3D"]}]},{"id":"diagnostic","titre":"Diagnostic positif de PA","rubriques":[{"titre":"2.1. Échographie","badge":"","ancre":"diagnostic","blocs":["Peu sensible. Elle peut montrer :","Augmentation de la taille du pancréas avec un aspect hypoéchogène ou hétérogène","Des collections péri-pancréatiques à contenu plus ou moins hétérogène","Un épanchement intra-abdominal","Calculs vésiculaires / lithiase des voies biliaires témoignant de l'étiologie lithiasique","→ Une échographie normale n'écarte pas le diagnostic."]},{"titre":"2.2. TDM : permet de distinguer deux formes de PA","badge":"","ancre":"diagnostic","blocs":["PA œdémateuse","Examen normal (30%)","Pancréas augmenté de taille (hypertrophie focale ou diffuse) avec perte de l'aspect lobulé","Rehaussement homogène de la glande pancréatique","Discrète densification de la graisse péri- pancréatique","PA nécrosante","Plages hypodenses non rehaussées : nécrose <30UH)","3 types : nécrose intra-pancréatique isolée (<5%) — risque de déconnexion pancréatique ; nécrose péri-pancréatique isolée (15%) — meilleur pronostic ; nécrose mixte (75%). Ces 3 types peuvent être stérile ou surinfecté.","PA œdémateusePancréas augmenté de taille avec perte de l'aspect lobulé (flèche) ; rehaussement homogène de la glande pancréatique. Brizi MG et al., La radiologia medica 2021, fig. 1 · source · CC BY 4.0 · flèches et lettres redessinées","PA nécrosantePlages hypodenses non rehaussées : nécrose ; collections péri-pancréatiques (flèches). A : temps artériel ; B : temps portal. Brizi MG et al., La radiologia medica 2021, fig. 3 · source · CC BY 4.0 · flèches et lettres redessinées"]},{"titre":"2.3. IRM","badge":"","ancre":"diagnostic","blocs":["Hypertrophie focale ou diffuse de la glande : en hyposignal T1 ±hétérogène et hyperT2.","Le rehaussement présente la même sémiologie qu'à la TDM.","Le signal du pancréas peut être normal mais il est souvent en hypoT1 et hyperT2.","Les zones de nécroses ne sont pas rehaussées.","Les épanchements liquidiens sont en hyperT2 et les zones hémorragiques sont bien étudiées sur les séquences T1 EG. Elles sont en hypersignal T1."]}]},{"id":"espaces","titre":"Collections pancréatiques et péri-pancréatiques","rubriques":[{"titre":"","badge":"","ancre":"espaces","blocs":["Les collections constituent la principale complication. Choisissez la forme et le délai : la collection d'Atlanta s'affiche avec son image TDM du cours.","< 4 semaines> 4 semaines Pancréatite Oedémato-Interstitielle (POI) Pancréatite Nécrosante (PN)","CANsiège intra et/ou péri-pancréatique","Cliquez une case du tableau.","Siège : CLAP adjacente au pancréas ; CAN intra et/ou péri-pancréatique ; PK adjacent ou distant au pancréas ; NOP intra et/ou extra pancréatique. Les espaces où siègent ces collections sont sur les coupes dessinées du rappel anatomique.","Évolution d'une collectionB : CAN (pas de paroi) ; C : environ 15 jours plus tard ; E : NOP (paroi propre). A et D : échographie ; F : IRM. Sureka B et al., Gastroenterology Report 2016, fig. 5 · source · CC BY 4.0 · flèches et lettres redessinées"]}]},{"id":"severite","titre":"Évaluation de la sévérité","rubriques":[{"titre":"1. Définition des degrés de sévérité de la PA : conférence d'Atlanta 2012","badge":"","ancre":"severite","blocs":["La sévérité de la PA est évaluée sur la présence ou non de défaillances viscérales et la présence ou non de complications locales.","L'évaluation de la défaillance viscérale est basée sur des critères cliniques et biologiques. Plusieurs classifications sont utilisées dont la classification de Ranson.","Les complications locales sont détectées par l'imagerie, principalement la TDM."]},{"titre":"2. Critères de sévérité radiologiques : CTSI (CT Severity Index)","badge":"","ancre":"severite","blocs":["Se base sur la TDM faite 48 à 72H après le début de la symptomatologie","Associe la classification de Balthazar (0-4 points) + l'étendue de la nécrose pancréatique (0-6 points) avec un score final entre 0 et 10"]}]},{"id":"evolution","titre":"Évolution : 2 phases","rubriques":[{"titre":"","badge":"","ancre":"evolution","blocs":["Une phase précoce (1ère semaine)","caractérisée par des anomalies systémiques pouvant aboutir à une défaillance viscérale. Durant cette phase, pas de corrélation entre les anomalies morphologiques constatées à l'imagerie et la gravité de la pathologie (défaillance viscérale). → Seuls les critères clinico-biologiques sont importants pour la décision thérapeutique","Une phase tardive (>1ère semaine, pouvant durer plusieurs semaines voire plusieurs mois)","caractérisée par la présence de complications locales (critères morphologiques déterminés par l'imagerie) ou la persistance de défaillance viscérale.","→ PEC dépend à la fois des constatations de l'imagerie et des critères clinico-biologiques"]}]},{"id":"complications","titre":"Complications","rubriques":[{"titre":"1. Surinfection des collections pancréatiques et péri-pancréatiques","badge":"","ancre":"complications","blocs":["Infection des collections et de la nécrose surtout","Clinique : fièvre/ choc septique","Imagerie : bulles de gaz dans les collections +++","→ faux positif : fistule digestive / après drainage ou ponction","Si pas de bulles de gaz → ponction à l'aiguille (dg +)","Pas de chirurgie avant 1 mois","→ Si collection infectée : commencer par drainage PC (voie postérieure >> voie antérieure)","Apport de l'IRM : caractérisation du contenu des collections","NB : Les 4 types de collections peuvent se surinfecter : très rare pour les CLAP et les pseudokystes et plus fréquent pour les collections contenant de la nécrose (CAN et NOP).","SurinfectionBulles de gaz dans les collections +++ : gaz intra et péri-pancréatique (axial et coronal). Hutsebaut L et al., J Belg Soc Radiol 2023, fig. 1 et 2 · source · CC BY 4.0 · flèches et lettres redessinées"]},{"titre":"Pancréatite aigue emphysémateuse","badge":"Rappel","ancre":"complications","blocs":["= Pancréatite aigue (+/- nécrosante) avec gaz péri-intra-pancréatique d'origine infectieuse : germes BGN (Escherichia coli, Pseudomonas aeruginosa, Klebsiella pneumoniae) ou BG+ (Clostridium perfringens).","Plusieurs mécanismes : par voie indirecte : hématogène / lymphatique / reflux bilio-pancréatique ; par voie directe : fistule entérique (duodénum, colon +++).","Augmentation du risque chez les diabétiques : diminution de la réponse immunitaire due aux altérations microvasculaires + augmentation de la glycémie donc de la dégradation du glucose en CO2.","CTSI 4 : coulées liquidiennes péri-pancréatiques avec air au sein des coulées ; CTSI 6 : nécrose parenchymateuse > 50 % → pancréatite aigue nécrosante emphysémateuse, CTSI 10.","A niveau de gravité égal, la mortalité d'un patient avec pancréatite aigue emphysémateuse est la même que celle d'un patient avec pancréatite aigue surinfectée : PA grave +++, pas grave parce que emphysémateuse mais grave parce que infectée +++ ; taux de mortalité égal avec les PA nécrosantes.","Faux positifs de PA emphysémateuse : fistule-perforation digestive ; air post ponction-biopsie ; chirurgie ; ampoule de Vater béante (post sphinctérotomie +++).","Fenêtrage adaptéAvec un fenêtrage adapté, meilleure visualisation du gaz intra et péri-pancréatique. Hutsebaut L et al., J Belg Soc Radiol 2023, fig. 3 · source · CC BY 4.0 · flèches et lettres redessinées"]},{"titre":"Complications artérielles","badge":"","ancre":"complications","blocs":["Pseudo-anévrysme +++","A. splénique +++ > A. pancréatico-duodénale > A. gastroduodénal","TDM > artériographie (MIP+++)","TTT : * faux anévrysme stable → coil","Hémorragie aigue → embolisation >> chir"]},{"titre":"Complications veineuses","badge":"","ancre":"complications","blocs":["Thrombose veineuse / pseudo-anévrysme veineux (rare)","Veine splénique → HTP segmentaire"]},{"titre":"Syndrome de Weber-Christian","badge":"Rappel","ancre":"complications","blocs":["Complication rare des pancréatites.","Physiopathologie : fistule pancréatico-porte ou pancréatico-mésentérique = libération d'enzymes pancréatiques dans la circulation systémique.","Nécrose adipocytaire avec panniculite lobulaire et infiltrat inflammatoire sous-cutanés.","Clinique : nodules hypodermiques des membres inférieurs, arthralgies-myalgies, fièvre.","Augmentation Amylase sérique +++","Imagerie : Communication d'une collection avec le système porte","Collection avec remaniement hémorragique récent (contenu hyperdense) ; autres collections péri-pancréatiques (flèches). Brizi MG et al., La radiologia medica 2021, fig. 5 · source · CC BY 4.0 · flèches et lettres redessinées","Imagerie : communication d'une collection avec le système porte. A–B : TDM ; C–D : IRM. Taepper MM et al., CVIR Endovascular 2026, fig. 1 · source · CC BY 4.0 · flèches et lettres redessinées","TDM temps portal reconstruction coronale : communication d'une collection avec le système porte (flèche)."]},{"titre":"2. Complications digestives","badge":"","ancre":"complications","blocs":["Inflammation : colite/ duodénite/ jéjunite/gastrite","Fistule digestive : Air +++ ; Scanner avec opacification digestive aux hydrosolubles (dilution 10%)","Rupture rate (rare)","Rupture CPP : à suspecter si Nécrose ≥ 2cm, centro-pancréatique ; CPP discontinu sur Bili-IRM (examen de référence)","Pancréas déconnecté Nikhil et al. Pancreas 2015"]},{"titre":"Disconnected duct syndrome – Pancréas déconnecté","badge":"","ancre":"complications","blocs":["Séquelle fréquente des pancréatites aigues nécrosantes : 16-23% (plus rarement de traumatisme pancréatique) = déconnection complète du canal pancréatique dans sa portion corporéale ou caudale qui ne s'écoule alors plus dans le tube digestif.","Le pancréas déconnecté reste fonctionnel => écoulement permanent de liquide pancréatique dans l'abdomen.","Traitement : redirection du liquide pancréatique dans le tube digestif.","Diagnostic (Nikhil et al. Pancreas 2015) :","Nécrose pancréatique > 2 cm lors de l'épisode de PA","Visualisation de pancréas normal en distalité (queue +++)","Pseudo-kystes intarrisables sur le site de déconnection","Fistule pancréatique persistante","Le pancréas corporéo-caudal ne communique plus avec le pancréas céphalique : le suc pancréatique du canal pancréatique corporéo-caudal ne s'écoule plus par la papille. C'est un diagnostic important car le traitement est chirurgical +++ (pancréatectomie médiane + anastomose pancréatico-gastrique).","Évolution d'un pancréas déconnecté :","TDM à 48hPA necrosante. Nécrose isthmo-corporéale.","TDM à J15Nécrose pancréatique organisée."]}]},{"id":"etiologie","titre":"Diagnostic étiologique","rubriques":[{"titre":"","badge":"","ancre":"etiologie","blocs":["Calculs cholestéroliques","Migration et enclavement dans les papilles (calculs de petite taille+++)","En faveur du dg : * Lithiase vésiculaire","*Cytolyse (ALAT > 3NL) → évocateur de l'origine biliaire (>95%)","Écho-endoscopie : importante intérêt pour le dg les petits calculs du bas cholédoque","TDM : Se 20% pour la lithiase biliaire → signes en faveur : * Dilatation des VB / Cholédocite (PDC+) / Cholécystite aigue associée ; * Calculs vésiculaires (sauf si cirrhose)","Sphinctérotomie endoscopique (SE) : risque accrue de mortalité par défaillance multiviscérale → l'indication de SE en URG : AA+ PA"]}]}]},{"id":"ischemie-mesenterique","url":"fiches/ischemie-mesenterique.html","titre":"Ischémie mésentérique : sémiologie et diagnostic","spe":"digestif","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["L'ischémie mésentérique aiguë correspond à une diminution brutale de la perfusion intestinale, d'origine artérielle, veineuse ou non occlusive.","Peut évoluer vers :","Ischémiediminution brutale de la perfusion","infarctus intestinal,","nécrose transmurale","et perforation digestive.","Urgence diagnostique et thérapeutique, mauvais pronostic.","Retard diagnostique = principal facteur pronostique modifiable."]}]},{"id":"exploration","titre":"Moyens d'exploration","rubriques":[{"titre":"1. Angioscanner abdominal — Examen clé des ischémies mésentériques aiguës.","badge":"artérielleveineusenon occlusive","ancre":"exploration","blocs":["Objectifs :","1Le diagnostic positif","2Le diagnostic différentiel avec les autres pathologies abdominales aiguës","3La recherche de signes directs d'obstruction des axes vasculaires artériels et veineux mésentériques","4La mise en évidence des signes de souffrance intestinale","Technique : 3 acquisitions","sans injection de produit de contraste","au temps artériel (~25-30 s)","au temps portal (70 s)","Analyse en fenêtrage abdominal et pulmonaire pour rechercher des images aériques anormales :","Air intramural : pneumatose","Air intravasculaire : aéroportie, aéromésentérie"]}]},{"id":"etiologie","titre":"Diagnostic étiologique — 3 formes","rubriques":[{"titre":"","badge":"","ancre":"etiologie","blocs":["Barre schématique (milieu des fourchettes de la fiche) ; cliquez une forme pour l'ouvrir."]},{"titre":"I. Origine artérielle thrombo-embolique","badge":"","ancre":"forme-arterielle","blocs":["60-75 % des cas d'IMA — 1ère cause — mortalité entre 60 et 90 %","1. L'embolie (40-50 % des IMA)","Survient sur artère saine.","Entraîne une ischémie massive et brutale — absence de réseau de suppléance → évolue vers l'infarctus transpariétal","Causes : La plus fréquente : embolie sur arythmie cardiaque par fibrillation auriculaire","2. La thrombose (20-30 % des IMA)","Survient sur un terrain athéromateux, patient plus âgé.","Siège préférentiellement au niveau de l'ostium de l'AMS","Le plus souvent progressive, venant compléter une sténose athéromateuse avec une collatéralité déjà en place.","Causes : athérosclérose ; dissection aortique et mésentérique ; syndromes d'hypercoagulabilité et d'hyperviscosité."]},{"titre":"II. Ischémie d'origine non occlusive","badge":"","ancre":"forme-nonOcclusive","blocs":["Cause de 20 à 30 % des IMA","Les lésions d'ischémie prédominent sur les zones de faiblesse (angle iléoccal, angle colique gauche, jonction rectosigmoïdienne)."]},{"titre":"III. L'ischémie veineuse","badge":"","ancre":"forme-veineuse","blocs":["5 à 15 % des IMA.","Peu sévère et de meilleur pronostic que l'ischémie d'origine artérielle.","Le plus souvent réversible sous traitement anticoagulant.","Si elle n'est pas traitée, l'augmentation des pressions veineuses par engorgement → ischémie artérielle secondaire, évoluant vers l'infarcissement, la nécrose et le décès","ThrombophilieCancerCirrhoseInflammation abdominaleContraception/grossesse"]}]},{"id":"semiologie","titre":"Sémiologie TDM — diagnostic positif","rubriques":[{"titre":"A. Signes d'insuffisance vasculaire","badge":"","ancre":"semiologie","blocs":["1. Embole et thrombose artériels","Défaut d'opacification artérielle du tronc cœliaque ou des artères mésentériques.","2. Thrombose veineuse","sans injection","temps portal","Thrombus dans les veines mésentériques spontanément hyperdense sur les coupes sans injection","Orientation étiologique : thrombose des petites veines évoque une cause systémique","Les coupes tardives permettent de s'affranchir des phénomènes de flux"]},{"titre":"3. Vascularite","badge":"","ancre":"semiologie","blocs":["Épaississement sténosant de la paroi vasculaire."]},{"titre":"4. Dissection artérielle","badge":"","ancre":"semiologie","blocs":["Réduction de calibre de la lumière vasculaire avec hématome de paroi. Flap intimal."]},{"titre":"","badge":"","ancre":"semiologie","blocs":["5. IMA non occlusive","Vasospasme diffus mésentérique : diminution de calibre des vaisseaux + irrégularité de calibre","Non visualisation des vaisseaux pariétaux ou des arcades.","Absence d'image de thrombus ou d'embole artériel ou veineux mésentérique.","Images d'infarcissement splénique, hépatique et/ou rénal associées","Confirmation par artériographie"]},{"titre":"B. Signes de souffrance intestinale","badge":"","ancre":"semiologie","blocs":["1. Signes pariétaux — choisissez un signe :"]},{"titre":"","badge":"","ancre":"paroi","blocs":["Épaississement > 3 mm — signe le plus fréquemment observé, surtout dans l'IMA veineuse et non occlusive, lié à l'œdème sous-muqueux ; parfois accompagné d'un rehaussement en cible ; Facteur de bon pronostic : l'œdème mural traduit l'absence de nécrose.","Amincissement : paroi à la limite de la visibilité, surtout IMA artérielle.","Hyperdensité spontanée : densité > muscles pariétaux ou anses adjacentes, liée à la congestion hémorragique sous-muqueuse.","Rehaussement : diminution ou absence, ou rehaussement < anses adjacentes ; Si absence de rehaussement → taux plus élevé de résection chirurgicale.","Pneumatose pariétale — Attention : pneumatose isolée ne veut pas dire nécrose irréversible. Suspecte de nécrose transmurale si associée à aéromésentérie/aéroportie (91 % de nécrose) ou bulles linéaires en bande (vs pneumatose bulleuse).","2. Tube digestif","Dilatation : grêle > 25 mm, côlon > 80 mm — liée à un iléus réflexe et à la nécrose pariétale ; Signe de mauvais pronostic, associé à plus de résection","Feces sign : bulles de gaz + débris fécaux dans une anse grêle dilatée — Aucune valeur sur une anse non dilatée ; surtout utile pour localiser une occlusion mécanique (autre contexte)","3. Mésentère","Infiltration de la graisse mésentérique","Engorgement veineux mésentérique, signe du peigne","Augmentation de densité de la graisse mésentérique"]},{"titre":"","badge":"","ancre":"semiologie","blocs":["Infarctus splénique, rénal et hépatique."]},{"titre":"","badge":"","ancre":"semiologie","blocs":["50 %","50 % des patients avec thrombose de l'AMS développent des emboles extra-mésentériques","Aéromésentérie","Bulles linéaires en bande","Aéroportie"]}]},{"id":"gravite","titre":"Diagnostic de gravité","rubriques":[{"titre":"","badge":"","ancre":"gravite","blocs":["Signes de mauvais pronostic — cochez ceux présents :"]},{"titre":"","badge":"","ancre":"im-gravite","blocs":["0 signe de mauvais pronostic coché","Pas de score dans la fiche : la grille compte simplement les signes cochés. À l'inverse, l'épaississement pariétal œdémateux est un Facteur de bon pronostic."]}]},{"id":"conclusion","titre":"Conclusion","rubriques":[{"titre":"","badge":"","ancre":"conclusion","blocs":["Pathologie digestive grave et mortelle — urgence diagnostique et thérapeutique","Seule l'imagerie peut poser le diagnostic +++ .","signes digestifs+signes vasculaires=diagnostic positif au TDM","Diagnostique","Pronostique","Thérapeutique","Le rôle du radiologue est à la fois diagnostique, pronostique et thérapeutique."]}]}]},{"id":"adenocarcinome-pancreas","url":"fiches/adenocarcinome-pancreas.html","titre":"Adénocarcinome canalaire du pancréas","spe":"digestif","sections":[{"id":"intro","titre":"Introduction & anatomopathologie","rubriques":[{"titre":"","badge":"","ancre":"intro","blocs":["Tumeur solide pancréatique la plus fréquente ; 2e tumeur digestive maligne après le cancer colorectal.","90 % des tumeurs malignes primitives exocrines sont canalaires.","Mauvais pronostic : survie à 5 ans voisine de 5 % ; découverte tardive dans environ 80 % des cas.","Seul traitement curatif : chirurgie.","Siège","Tête60-70 %","Corps20 %","Queue10 %"]}]},{"id":"exploration","titre":"Moyens d'exploration","rubriques":[{"titre":"Échographie","badge":"1","ancre":"exploration","blocs":["Place : 1re intention devant douleur abdominale ou ictère ; très bonne détection de la dilatation biliaire.","Limites : opérateur-dépendante ; obésité et gaz ; queue mal étudiée ; faible sensibilité si tumeur < 2 cm."]},{"titre":"TDM","badge":"2","ancre":"exploration","blocs":["Place : examen de choix des masses solides et du bilan d'extension loco-régional et à distance ; rapide et standardisée.","Limites : irradiation ; injection iodée."]},{"titre":"IRM","badge":"3","ancre":"exploration","blocs":["Place : plus sensible pour petites tumeurs et métastases hépatiques ; meilleure étude canalaire.","Limites : moins disponible ; plus longue ; apnées.","Points techniques : T1 EG FatSat ; T2 ; diffusion ; cholangio-wirsungo-IRM ; dynamique 35 s, 70 s et 5 min."]},{"titre":"Écho-endoscopie","badge":"4","ancre":"exploration","blocs":["Place : 3e intention ; petites lésions, parfois infra-centimétriques ; ponction-biopsie transduodénale.","Limites : invasive."]},{"titre":"CPRE, TEP","badge":"5","ancre":"exploration","blocs":["CPRE : rôle thérapeutique palliatif (prothèse biliaire) ; diagnostic supplanté par la cholangio-IRM.","TEP : intérêt initial non clairement démontré ; recherche de localisations à distance chez l'opéré ; coûteuse et peu disponible."]}]},{"id":"protocoles","titre":"Protocoles & indications ciblées de l'IRM","rubriques":[{"titre":"Protocole TDM pancréatique","badge":"","ancre":"protocoles","blocs":["J-15 min","Préparation : ingestion de 500 mL d'eau 15 minutes avant pour distendre le duodénum.","Sans inj.","Sans injection : calcifications ; lésions hépatiques pour évaluer un éventuel rehaussement.","Iode","Injection iodée 1,5-2 mL/kg, débit 3-5 mL/s.","≈ 45 s","Temps pancréatique : contraste maximal tumeur-parenchyme pancréatique et bilan artério-veineux.","≈ 70 s","Temps portal : foie et cavité abdomino-pelvienne, + bilan veineux ; compléter par l'étage thoracique.","Post-ttt","Reconstructions multiplanaires ; MIP pour les vaisseaux ; minIP pour les voies biliaires et le canal pancréatique."]},{"titre":"Protocole IRM pancréatique","badge":"","ancre":"protocoles","blocs":["Axial T1 EG FatSat (pancréas normal en hypersignal).","Axial T2 TSE FatSat +/- sans FatSat.","Cholangio-wirsungo-IRM.","Diffusion (b0, b1000) avec cartographie ADC.","Séquence axiale T1 en écho de gradient FS dynamique aux temps artériel (35 s), portal (70 s) et tardif (5 min)."]},{"titre":"Indications ciblées de l'IRM","badge":"","ancre":"protocoles","blocs":["Suspicion de tumeur sur signes indirects en TDM sans masse visible.","Suspicion clinique ou biologique de lésion endocrine sécrétante non visible au scanner.","Nature solide ou kystique incertaine ; pancréatite focale versus cancer.","Tumeur jugée résécable en TDM : recherche de métastases hépatiques occultes, infra-cliniques et infra-scannographiques."]}]},{"id":"semiologie","titre":"Sémiologie radiologique","rubriques":[{"titre":"","badge":"","ancre":"semiologie","blocs":["Signes directs = masse elle-même. Signes indirects = retentissement d'amont biliaire, wirsungien et parenchymateux.","Une tumeur isodense ou < 2 cm peut n'être révélée que par les signes indirects."]},{"titre":"Échographie","badge":"","ancre":"semiologie","blocs":["Directs","Masse hypoéchogène, mal limitée, céphalique, déformant ou non la glande ; parfois invisible si < 2 cm.","Indirects","Wirsung > 3 mm ± atrophie d'amont ; dilatation des VBIH, VBEH et de la vésicule biliaire."]},{"titre":"TDM","badge":"","ancre":"semiologie","blocs":["Directs","Masse surtout visible au temps pancréatique : hypodense, irrégulière ; tête globuleuse et perte de l'aspect effilé de l'uncus. Dans 10-15 %, masse isodense.","Indirects","Interruption brutale du Wirsung > 3 mm ; VBP > 7 mm (> 10 mm si sujet âgé ou cholécystectomisé) ; double canal ; atrophie et pseudokyste d'amont."]},{"titre":"IRM","badge":"","ancre":"semiologie","blocs":["Directs","Hyposignal T1 ; iso- ou discret hypersignal T2 ; hypersignal diffusion avec ADC bas ; rehaussement périphérique progressif aux temps portal et tardif.","Indirects","Dilatation bilio-pancréatique et obstacle analysés en cholangio-wirsungo-IRM."]},{"titre":"Exemples en imagerie","badge":"","ancre":"semiologie","blocs":["Masse céphalique hypoéchogèneMasse hypoéchogène, mal limitée de la tête du pancréas, avec dilatation des voies biliaires d'amont.","Masse hypodense au temps pancréatiqueAu temps pancréatique (≈ 45 s), masse hypodense, irrégulière de la tête, mieux visible que sur le parenchyme sain rehaussé.","Signe du double canalDilatation conjointe de la VBP (> 7 mm) et du Wirsung (> 3 mm) avec interruption brutale en regard de la tumeur.","Diffusion / ADCLésion en hypersignal diffusion avec ADC bas, utile pour les petites tumeurs ou les tumeurs isodenses en TDM.","Obstacle bilio-pancréatiqueCholangio-wirsungo-IRM : dilatation bilio-pancréatique d'amont et arrêt net au niveau de l'obstacle céphalique."]}]},{"id":"extension","titre":"Bilan d'extension","rubriques":[{"titre":"1. Extension vasculaire","badge":"","ancre":"extension","blocs":["À rechercher pour le tronc cœliaque (TC), l'AMS, l'AHC, le tronc porte et la VMS : absence de contact ; contact ≤ ou > 180° ; déformation ; sténose ; thrombose / occlusion.","Vaisseau Résécable Borderline Non résécable","AMS Pas de contact. Contact solide < 180°. Contact > 180°.","Tronc cœliaque Pas de contact. Contact tumoral solide ≤ 180°, OU contact tumoral solide > 180° sans impliquer l'aorte, court et reconstructible (uniquement pour les tumeurs du corps / queue). Contact > 180° non reconstructible ou contact avec l'aorte.","AHC Pas de contact. Contact < 180° ou > 180° sans extension au TC ni à la bifurcation hépatique ; segment reconstructible. Extension au TC ou à la bifurcation hépatique.","VP / VMS Pas de contact ou contact < 180° sans irrégularité. Contact > 180° ; ou ≤ 180° avec irrégularité ; ou thrombose courte avec segments sains proximal et distal permettant une reconstruction. Occlusion / atteinte sans reconstruction possible ; atteinte des veines jéjunales proximales.","Critère pronostique et d'opérabilité majeur."]},{"titre":"Exemples d'extension vasculaire","badge":"","ancre":"extension","blocs":["Contact veineux VMS / tronc porteContact tumoral avec la VMS ou le tronc porte : préciser l'angle (≤ ou > 180°), une déformation ou une thrombose, et si une reconstruction est possible.","Engainement de l'AMSContact tumoral solide > 180° autour de l'AMS : critère de non-résécabilité.","Infiltration de la lame rétro-porteInfiltration du plan graisseux entre uncus et AMS, derrière la VMS / tronc porte : marge à haut risque R1."]},{"titre":"Lame rétro-porte","badge":"2","ancre":"extension","blocs":["Infiltration du plan cellulo-graisseux situé derrière VMS / tronc porte, entre uncus et AMS ; marge à haut risque R1.","Point de vigilance : son infiltration annonce un risque très élevé de marge R1 et peut faire proposer un statut borderline ou une stratégie néoadjuvante. Elle n'est pas, à elle seule, une impossibilité technique absolue de résection en l'absence d'atteinte artérielle non résécable."]},{"titre":"Organes de voisinage","badge":"3","ancre":"extension","blocs":["Duodénum, estomac, mésocôlon : perte du plan graisseux de séparation ; envahissement pariétal direct.","Résection en bloc parfois possible."]},{"titre":"4. Extension ganglionnaire","badge":"","ancre":"extension","blocs":["Ganglions péri-pancréatiques, péri-portaux, mésentériques.","Critères de malignité","Taille > 10 mm de petit axe","Morphologie sphérique sans hile graisseux > 5 mm","Contours flous, rupture capsulaire avec graisse infiltrée","Hétérogénéité ou nécrose","Ganglions péri-pancréatiques → n'excluent pas la résection","Ganglions à distance (hile hépatique / mésentérique / rétro-péritonéal) → excluent la résection","Performance de la TDM limitée pour l'analyse ganglionnaire."]},{"titre":"5. Extension à distance","badge":"","ancre":"extension","blocs":["Métastases hépatiques, péritonéales, pulmonaires ou ganglionnaires à distance.","IRM supérieure à la TDM pour les métastases hépatiques. Toute métastase = non résécable."]},{"titre":"Exemple d'extension à distance","badge":"","ancre":"extension","blocs":["Métastases hépatiquesLésions hépatiques en hypersignal diffusion : l'IRM est supérieure à la TDM pour les détecter. Toute métastase = non résécable."]}]},{"id":"resecabilite","titre":"Bilan de résécabilité","rubriques":[{"titre":"Résécable","badge":"","ancre":"resecabilite","blocs":["Résection R0 attendue.","Critères : pas de métastase ; pas d'envahissement artériel TC / AMS / AHC ; contact VP / VMS absent ou < 180° sans déformation.","→ Chirurgie d'emblée."]},{"titre":"Borderline","badge":"","ancre":"resecabilite","blocs":["Potentiellement résécable mais risque élevé de R1 / R2.","Critères : contact artériel limité ou atteinte veineuse reconstructible.","→ Traitement néoadjuvant puis réévaluation."]},{"titre":"Non résécable","badge":"","ancre":"resecabilite","blocs":["Résection R0 impossible.","Critères : engainement artériel majeur / non reconstructible ; atteinte veineuse non reconstructible ; métastases.","→ Traitement palliatif ou néoadjuvant selon contexte."]}]},{"id":"variantes","titre":"Variantes vasculaires à signaler","rubriques":[{"titre":"Sténose du tronc cœliaque","badge":"!","ancre":"variantes","blocs":["Par le ligament arqué ou une plaque d'athérome : perfusion hépatique, gastrique et splénique pouvant dépendre de l'AMS via l'AGD ; sa ligature pendant la DPC expose à l'ischémie / nécrose.","Voir les images en annexe →"]},{"titre":"Artère hépatique droite issue de l'AMS","badge":"!","ancre":"variantes","blocs":["À trajet rétro-portal : risque d'envahissement tumoral et de lésion iatrogène lors de la dissection de la lame rétro-porte."]}]},{"id":"annexe","titre":"Annexe · Cas & images","rubriques":[{"titre":"","badge":"","ancre":"annexe","blocs":["Cas clinique","Homme de 63 ans, adénocarcinome canalaire du pancréas.","Cas annoté · 4 signes typiques en TDM et IRM · variante du tronc cœliaque · diagnostics différentiels"]}]}]},{"id":"maladie-de-crohn","url":"fiches/maladie-de-crohn.html","titre":"Place de l'imagerie dans la maladie de Crohn","spe":"digestif","sections":[{"id":"intro","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"intro","blocs":["Maladie inflammatoire chronique de l'intestin touchant généralement le sujet jeune et évoluant par poussées.","Le tableau clinique typique est fait d'épisodes de diarrhée glairo-sanglante.","L'atteinte digestive prédomine au niveau du côlon droit et de la dernière anse iléale (région iléo-caecale).","L'atteinte est segmentaire et transmurale, pouvant être sténosante et/ou fistulisante.","Le diagnostic repose sur un faisceau d'arguments cliniques, biologiques, endoscopiques, histologiques et radiologiques."]}]},{"id":"objectifs","titre":"Objectifs de l'imagerie","rubriques":[{"titre":"","badge":"","ancre":"objectifs","blocs":["Participer au diagnostic positif.","Préciser la localisation et la longueur des segments atteints.","Rechercher des lésions grêliques non accessibles à l'endoscopie.","Évaluer l'activité inflammatoire.","Déterminer le phénotype : inflammatoire, sténosant ou pénétrant.","Rechercher les complications.","Établir un diagnostic différentiel.","Assurer la surveillance et évaluer la réponse thérapeutique.","Guider le drainage percutané d'un abcès."]}]},{"id":"moyens","titre":"Moyens d'imagerie","rubriques":[{"titre":"Échographie","badge":"1","ancre":"moyens","blocs":["Examen non irradiant, accessible, utilisé pour le diagnostic initial et la surveillance.","Elle étudie : l'épaisseur pariétale (pathologique si > 3 mm), la stratification des couches, la vascularisation pariétale au Doppler, la graisse mésentérique (hypoéchogène homogène), les sténoses, fistules et abcès accessibles.","Avantage : disponibilité, non irradiante, faible coût.","Limites : étude limitée par l'obésité et les gaz digestifs."]},{"titre":"Entéro-IRM","badge":"2","ancre":"moyens","blocs":["Examen de référence pour la cartographie et le suivi évolutif.","Après ingestion d'environ 1 L de contraste oral biphasique pendant 45-60 minutes et administration d'un antispasmodique.","Voir la préparation et les séquences ↓"]},{"titre":"TDM","badge":"3","ancre":"moyens","blocs":["Surtout indiquée en urgence ou si l'IRM et l'échographie ne sont pas disponibles.","L'entéro-IRM et l'échographie sont privilégiées pour le suivi, tandis que la TDM est principalement réservée au contexte aigu.","Voir les protocoles ↓"]},{"titre":"Entéro-IRM : préparation","badge":"","ancre":"moyens","blocs":["À jeun","Patient à jeun.","Avant","Métoclopramide (prokinétique) avant ingestion.","30 min-1 h","Balisage digestif : ingestion fractionnée de 1,5 à 2 L de PEG ou de Mannitol 5 % durant 30 min à 1 h avant l'examen.","Avant gado","Contrôle du péristaltisme : Glucagon (1 mg) en IV avant l'injection de gadolinium."]},{"titre":"Entéro-IRM : séquences","badge":"","ancre":"moyens","blocs":["Coronal FIESTA (± dynamique)","Axial diffusion","Coro 3D T1 avant / après Gado (70 s)","Coro T2 SSFSE sans FAT SAT","Axial T2 SSFSE sans et avec FAT SAT","Axial 3D T1 après injection (5 min)","Coro 3D T1 après injection (8 min)","Séquences cinétiques pour le péristaltisme","Diffusion avec carte ADC","T1 avec saturation de graisse avant / après gadolinium"]},{"titre":"En urgence","badge":"!","ancre":"moyens","blocs":["Acquisition abdominopelvienne injectée au temps portal."]},{"titre":"Hors urgence (suivi)","badge":"↻","ancre":"moyens","blocs":["En cas de contre-indication ou de non-disponibilité de l'IRM → entéro-TDM après distension par contraste oral neutre.","Patient à jeun, sans préparation digestive préalable ; balisage digestif par 1,5 à 2 litres d'eau (Mannitol 5 % ou PEG) ; 2 acquisitions : sans injection et au temps portal."]}]},{"id":"signes","titre":"Signes radiologiques","rubriques":[{"titre":"Échographie","badge":"","ancre":"signes","blocs":["Épaississement pariétal : circonférentiel et symétrique (caractère inflammatoire).","Au stade précoce : épaississement touchant essentiellement la sous-muqueuse, hyperéchogène en rapport avec l'œdème ; hypervascularisation au Doppler.","Graisse péridigestive : hyperéchogène en phase aiguë — diminution de l'échogénicité en phase quiescente.","Signes associés : éventuel épanchement intrapéritonéal, adénomégalies, éventuelle collection en rapport avec un abcès.","Évolution : progression vers la fibrose, dé-différenciation de la paroi digestive, toutes les couches deviennent hypoéchogènes."]},{"titre":"","badge":"","ancre":"signes","blocs":["TDM · Signes d'activité"]},{"titre":"Signes pariétaux","badge":"","ancre":"signes","blocs":["Paroi épaissie (> 4 mm), épaississement segmentaire, généralement circonférentiel et symétrique.","Rehaussement de la muqueuse et, à un degré moindre, de la séreuse (rehaussement en cible / target sign).","Densification de la graisse péridigestive ; engorgement vasculaire (signe du peigne) ; adénomégalies ; épanchement intrapéritonéal."]},{"titre":"Complications","badge":"","ancre":"signes","blocs":["Phlegmon : masse de densité tissulaire, rehaussée après injection.","Abcès : collection hypodense avec rehaussement périphérique.","Trajets fistuleux borgnes ou non (entéro-entérales, entéro-coliques, entéro-vésicales)."]},{"titre":"","badge":"","ancre":"signes","blocs":["TDM · Signes de chronicité","Transformation graisseuse de la sous-muqueuse : signe de la cible avec un halo graisseux (fat-halo sign).","Zones de sténoses étagées avec dilatations post-sténotiques.","Hypertrophie de la graisse mésentérique : sclérolipomatose.","La sacro-iliite est une manifestation extra-intestinale associée."]},{"titre":"Entéro-IRM","badge":"","ancre":"signes","blocs":["Montre les mêmes anomalies que l'entéro-TDM.","L'œdème pariétal est en hypoT1 et hyperT2 avec PDC en cible.","Ulcérations pariétales : profonde (défect pariétal linéaire en hyperT2 et hypoT1 gado) ou transmurale (T2 single shot).","La fibrose pariétale apparaît en hypoT2 avec une prise de contraste diffuse.","Le signe du « peigne » est bien visible sur les séquences T1 avec saturation du signal de la graisse et injection (hypervascularisation mésentérique).","Les masses inflammatoires et les collections sont détectées sur les séquences de diffusion : masses inflammatoires sans signal liquidien ; collections en hypoT1 et hyperT2 avec rehaussement périphérique.","Les trajets fistuleux en hyperT2, plus ou moins rehaussés : bonne détection sur les séquences de diffusion et T1 EG.","Rehaussement pariétal : 3 types","En cocarde→ maladie active","Prédominance muqueuse","Homogène et diffus"]},{"titre":"Exemples en imagerie","badge":"","ancre":"signes","blocs":["Épaississement pariétal iléalParoi de la dernière anse épaissie (> 3 mm), circonférentielle et symétrique, hypervascularisée au Doppler.","Rehaussement en cocardeRehaussement stratifié de la paroi iléale après gadolinium : argument de maladie active.","Signe du peigneHypervascularisation mésentérique en regard du segment atteint, sur T1 FatSat injecté.","Fat-halo signTransformation graisseuse de la sous-muqueuse : signe de chronicité.","Abcès et trajet fistuleuxCollection hypodense à rehaussement périphérique au contact d'un trajet fistuleux : phénotype pénétrant (B3).","Sténose avec dilatation d'amontSegment sténosé avec dilatation post-sténotique : phénotype sténosant (B2)."]}]},{"id":"phenotypes","titre":"Phénotypes & complications","rubriques":[{"titre":"B1","badge":"","ancre":"phenotypes","blocs":["Inflammatoire","Non sténosant et non pénétrant."]},{"titre":"B2","badge":"","ancre":"phenotypes","blocs":["Sténosant"]},{"titre":"B3","badge":"","ancre":"phenotypes","blocs":["Pénétrant","Avec fistule, phlegmon, abcès ou perforation."]},{"titre":"Complications","badge":"","ancre":"phenotypes","blocs":["Sténose et occlusion.","Fistules entéro-entériques, entéro-coliques, entéro-vésicales, entéro-cutanées ou génitales.","Fistules et abcès périnéaux.","Phlegmon et abcès intra-abdominaux.","Perforation, plus rare.","Hémorragie digestive.","Malabsorption et carence en vitamine B12 en cas d'atteinte ou de résection iléale.","Risque tardif d'adénocarcinome colorectal ou du grêle dans les formes anciennes.","Manifestations extra-intestinales : sacro-iliite, cholangite sclérosante, lithiase biliaire ou urinaire."]}]},{"id":"differentiels","titre":"Principaux diagnostics différentiels","rubriques":[{"titre":"","badge":"","ancre":"differentiels","blocs":["Tuberculose iléo-caecale Iléites infectieuses, notamment Yersinia Appendicite et abcès appendiculaire Adénocarcinome caecal ou du grêle Lymphome"]}]}]},{"id":"irm-cancer-rectum","url":"fiches/irm-cancer-rectum.html","titre":"IRM pelvienne dans le cancer du rectum","spe":"digestif","sections":[{"id":"intro","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"intro","blocs":["2e cancer digestif ; 30 % des cancers colorectaux.","Diagnostic clinique et anatomopathologique → diagnostic positif : biopsie par endoscopie.","Mauvais pronostic : risque de récidive locale / métastase à distance.","But de l'imagerie : bilan d'extension pour adapter le traitement → éviter les récidives et être le moins mutilant possible.","IRM +++ pour les cancers du bas et du moyen rectum."]}]},{"id":"bilan","titre":"Imagerie dans le bilan pré-thérapeutique","rubriques":[{"titre":"","badge":"","ancre":"bilan","blocs":["Les indications thérapeutiques dépendent du bilan initial d'imagerie."]},{"titre":"TDM-TAP","badge":"1","ancre":"bilan","blocs":["Bilan d'extension à distance / bilan local des tumeurs du haut rectum."]},{"titre":"± IRM hépatique","badge":"2","ancre":"bilan","blocs":["En complément pour le bilan hépatique."]},{"titre":"Écho-endoscopie","badge":"3","ancre":"bilan","blocs":["Tumeurs superficielles : T1 (sous-muqueuse) et T2 (musculeuse).","Limites : T4 et grosses tumeurs (marge latérale)."]},{"titre":"IRM du rectum","badge":"4","ancre":"bilan","blocs":["Bilan d'extension local du rectum sous-péritonéal (moyen et bas rectum) en vue d'indiquer un traitement néoadjuvant."]}]},{"id":"anatomie","titre":"Rappel anatomique","rubriques":[{"titre":"Rectum : longueur moyenne de 15 cm","badge":"","ancre":"anatomie","blocs":["2 portions : péritonéale et sous-péritonéale.","3 parties, mesurées à partir du faisceau pubo-rectal du muscle releveur de l'anus ou à partir de la marge anale (longueur du canal anal variable : moyenne de 3 cm).","PartieDepuis le faisceau pubo-rectalDepuis la marge anale","Haut> 7 cm> 10 cm","Moyen2-7 cm5-10 cm","Bas< 2 cm< 5 cm"]},{"titre":"Mésorectum","badge":"M","ancre":"anatomie","blocs":["Graisse + structures vasculo-nerveuses.","Délimité par le fascia mésorectal, formé par le fascia recti en dedans et le fascia pelvis en dehors."]},{"titre":"Les fascias","badge":"F","ancre":"anatomie","blocs":["Fascia recti : bande en hyposignal T2 qui entoure le mésorectum ; barrière à la croissance tumorale.","Sous le cul-de-sac de Douglas, le feuillet péritonéal se prolonge par la cloison recto-vaginale chez la femme et par l'aponévrose de Denonvilliers chez l'homme."]},{"titre":"Releveurs de l'anus","badge":"R","ancre":"anatomie","blocs":["3 faisceaux : 1. pubo-rectal ; 2. ilio-coccygien ; 3. pubo-coccygien."]},{"titre":"Sphincters","badge":"S","ancre":"anatomie","blocs":["Externe + interne : ils délimitent un espace inter-sphinctérien."]}]},{"id":"technique","titre":"Technique IRM","rubriques":[{"titre":"","badge":"","ancre":"technique","blocs":["Antenne en réseau phasé","Pas de préparation du rectum","Gel intra-rectal non recommandé, sauf pour la DWI","Centré sur le pelvis : la marge anale et 5 cm au-dessus du bord supérieur de la tumeur"]},{"titre":"Sagittal","badge":"S","ancre":"technique","blocs":["Repérer la tumeur et positionner les plans de coupes HR.","Localisation et étendue de la tumeur.","Marge de résection longitudinale."]},{"titre":"Axial","badge":"A","ancre":"technique","blocs":["Coupes fines perpendiculaires à l'axe de la tumeur.","Extension pariétale et invasion extra-murale EMS (T3 et T4).","Marge de résection circonférentielle (CRM).","Ganglions."]},{"titre":"Coronal","badge":"C","ancre":"technique","blocs":["Coupes fines parallèles à l'axe de la tumeur.","Marge longitudinale.","Ganglions."]},{"titre":"","badge":"","ancre":"technique","blocs":["Bas rectum","Au moins un plan coronal T2 parallèle au canal anal si tumeur du bas rectum.","DWI","Diffusion b 500 + b 1000 axiale perpendiculaire au plan de la tumeur : aide à repérer la tumeur et détecter les ganglions ; diagnostic différentiel avec des pathologies inflammatoires (ADC) ; évaluation post-traitement (résidu tumoral / fibrose).","Ganglions","Axial T2 strict jusqu'aux reins : ganglions.","± Gado","T1 FAT SAT Gado 3D : si bas rectum → sphincters ; si T4 → envahissement des organes de voisinage.","± T1","Axial T1 SE strict."]}]},{"id":"staging","titre":"Sémiologie IRM & staging pré-thérapeutique","rubriques":[{"titre":"","badge":"","ancre":"staging","blocs":["Étapes d'interprétation","Forme","Localisation & mesure","Staging T","Bas rectum","Staging N"]},{"titre":"Forme infiltrante","badge":"1","ancre":"staging","blocs":["La plus classique.","Linite rectale : forme infiltrante particulière, primitive (rare) ou secondaire (à une linite gastrique…).","Infiltration pariétale circonférentielle modérée.","T2 : bonne différenciation des différentes couches de la paroi rectale.","Rehaussement de type fibreux : précoce de la muqueuse et sous-muqueuse, puis tardif de l'ensemble de la paroi +++.","Fibrose péri-tumorale : réaction desmoplastique."]},{"titre":"Forme mucineuse ou colloïde","badge":"4","ancre":"staging","blocs":["Hypersignal T2.","Mauvais pronostic : moins chimio-sensible, plus de récidives."]},{"titre":"","badge":"","ancre":"staging","blocs":["Formes tumoralesCoupes sagittale et axiale T2 illustrant l'aspect morphologique de la tumeur (illustration du cours)."]},{"titre":"","badge":"","ancre":"staging","blocs":["Par rapport à la marge anale ou au faisceau pubo-rectal du muscle releveur de l'anus : haut / moyen / bas rectum.","Si tumeur à cheval entre deux segments : c'est le pôle inférieur de la tumeur qui définit le segment rectal concerné.","Pour le haut rectum : par rapport au cul-de-sac de Douglas → péritonisé ou sous-péritonéal.","Antérieure / postérieure / latérale droite ou gauche.","Envahissement de la circonférence : ¼, ½ ou ¾ circonférentielle + rayon horaire.","Mesure de la tumeur dans les 3 plans."]},{"titre":"3. Staging T : extension pariétale","badge":"","ancre":"staging","blocs":["Tx non évaluable","T0 pas de tumeur","Tis carcinome in situ"]},{"titre":"T1 · Sous-muqueuse","badge":"","ancre":"staging","blocs":["Tumeur que l'on peut à tout endroit différencier de la couche musculaire de la paroi rectale.","La musculeuse : bande en hyposignal T2 intense.","Stade T1Tumeur séparée sur toute sa circonférence de la musculeuse, qui reste en hyposignal T2 intense."]},{"titre":"T2 · Musculeuse","badge":"","ancre":"staging","blocs":["Couche musculaire envahie sans infiltration de la graisse du mésorectum.","Stade T2Envahissement de la musculeuse, graisse mésorectale respectée."]},{"titre":"T3 · Mésorectum","badge":"","ancre":"staging","blocs":["Envahissement du mésorectum.","Piège : discontinuité de la musculeuse (vaisseaux perforants) et spiculations péri-rectales : spicules non tumorales (réaction desmoplastique bénigne) ou tumorales.","Stade T3Extension tumorale dans la graisse du mésorectum (têtes de flèche orange)."]},{"titre":"T4 · Au-delà du fascia recti","badge":"","ancre":"staging","blocs":["Envahissement du fascia recti avec envahissement du péritoine viscéral (T4a) ou des organes de voisinage (T4b)."]},{"titre":"","badge":"","ancre":"staging","blocs":["Staging TT1 sous-muqueuse, T2 musculeuse, T3 mésorectum, T4 organes de voisinage.","L'IRM a tendance à sous-estimer les stades T1-T2 et à surestimer les stades T3-T4."]},{"titre":"Invasion extra-murale (EMS)","badge":"","ancre":"staging","blocs":["= importance de l'extension tumorale dans la graisse péri-rectale à partir de la couche musculaire pariétale.","T3 faible","T3a< 1 mm","T3b1-5 mm","T3 fort","T3c5-15 mm","T3d> 15 mm"]},{"titre":"Marge circonférentielle (CRM)","badge":"","ancre":"staging","blocs":["= la plus petite distance entre la tumeur et le fascia du mésorectum.","Peut être mesurée pour les tumeurs T1 et T2, mais utile surtout pour les tumeurs T3.","Ne s'applique pas aux tumeurs situées au-dessus du péritoine.","Les ganglions doivent être pris en compte si on est sûr de leur caractère tumoral.","Peut être calculée sur une spicule à l'anatomopathologie, mais pas en IRM.","CRM envahie si < 1 mm · facteur pronostique majeur"]},{"titre":"","badge":"","ancre":"staging","blocs":["CRM et EMS · tumeur T1CRM (vert) mesurée jusqu'au fascia recti ; distinction ganglion suspect / non suspect.","CRM et EMS · tumeur T3EMS (jaune) mesurée depuis la musculeuse ; CRM (vert) jusqu'au fascia recti.","Exemple de mesureMesure sur coupe axiale (1,64 cm), illustrant l'évaluation de l'extension dans le mésorectum."]},{"titre":"Marge de résection longitudinale","badge":"","ancre":"staging","blocs":["Distance du bord inférieur de la tumeur au bord supérieur du sphincter anal, en précisant la longueur du canal anal."]},{"titre":"","badge":"","ancre":"staging","blocs":["Coronales T2 et T1 fat sat Gado sur le canal anal.","Marge latérale","CRM mesurée par rapport au plan de clivage entre le faisceau ilio-coccygien et la tumeur.","> 1 mm ou < 1 mm.","Marge distale","Sphincter interne (SI), sphincter externe (SE).","Infiltration de l'espace inter-sphinctérien."]},{"titre":"","badge":"","ancre":"staging","blocs":["CRM au bas rectumCoupe coronale T2 sur le canal anal : marge latérale (CRM) mesurée par rapport au plan de clivage avec le faisceau ilio-coccygien."]},{"titre":"5. Staging ganglionnaire","badge":"","ancre":"staging","blocs":["Nxnon évaluable N0pas d'atteinte ganglionnaire N11 à 3 ganglions métastatiques régionaux N1cdépôts tumoraux (anapath) N2≥ 4 ganglions métastatiques régionaux","Ganglions régionaux","Ganglions du mésorectum.","Ganglions pré-sacrés et du promontoire.","Ganglions mésentériques inférieurs.","Ganglions iliaques internes.","Métastases à distance","Ganglions iliaques externes, inguinaux et obturateurs : considérés comme des métastases à distance."]},{"titre":"Ganglions suspects : taille","badge":"","ancre":"staging","blocs":["Mésorectal > 5 mm de petit axe","Iliaque interne > 7 mm","Iliaque externe > 10 mm"]},{"titre":"Critères morphologiques +++","badge":"","ancre":"staging","blocs":["Irrégularité des contours, spiculations","Rapport petit axe / grand axe > 1,5 (arrondi)","Hétérogénéité de signal","Interruption de la capsule"]},{"titre":"Envahissement veineux extra-mural (EMVI)","badge":"","ancre":"staging","blocs":["Présence de cellules tumorales dans les vaisseaux au-delà de la musculeuse.","Vaisseau à proximité de la tumeur, augmenté de calibre, de signal intermédiaire T2, aux contours irréguliers.","S'associe à un haut risque métastatique et de récidive."]}]},{"id":"pronostic","titre":"Facteurs de mauvais pronostic","rubriques":[{"titre":"","badge":"","ancre":"pronostic","blocs":["→ Haut risque de récidive.","Stade T3 fort, T4","CRM < 1 mm","N+ / dépôt tumoral (IRM hépatique, PET)","Invasion veineuse","Dépôt tumoral (N1c)","Envahissement de l'espace inter-sphinctérien"]}]},{"id":"post-traitement","titre":"Évaluation post-traitement néoadjuvant","rubriques":[{"titre":"Quoi & pourquoi","badge":"?","ancre":"post-traitement","blocs":["RT ou RCT.","Buts : diminuer le taux de récidive locale ; améliorer la résécabilité ; modifier la prise en charge chirurgicale."]},{"titre":"Pour qui","badge":"!","ancre":"post-traitement","blocs":["Tumeurs évoluées : T3 avec CRM infra-millimétrique, T4 et N+."]},{"titre":"Quand & comment","badge":"⏱","ancre":"post-traitement","blocs":["6 à 8 (8-10) semaines après la fin du traitement.","Examen clinique, TAP, IRM, imagerie dédiée si patient M+ (IRM hépatique).","Même protocole qu'en pré-thérapeutique : diffusion +++."]},{"titre":"Apport de la diffusion","badge":"","ancre":"post-traitement","blocs":["Aide à la distinction entre résidu tumoral et fibrose cicatricielle au sein d'un épaississement résiduel post-RCT.","Un ADC élevé est corrélé à une diminution de la cellularité et à la réponse tumorale.","Améliore l'évaluation de la CRM.","Améliore la détection des ganglions, mais pas leur caractérisation (trop petits pour une mesure fiable de l'ADC).","Limite : les formes mucineuses ont un ADC non diminué."]},{"titre":"Critères recommandés par le groupe MERCURY","badge":"","ancre":"post-traitement","blocs":["Aspect morphologique de la tumeur, y compris zones de mucine ou de nécrose","Hauteur tumorale par rapport à la marge anale","Longueur tumorale : down-sizing","Grade de régression tumorale IRM (mrTRG)","Extension extramurale maximale (tumeur et zones de fibrose)","Staging pariétal : stade T, downstaging","Évaluation des marges de résection","Envahissement veineux extra-mural (EMVI)","Staging ganglionnaire : down-staging N"]},{"titre":"1. Aspect de la tumeur : 3 types de réponse + l'œdème","badge":"","ancre":"post-traitement","blocs":["Réponse fibreuse Stroma fibreux en hyposignal T2, similaire au signal de la musculeuse. Résidu tumoral au sein de la fibrose : signal intermédiaire.","Réponse desmoplastique Fines spicules hypointenses dans la graisse péri-rectale, irradiant à partir du résidu tumoral. Over-staging tumoral.","Réponse colloïde Nécrose de la tumeur avec transformation colloïde ou mucineuse. Rend difficile l'évaluation du résidu ; impossible de distinguer colloïde acellulaire et pauci-cellulaire. À ne pas confondre avec les tumeurs mucineuses (hyperT2 sur l'IRM initiale).","Œdème post-thérapeutique Peut avoir un aspect pseudo-tumoral. Signal intermédiaire : inflammation de la sous-muqueuse adjacente à la tumeur. Risque de faux positif, mais cette zone est sus- ou sous-jacente à la tumeur (IRM initiale).","Résidu tumoralFibroseRéaction desmoplastique","T1HyposignalHyposignalHyposignal","T2 Similaire à celui de la tumeur initialeHyposignalHyposignal","Diffusion HypersignalHyposignalHyposignal","GadoliniumPrise de contrastePDC si inflammatoirePrise de contraste"]},{"titre":"2. Grade de régression tumorale en IRM (mrTRG)","badge":"","ancre":"post-traitement","blocs":["Calqué sur la classification anatomopathologique de Dworak. Repose sur la modification du signal tumoral et le développement de plages de fibrose en hyposignal T2 ou de mucine en hypersignal T2.","TRG 1Réponse radiologique complète : absence de signal tumoral.","TRG 2Bonne réponse : prédominance de fibrose ou mucine avec minime résidu de signal tumoral.","TRG 3Réponse modérée : > 50 % fibrose ou mucine et persistance de signal tumoral.","TRG 4Réponse faible : tumeur > fibrose ou mucine.","TRG 5Absence de modification par rapport à l'IRM pré-thérapeutique."]},{"titre":"3. Down-staging ganglionnaire","badge":"","ancre":"post-traitement","blocs":["Critères de réponse en IRM :","1Taille 2Contours 3Signal (fibrose)"]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture."]},{"titre":"CR pré-thérapeutique","badge":"","ancre":"compte-rendu","blocs":["Tumeur","Extension","Si cancer du bas rectum","Ganglions & staging"]}]}]},{"id":"irm-prostate-diagnostic","url":"fiches/irm-prostate-diagnostic.html","titre":"IRM de la prostate : diagnostic du cancer","spe":"uro","sections":[{"id":"commandements","titre":"Les 7 commandements","rubriques":[{"titre":"","badge":"","ancre":"commandements","blocs":["AIRM multiparamétrique (biparamétrique possible si patient naïf de biopsies et sans facteur de risque).","BÉvaluer la qualité de l'examen : PI-QUAL (→ II).","CMesurer la glande et calculer la densité de PSA (PSAd).","DDécrire le signal « de fond » (→ III).","EAnalyser successivement : ZP, ZT, SFMA, lobe médian, VS.","FAnalyser les images significatives : 1) PI-RADS v2.1 = zone, taille (mm), score, extension ; 2) PRECISE pour la surveillance active ; 3) Likert si prostate traitée ou « impression » différente du PI-RADS ; 4) PI-RR pour les récidives.","GUn compte rendu standardisé incluant le schéma (www.pcih.fr/portal).","ZP zone périphérique ZT zone de transition SFMA stroma fibromusculaire antérieur (AS) ZC zone centrale (CZ) VS vésicules séminales"]}]},{"id":"pi-qual","titre":"Qualité de l'examen : PI-QUAL","rubriques":[{"titre":"","badge":"","ancre":"pi-qual","blocs":["PI-QUAL (Giganti, Insights Imaging, 2021) : qualité diagnostique des séquences de l'IRM multiparamétrique (T2, diffusion, perfusion).","PI-QUAL","Critères","Implications cliniques","Toutes les séquences sont en dessous du standard minimal de qualité diagnostique","Impossible d'affirmer toutes les lésions significatives","Impossible d'exclure tous les cancers significatifs*","Une seule séquence est de qualité diagnostique acceptable","Au moins deux séquences, prises ensemble, sont de qualité diagnostique","Possible d'affirmer toutes les lésions significatives","Impossible d'exclure tous les cancers significatifs","Deux séquences ou plus sont indépendamment de qualité diagnostique"]}]},{"id":"glande","titre":"Glande, PSAd et signal de fond","rubriques":[{"titre":"Mesurer la glande","badge":"","ancre":"glande","blocs":["Trois diamètres : transverse × antéro-postérieur × crânio-caudal.","Volume (ellipsoïde) = L × l × h × 0,52.","PSAd = PSA / volume (ng/mL/cm³)."]},{"titre":"Signal « de fond » de la ZP","badge":"","ancre":"glande","blocs":["Bura, Eur Radiol, 2021.","1Presque tout est en hypersignal T2.","2Quelques plages linéaires de signal intermédiaire (1 à 2 secteurs).","3Multiples plages linéaires ou triangulaires de signal intermédiaire (≥ 3 secteurs).","4Multiples plages très hétérogènes ou hyposignal diffus."]}]},{"id":"pirads","titre":"Score PI-RADS v2.1","rubriques":[{"titre":"","badge":"","ancre":"pirads","blocs":["Pour chaque image significative : zone, taille (mm), score, extension. La séquence dominante dépend de la zone."]},{"titre":"Zone périphérique : séquence dominante = diffusion","badge":"","ancre":"pirads","blocs":["1Aucune anomalie.","2Image linéaire ou angulaire.","3Image focale, restriction modérée (peut être marquée, mais sur une seule des deux images de diffusion : b élevé ou ADC).","4Image focale < 15 mm, restriction marquée.","5Image focale ≥ 15 mm, restriction marquée, ou extension extraprostatique (EEP).","Dominante","Accessoire","PI-RADS","Diffusion","Perfusion (DCE)","Négative","Positive(nettement)"]},{"titre":"Zone de transition : séquence dominante = T2","badge":"","ancre":"pirads","blocs":["1Nodule parfaitement encapsulé, ou ZT homogène normale (rare).","2Nodule presque complètement encapsulé ; nodule circonscrit homogène non encapsulé ; nodule circonscrit homogène hypointense.","3Image hétérogène avec contours incertains (et tout ce qui n'est pas 2, 4 ou 5).","4Image lenticulaire ou non circonscrite, homogène, de signal intermédiaire, < 15 mm.","5Idem ≥ 15 mm, ou extension extraprostatique (EEP).","Dominante","Accessoire","PI-RADS","Diffusion","1 à 3","4 ou 5(restriction marquée)","2 + 1 = 3"]},{"titre":"","badge":"","ancre":"pirads","blocs":["Seuil de 15 mm entre les scores 4 et 5 ; une extension extraprostatique classe d'emblée la lésion en 5."]}]},{"id":"cartographie","titre":"Cartographie sectorielle","rubriques":[{"titre":"","badge":"","ancre":"cartographie","blocs":["Localiser chaque lésion sur le schéma : niveau (base, milieu, apex), côté et secteur. Coupes axiales, vue sagittale et vue coronale.","LPZ = PZpl (postérolatérale) MPZ = PZpm (postéromédiale) APZ = PZa (antérieure) PTZ = TZp ATZ = TZa AFS = AS (SFMA)","Le calculateur PI-RADS de la page Comptes rendus place les lésions sur ce même schéma (axial, sagittal, coronal) et rédige le texte."]}]},{"id":"scores","titre":"Autres scores selon la situation","rubriques":[{"titre":"PI-RADS v2.1","badge":"1","ancre":"scores","blocs":["Diagnostic : zone, taille (mm), score, extension."]},{"titre":"PRECISE","badge":"2","ancre":"scores","blocs":["Patients en surveillance active."]},{"titre":"Likert","badge":"3","ancre":"scores","blocs":["Prostate traitée ou « impression » différente du PI-RADS."]},{"titre":"PI-RR","badge":"4","ancre":"scores","blocs":["Récidives."]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture."]},{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Technique et qualité","Glande","Pour chaque lésion","Synthèse"]}]}]},{"id":"irm-prostate-extension","url":"fiches/irm-prostate-extension.html","titre":"IRM de la prostate : bilan d'extension","spe":"uro","sections":[{"id":"savoir","titre":"À savoir","rubriques":[{"titre":"","badge":"","ancre":"savoir","blocs":["L'IRM améliore le pronostic chirurgical : modification de la technique, préservation nerveuse, diminution des R1.","Il n'existe pas de vraie capsule : parler d'extension extraprostatique plutôt que d'« extension extracapsulaire ».","Autres indicateurs de l'extension : volume lésionnel, Gleason (ISUP), valeur de l'ADC."]}]},{"id":"tnm","titre":"Classification TNM 2016","rubriques":[{"titre":"","badge":"","ancre":"tnm","blocs":["T1(TR− / IRM−)","T1a : tumeur < 5 % du tissu réséqué avec Gleason < 7 ou absence de grade 4 ou 5","T1b : tumeur > 5 % du tissu réséqué ou Gleason > 7 ou grade 4 ou 5 présent","T1c : tumeur découverte sur biopsie pour élévation du taux de PSA","T2(limitée à la prostate)","T2a : tumeur < ½ lobe","T2b : tumeur > ½ lobe","T2c : atteinte des 2 lobes","T3(au-delà de la prostate)","T3a : extension extraprostatique uni- ou bilatérale","T3b : extension à la (aux) vésicule(s) séminale(s)","Tumeur fixée ou atteignant d'autres structures que les VS : sphincter externe, rectum, muscle élévateur de l'anus, paroi pelvienne"]}]},{"id":"it3a","titre":"Extension extraprostatique : iT3a","rubriques":[{"titre":"","badge":"","ancre":"it3a","blocs":["50 % d'iT3a sur les prostatectomies ; 10 à 15 % pour les cancers de bas risque et 45 à 50 % pour les cancers à haut risque."]},{"titre":"Les signes sémiologiques sont nombreux","badge":"","ancre":"it3a","blocs":["Contact de la tumeur ≥ 10 mm (ou 15…) avec la capsule.","Irrégularité de la capsule.","Bombement de la capsule.","Rétraction ou spiculation de la capsule.","Asymétrie des bandelettes neurovasculaires.","Comblement de l'angle prostato-vésiculaire.","Extension extraprostatique mesurable : se mesure par une distance radiale en mm.","L'extension extraprostatique iT3 peut être décrite par des signes sémiologiques, mais doit être quantifiée par un score EPE."]},{"titre":"Le score EPE : incontournable pour l'extension iT3a","badge":"","ancre":"it3a","blocs":["Score EPE","2 (1 + 1)","Schéma","Signes IRM","Aucun des signes","Contact capsulaire ≥ 15 mm","Bombement ou irrégularité de la capsule","Les deux signes du score 1 combinés","Brèche extraprostatique évidente","Se T3a","24,3 %","38,2 %"]}]},{"id":"it3b","titre":"Vésicules séminales : iT3b","rubriques":[{"titre":"","badge":"","ancre":"it3b","blocs":["3 jours d'abstinence éjaculatoire avant l'examen.","Score de Likert 1 à 5 (selon PI-RADS) : VPP [3-5] : 90 % ; VPN [1-2] : 93 %.","Séquences clés : perfusion (DCE) et diffusion ; l'extension aux vésicules séminales est meilleure avec l'injection (IRM multiparamétrique > biparamétrique).","Bien observer les canaux éjaculateurs.","Analyser les images dans les 3 plans, ou en MPR +++.","Forcément associée à une lésion basale (sinon…).","Être encore plus vigilant sur le N+."]},{"titre":"","badge":"","ancre":"it3b","blocs":["● Directe via les canaux éjaculateurs · ● Via une brèche capsulaire basale et la graisse · ● Métastatique (rare)"]}]},{"id":"it4","titre":"Organes de voisinage : iT4","rubriques":[{"titre":"","badge":"","ancre":"it4","blocs":["1Sphincter urétral 2Col vésical 3Rectum 4Paroi pelvienne / muscles releveurs de l'anus"]}]},{"id":"in","titre":"Extension ganglionnaire : iN","rubriques":[{"titre":"","badge":"","ancre":"in","blocs":["IRM","Taille > 8 mm : chaînes obturatrices","Taille > 10 mm : chaînes lombo-aortiques","Forme ronde plutôt qu'ovale","TEP-choline","Si haut risque M+ d'Amico","Avant radiothérapie (recrutement des lésions à inclure)","TEP-PSMA","Indiquée si TEP-choline négative"]}]},{"id":"im","titre":"Extension à distance : iM","rubriques":[{"titre":"","badge":"","ancre":"im","blocs":["Scintigraphie osseuse","Si haut risque d'Amico","Ou risque intermédiaire et grade 4 majoritaire","Ou douleurs osseuses","Scanner TAP","Si envahissement ganglionnaire significatif ou si atteinte osseuse"]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture."]},{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Extension locale","Ganglions et à distance","Synthèse"]}]}]},{"id":"masses-renales-kystiques","url":"fiches/masses-renales-kystiques.html","titre":"Masses rénales kystiques : Bosniak 2019","spe":"uro","sections":[{"id":"savoir","titre":"À savoir","rubriques":[{"titre":"","badge":"","ancre":"savoir","blocs":["Une masse kystique contient moins de 25 % de tissu rehaussé. Au-delà, c'est une masse solide : elle sort de la classification.","Hors Bosniak aussi : les lésions infectieuses, inflammatoires ou vasculaires et les syndromes héréditaires.","La version 2019 classe au scanner et en IRM, et donne une définition chiffrée de chaque terme.","On ne compte que ce qui se rehausse : paroi, cloisons et protrusions s'évaluent après injection.","Ordre de lecture : on cherche les critères de IV, puis III, IIF, II et enfin I ; la catégorie la plus haute atteinte l'emporte."]},{"titre":"Le vocabulaire de 2019","badge":"","ancre":"savoir","blocs":["Terme","Définition","Paroi ou cloison fine","≤ 2 mm","Discrètement épaissie","3 mm, lisse","Épaisse","≥ 4 mm","Peu / nombreuses cloisons","1 à 3 / 4 ou plus","Irrégularité","Protrusion (bombement convexe) ≤ 3 mm à angle obtus"]}]},{"id":"categories","titre":"Les 5 catégories","rubriques":[{"titre":"","badge":"","ancre":"categories","blocs":["Rein en gris, kyste en noir ; la paroi, les cloisons et la protrusion prennent la couleur de la catégorie."]},{"titre":"Kyste simple · bénin","badge":"I","ancre":"categories","blocs":["Paroi fine (≤ 2 mm) et lisse.","Liquide homogène : −9 à 20 UH au scanner, signal du LCR en IRM.","Ni cloison ni calcification.","Conduite : pas de suivi."]},{"titre":"Kyste bénin","badge":"II","ancre":"categories","blocs":["1 à 3 cloisons fines (≤ 2 mm) ; calcifications de tout type.","Scanner, kyste homogène : −9 à 20 UH ou ≥ 70 UH sans injection ; > 20 UH sans rehaussement ; 21 à 30 UH au temps portal ; trop petit pour être caractérisé.","IRM, kyste homogène : hypersignal T2 ≈ LCR (sans injection) ou hypersignal T1 ≥ 2,5 × rein.","Conduite : pas de suivi."]},{"titre":"À surveiller","badge":"IIF","ancre":"categories","blocs":["Paroi lisse, discrètement épaissie (3 mm), rehaussée.","Une ou plusieurs cloisons lisses de 3 mm, rehaussées.","4 cloisons fines ou plus, rehaussées.","IRM : hypersignal T1 hétérogène en saturation de graisse.","Conduite : contrôle à 6 et 12 mois, puis annuel jusqu'à 5 ans."]},{"titre":"Malignité intermédiaire","badge":"III","ancre":"categories","blocs":["Paroi ou cloison rehaussée épaisse (≥ 4 mm).","Ou irrégulière : protrusion rehaussée ≤ 3 mm à angle obtus, quelle que soit l'épaisseur.","Conduite : chirurgie ou surveillance active selon l'âge et les comorbidités."]},{"titre":"Malignité jusqu'à 90 %","badge":"IV","ancre":"categories","blocs":["Nodule rehaussé : protrusion ≥ 4 mm à angle obtus.","Ou protrusion rehaussée à angle aigu, quelle que soit sa taille.","Conduite : avis urologique."]}]},{"id":"hyperdense","titre":"Kyste hyperdense : Bosniak II","rubriques":[{"titre":"","badge":"","ancre":"hyperdense","blocs":["Un kyste hyperdense homogène reste un Bosniak II (bénin, sans suivi) s'il remplit l'un de ces critères :"]},{"titre":"","badge":"","ancre":"hyperdense","blocs":["Plus de 70 UH sans injection.","Hyperdense (vers 50 UH) sans rehaussement après injection (variation inférieure à 10 UH).","En IRM : hypersignal T1 avec un rapport de signal lésion / rein ≥ 2,5.","Volumineux (> 3 cm) et endophytique : IRM recommandée."]}]},{"id":"rehaussement","titre":"Rehausse ou pas ?","rubriques":[{"titre":"","badge":"","ancre":"rehaussement","blocs":["Différence de densité entre le temps sans injection et le temps portal, mesurée au même endroit.","Différence (Δ)","Interprétation","< 10 UH","Pas de rehaussement","10 à 19 UH","Zone grise : IRM conseillée","≥ 20 UH","Rehaussement"]},{"titre":"","badge":"","ancre":"rehaussement","blocs":["Sans injection, le rehaussement d'une paroi, d'une cloison ou d'une protrusion ne s'évalue pas : compléter par un scanner ou une IRM avec injection.","Rehaussement franc d'une lésion d'aspect homogène : penser à une masse solide."]}]},{"id":"pieges","titre":"Pièges","rubriques":[{"titre":"","badge":"","ancre":"pieges","blocs":["Cloison lisse de 3 mm rehaussée = IIF, pas III : le III commence à 4 mm ou à l'irrégularité.","Protrusion de 2 mm à angle aigu = IV : l'angle aigu fait le nodule, quelle que soit la taille.","Protrusion ≤ 3 mm à angle obtus = III (irrégularité), pas IV.","Les calcifications ne font pas monter la catégorie (II) ; épaisses ou nodulaires, elles masquent le rehaussement : IRM conseillée avant de classer.","Une structure qui ne se rehausse pas ne compte pas.","L'IRM reclasse environ 17 % des IIF du scanner en III."]}]},{"id":"conduite","titre":"Conduite à tenir","rubriques":[{"titre":"","badge":"","ancre":"conduite","blocs":["I · II","Bénin : pas de suivi.","IIF","Contrôle à 6 et 12 mois, puis annuel jusqu'à 5 ans. Une IRM peut précéder le premier contrôle.","III","Chirurgie (tumorectomie chez le patient jeune) ou surveillance active selon l'âge et les comorbidités.","Malignité jusqu'à 90 % : avis urologique."]},{"titre":"Pourquoi surveiller un III ?","badge":"","ancre":"conduite","blocs":["Beaucoup de lésions III sont des tumeurs kystiques multiloculaires bénignes ou de bas potentiel de malignité, souvent indolentes :","néphrome kystique (tumeur mixte épithéliale et stromale) ;","tumeur rénale papillaire à cellules claires ;","néoplasme kystique multiloculaire de bas potentiel de malignité ;","carcinome rénal éosinophile solide et kystique ;","carcinome tubulo-kystique."]},{"titre":"Biopsie","badge":"","ancre":"conduite","blocs":["À éviter devant une tumeur kystique, sauf s'il existe une composante tissulaire solide significative."]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture. Dans l'éditeur des comptes rendus, l'outil Bosniak rédige la description et la conclusion."]},{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Lésion","Critères","Conclusion"]}]}]},{"id":"myome-uterin","url":"fiches/myome-uterin.html","titre":"Le myome utérin dans tous ses états","spe":"femme","sections":[{"id":"generalites","titre":"Généralités","rubriques":[{"titre":"Le myome","badge":"","ancre":"generalites","blocs":["Pathologie bénigne de l'utérus.","Tumeur faite de cellules musculaires lisses et de tissu fibreux conjonctif.","Fréquente : 25 % des femmes en période d'activité génitale.","Hormono-dépendante : augmente de taille pendant la grossesse, involue après la ménopause."]},{"titre":"Clinique","badge":"","ancre":"generalites","blocs":["Souvent asymptomatique, de découverte fortuite.","Symptômes : douleurs pelviennes, métrorragies, infertilité."]}]},{"id":"protocole","titre":"Échographie, IRM et protocole","rubriques":[{"titre":"","badge":"","ancre":"protocole","blocs":["L'échographie par voie endovaginale reste l'examen de première intention."]},{"titre":"Indications de l'IRM (cartographie)","badge":"","ancre":"protocole","blocs":["Myomes nombreux (> 5).","Myome volumineux (> 10 cm).","Myome difficilement explorable en échographie (ex. : sous-séreux).","Myome atypique en échographie."]},{"titre":"Intérêts de l'IRM","badge":"","ancre":"protocole","blocs":["Meilleure cartographie : nombre, taille, localisation.","Caractérisation tissulaire : myome simple, remanié, en dégénérescence.","Diagnostic différentiel : sarcome utérin.","Lésions associées : adénomyose, endométriose…","Bilan préthérapeutique."]},{"titre":"Protocole IRM","badge":"","ancre":"protocole","blocs":["Séquences","Réalisation","3 plans T2.","T1 sans et avec suppression du signal de la graisse.","Diffusion","b0 et b1000, avec cartographie ADC.","Injection","± T1 après injection de chélates de gadolinium (si myome atypique)."]}]},{"id":"figo","titre":"Cartographie : classification FIGO","rubriques":[{"titre":"","badge":"","ancre":"figo","blocs":["Initialement décrite en échographie, la classification FIGO s'utilise aussi en IRM : elle décrit la position du myome par rapport à la muqueuse et à la séreuse, ce qui oriente le choix thérapeutique.","Catégorie","Type","Description","Sous-muqueux","Intracavitaire pédiculé","< 50 % intramural","> 50 % intramural","Interstitiel","Intramural au contact de la muqueuse","Intramural","Sous-séreux"]}]},{"id":"simple","titre":"Myome utérin simple (non remanié)","rubriques":[{"titre":"","badge":"","ancre":"simple","blocs":["Morphologie","Masse arrondie, aux contours circonscrits.","Hyposignal T2.","Isosignal T1 par rapport au myomètre.","Diffusion","Hyposignal en diffusion b1000.","Après injection","Rehaussement homogène et parallèle au myomètre."]}]},{"id":"degenerescences","titre":"Dégénérescences des myomes","rubriques":[{"titre":"","badge":"","ancre":"degenerescences","blocs":["Quatre types : hyaline, kystique, myxoïde et nécrobiose aseptique (« red degeneration »)."]},{"titre":"Dégénérescence hyaline","badge":"","ancre":"degenerescences","blocs":["La plus fréquente : jusqu'à 60 % des myomes.","IRM : hyposignal T2, absence de rehaussement après injection.","Après embolisation : le myome est dévascularisé, ne se rehausse plus et prend l'aspect d'une dégénérescence hyaline."]},{"titre":"Dégénérescence kystique","badge":"","ancre":"degenerescences","blocs":["Échographie : myome hétérogène avec portions anéchogènes.","IRM : hypersignal T2, pas de rehaussement des portions kystiques."]},{"titre":"Dégénérescence myxoïde","badge":"","ancre":"degenerescences","blocs":["Rare.","IRM : hétérogène, isosignal T1, portions en hypersignal T2 qui se rehaussent après injection, pas de restriction de la diffusion.","Attention : une dégénérescence myxoïde peut s'observer dans un léiomyosarcome : vérifier l'absence de signe de malignité."]},{"titre":"Nécrobiose aseptique","badge":"","ancre":"degenerescences","blocs":["Contexte de douleurs pelviennes.","IRM : hypersignal T1 diffus ou périphérique, signal T2 variable, pas de rehaussement."]}]},{"id":"remaniements","titre":"Remaniements des myomes","rubriques":[{"titre":"Hémorragique","badge":"1","ancre":"remaniements","blocs":["IRM : hypersignal T1, persistant après suppression du signal de la graisse."]},{"titre":"Lipoléiomyome","badge":"2","ancre":"remaniements","blocs":["Remaniement graisseux, parfois considéré comme une variante histologique.","Écho : hyperéchogène, atténuation postérieure, peu vascularisé en Doppler couleur.","TDM : masse bien limitée de contenu graisseux.","IRM : hypersignal T1 et T2, hyposignal T1 Fat Sat."]},{"titre":"Myome calcifié","badge":"3","ancre":"remaniements","blocs":["TDM : calcifications périphériques.","IRM : absence de signal périphérique sur l'ensemble des séquences."]}]},{"id":"sarcome","titre":"Myome cellulaire et léiomyosarcome","rubriques":[{"titre":"Myome cellulaire","badge":"","ancre":"sarcome","blocs":["IRM : contours réguliers, hypersignal T2, isosignal T1, rehaussement intense.","ADC > 1,2 × 10⁻³ mm²/s.","Diagnostic différentiel : léiomyosarcome."]},{"titre":"Léiomyosarcome","badge":"","ancre":"sarcome","blocs":["Lésion","Unique, volumineuse.","Contours","Irréguliers.","Injection","Fort rehaussement.","Remaniements","Internes nécrotico-hémorragiques.","Diffusion","Hypersignal, avec ADC < 0,8 × 10⁻³ mm²/s (signe non toujours présent)"]}]},{"id":"arbre","titre":"Arbre décisionnel et messages à retenir","rubriques":[{"titre":"","badge":"","ancre":"arbre","blocs":["On part du signal T2 du myome, puis du rehaussement ou du signal T1, et en signal T2 intermédiaire de l'ADC. Survolez une case pour suivre son chemin ; un clic mène à la partie de la fiche.","Signal T2 du myome","Hyposignal T2","Rehaussement homogène","Myome simple","Pas de rehaussement","Dégénérescence Hyalineaussi après embolisation","Hypersignal T2","Rehaussement hétérogène","Dégénérescence Myxoïdeéliminer un sarcome","Dégénérescence Kystique","Signal T2 intermédiaire"]},{"titre":"Take home messages","badge":"","ancre":"arbre","blocs":["1Protocole : 3 plans T2, T1 multicontraste (graisse / eau), diffusion avec cartographie ADC, T1 après injection de gadolinium.","2La classification FIGO échographique décrit aussi en IRM la position du myome par rapport à la muqueuse et à la séreuse.","3Myome simple : hyposignal T2, isosignal T1, hyposignal b1000, rehaussement homogène.","4Un des critères principaux pour distinguer un sarcome d'un myome : ADC < 0,8 × 10⁻³ mm²/s."]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture."]},{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Utérus","Pour chaque myome","Synthèse"]}]}]},{"id":"irm-myocardite","url":"fiches/irm-myocardite.html","titre":"IRM des myocardites","spe":"vasculaire","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"Définition","badge":"","ancre":"introduction","blocs":["Myocardite : inflammation du myocarde.","Jusqu'à 12 % des morts subites du sujet jeune."]},{"titre":"Étiologies","badge":"","ancre":"introduction","blocs":["Origine infectieuse virale +++ (parvovirus B19, herpèsvirus humain 6, adénovirus…).","Autres origines : immunologiques, toxiques, médicamenteuses…"]}]},{"id":"clinique","titre":"Diagnostic clinique","rubriques":[{"titre":"","badge":"","ancre":"clinique","blocs":["Histoire clinique","Épisode grippal récent.","Examen physique","Non spécifique : de l'examen normal à la défaillance hémodynamique.","Fonction ventriculaire","Anomalies de la contractilité ; dysfonction du VG non spécifique ; dysfonction biventriculaire : mauvais pronostic.","ECG","Anomalies du segment ST et de l'onde T, présentes chez moins de 50 % des patients.","Biologie","Élévation des troponines dans seulement 35 à 45 % des cas.","Imagerie","Échographie, scintigraphie… et surtout IRM cardiaque, examen non invasif de référence."]}]},{"id":"indications","titre":"IRM : indications","rubriques":[{"titre":"","badge":"","ancre":"indications","blocs":["Une triade indispensable : symptômes évocateurs + atteinte myocardique évidente + suspicion d'une origine virale."]},{"titre":"Symptômes évocateurs","badge":"1","ancre":"indications","blocs":["Nouveaux ou persistants :","Dyspnée, orthopnée.","Palpitations.","Malaise à l'effort.","Douleurs thoraciques."]},{"titre":"Atteinte myocardique évidente","badge":"2","ancre":"indications","blocs":["Dysfonction ventriculaire.","Anomalies ECG.","Élévation des troponines."]},{"titre":"Suspicion d'une origine virale","badge":"3","ancre":"indications","blocs":["Virose récente / antécédent de myocardite.","Absence de facteur de risque coronarien.","Âge < 35 ans.","Symptômes inexpliqués par une atteinte coronaire.","Tests fonctionnels coronaires récents négatifs."]}]},{"id":"protocole","titre":"Protocole IRM — myocardite","rubriques":[{"titre":"","badge":"","ancre":"protocole","blocs":["Séquence","Coupes","Ce que l'on cherche","T2 STIR / T2 sang noir","Petit axe basal, médian, apical ± 4 cavités","Œdème myocardique : hypersignal T2.","Cartographie T2","Petit axe basal, médian, apical","T2 allongé = œdème.","Cartographie T1 native","T1 allongé = atteinte inflammatoire / œdème.","Injection"]}]},{"id":"signes","titre":"IRM : les trois signes cardinaux","rubriques":[{"titre":"","badge":"","ancre":"signes","blocs":["Les cibles tissulaires : œdème, hyperhémie et stase capillaire, nécrose et fibrose. S'y ajoutent les anomalies de la contractilité, la dysfonction ventriculaire et l'épanchement péricardique."]},{"titre":"Œdème myocardique","badge":"1","ancre":"signes","blocs":["Hypersignal T2 (sang noir, triple inversion-récupération).","Diffus : normaliser au muscle squelettique (ratio ≥ 2,0).","Focal : sous-épicardique ou transmural ; ± épaississement pariétal.","Sans rehaussement tardif : lésions réversibles.","Corrélé à la présence d'un génome viral dans le sang."]},{"titre":"Hyperhémie et stase capillaire","badge":"2","ancre":"signes","blocs":["Rehaussement précoce : perfusion, ciné ou T1 juste après gadolinium.","Augmentation du signal myocardique avant / après gadolinium ≥ 45 %.","Ratio de rehaussement précoce myocarde / muscle ≥ 4.","N'est pas un critère de Lake Louise 2018 : l'hyperhémie est captée par le T1 natif et l'ECV."]},{"titre":"Nécrose et fibrose","badge":"3","ancre":"signes","blocs":["Rehaussement tardif multifocal ou linéaire sous-épicardique, de distribution non vasculaire.","Inféro-latéral >>> antéro-septal.","Peu sensible si l'atteinte myocardique est limitée."]},{"titre":"Un même foyer inféro-latéral, trois séquences","badge":"","ancre":"signes","blocs":["Schémas pédagogiques (pas des images de patients). Le T2 voit l'eau ; le T1 natif voit l'eau et l'inflammation ; le rehaussement tardif voit la nécrose et la fibrose, ici sous-épicardique."]}]},{"id":"lake-louise","titre":"Critères de Lake Louise (2018)","rubriques":[{"titre":"","badge":"","ancre":"lake-louise","blocs":["Les critères de 2018 intègrent l'imagerie paramétrique (cartographies T1 et T2, volume extracellulaire).","Pour parler de myocardite, le myocarde doit être Trempé (T2) et Touché (T1)."]},{"titre":"","badge":"","ancre":"lake-louise","blocs":["Trempé","L'eau : l'œdème","Hypersignal T2 régional","Hypersignal T2 globalratio myocarde / muscle squelettique ≥ 2,0","T2 allongé en cartographierégional ou global"]},{"titre":"","badge":"","ancre":"lake-louise","blocs":["Touché","La lésion : hyperhémie, nécrose, fibrose","T1 natif allongé en cartographierégional ou global","ECV augmentévolume extracellulaire","Rehaussement tardif non ischémiqueau moins un foyer"]},{"titre":"","badge":"","ancre":"lake-louise","blocs":["Myocardite ≥ 1 T2 + ≥ 1 T1 Au moins un critère de chaque colonne : spécificité maximale.","Les 2 « P » de soutien","PPéricarde : épanchement ou hypersignal du péricarde.","PPompe : trouble de la cinétique, dysfonction systolique du VG."]},{"titre":"T2 + T1","badge":"T1","ancre":"lake-louise","blocs":["Myocardite","Au moins un critère T2 et au moins un critère T1.","→ Diagnostic retenu"]},{"titre":"T2 ou T1 seul","badge":"","ancre":"lake-louise","blocs":["Possible","Peut soutenir le diagnostic dans un contexte évocateur, avec une spécificité moindre.","→ IRM de contrôle à 1-2 semaines"]},{"titre":"Aucun critère","badge":"","ancre":"lake-louise","blocs":["Pas d'argument IRM","Mais si le tableau clinique est très évocateur (ou les symptômes très récents)…","→ IRM de contrôle à 1-2 semaines"]},{"titre":"Calculateur Lake Louise","badge":"","ancre":"lake-louise","blocs":["Aide au calcul — résultat à valider par le radiologue."]}]},{"id":"exemples","titre":"Les aspects IRM à connaître","rubriques":[{"titre":"","badge":"","ancre":"exemples","blocs":["Sept situations types, chacune avec son schéma : où se trouve l'anomalie, dans quelle couche du myocarde, et ce qu'elle signifie.","Schémas pédagogiques dessinés pour la fiche : ce ne sont pas des images de patients. L'œil-de-bœuf indique les segments atteints (17 segments AHA)."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Myocardite virale typique"]},{"titre":"Parvovirus B19 : la forme « pseudo-infarctus »","badge":"","ancre":"exemples","blocs":["Présentation proche d'un infarctus du myocarde : douleur thoracique, troponine.","Rehaussement tardif sous-épicardique de la paroi latérale, le plus souvent inféro-latérale.","Récupération habituelle en quelques mois.","Une biopsie dirigée vers la zone rehaussée est bien plus rentable qu'une biopsie à l'aveugle.","Sous-épicardique + paroi latérale : la signature de la myocardite virale."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Forme septale"]},{"titre":"Herpèsvirus humain 6 (HHV6) : l'atteinte septale","badge":"","ancre":"exemples","blocs":["Révélation volontiers par une insuffisance cardiaque de novo, surtout en cas de co-infection HHV6 + parvovirus B19.","Rehaussement tardif septal, en bande médio-pariétale.","Évolution plus souvent vers l'insuffisance cardiaque chronique.","Le siège du rehaussement oriente le pronostic : septal = forme plus sévère."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Pronostic"]},{"titre":"FEVG préservée : le motif antéro-septal inquiète","badge":"","ancre":"exemples","blocs":["Deux motifs dominent : sous-épicardique inféro-latéral (le plus fréquent) et médio-pariétal antéro-septal.","Le motif antéro-septal : rehaussement plus étendu, VG plus dilaté et pronostic plus sombre.","Vrai même quand la FEVG est normale.","Même avec une FEVG normale, un rehaussement médio-pariétal antéro-septal est un signal d'alarme."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Pronostic"]},{"titre":"Le rehaussement tardif prédit les événements","badge":"","ancre":"exemples","blocs":["La présence d'un rehaussement tardif est le principal facteur pronostique de l'IRM, plus que la FEVG ou les symptômes.","Les aspects les plus péjoratifs : septal, médio-pariétal, en patch et étendu.","Une IRM normale est rassurante : risque d'événements très faible.","Au compte rendu : présence, siège, couche, motif et étendue du rehaussement tardif."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Cartographie T1"]},{"titre":"La cartographie T1 native, plus sensible","badge":"","ancre":"exemples","blocs":["T1 natif allongé dans la zone atteinte, parfois de façon globale.","Plus sensible que le T2 pondéré ; utile pour une atteinte discrète ou sans injection de gadolinium.","En phase aiguë, les cartographies T1 et T2 sont très performantes ; en phase chronique, la cartographie T2 reste la plus utile.","Seuils propres à chaque machine et séquence : interpréter avec les normes locales."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Suivi"]},{"titre":"L'IRM à distance : œdème ou fibrose ?","badge":"","ancre":"exemples","blocs":["L'œdème régresse le plus souvent ; le rehaussement tardif peut diminuer, voire disparaître.","À distance, un rehaussement sans œdème correspond à une fibrose définitive : pronostic plus sombre, surtout s'il est septal médio-pariétal.","Un œdème persistant signe une inflammation encore active, avec une chance de récupération.","En phase aiguë, rehaussement ≠ fibrose définitive ; à distance, rehaussement sans œdème = fibrose."]},{"titre":"","badge":"","ancre":"exemples","blocs":["Post-vaccinale"]},{"titre":"Myocardite après vaccin ARNm contre la COVID-19","badge":"","ancre":"exemples","blocs":["Surtout l'homme jeune.","Même aspect que les autres myocardites : rehaussement sous-épicardique basal inféro-latéral.","Mais en moins sévère : rehaussement moins étendu, FEVG mieux conservée, septum moins souvent atteint ; évolution favorable à court terme.","Même aspect que les autres myocardites, en moins sévère."]},{"titre":"Cas du service","badge":"","ancre":"exemples","blocs":["ŒdèmeHypersignal T2 sous-épicardique.","Rehaussement tardifSous-épicardique, de distribution non coronaire.","T1 natif allongéValeurs au-dessus des normes locales.","Épanchement péricardiqueCritère de soutien."]}]},{"id":"pieges","titre":"Autres signes et pièges","rubriques":[{"titre":"Autres signes","badge":"","ancre":"pieges","blocs":["Anomalies de la contractilité : peu spécifiques.","Augmentation transitoire de l'épaisseur pariétale.","Augmentation transitoire des volumes du VG.","Diminution de la masse myocardique en cours de récupération.","Épanchement péricardique : non spécifique."]},{"titre":"Pièges techniques","badge":"","ancre":"pieges","blocs":["Antenne de surface : signal inhomogène, faux négatif inféro-latéral et faux positif septal → correction d'intensité ou antenne corps.","Sang lent mal supprimé en T2 : faux hypersignal sous-endocardique ; l'œdème de myocardite est presque toujours sous-épicardique ou transmural.","Myosite associée : les ratios normalisés au muscle sont faussés.","Septum basal : la chambre de chasse, le septum membraneux et l'insertion de la bande modératrice peuvent simuler un rehaussement septal.","Épanchement ou graisse ? En ciné, la graisse entoure les coronaires et le sillon auriculo-ventriculaire, séparée par une fine ligne noire de déplacement chimique.","IRM des premiers jours moins sensible : savoir la répéter."]},{"titre":"Ischémique ou non ischémique ?","badge":"","ancre":"pieges","blocs":["IschémiqueDébute toujours au sous-endocarde et s'étend vers l'épicarde, dans un territoire coronaire (ici l'IVA).","Non ischémiqueSous-épicardique ou médio-pariétal, sans systématisation coronaire ; le sous-endocarde n'est pas atteint de façon isolée."]}]},{"id":"take-home","titre":"Take home message — protocole a minima","rubriques":[{"titre":"","badge":"","ancre":"take-home","blocs":["1Fonction ventriculaire → ciné petit axe.","2Œdème → triple inversion-récupération (STIR) petit axe et 4 cavités.","3Hyperhémie → perfusion, T1 double inversion-récupération petit axe après gadolinium (rehaussement précoce).","4Fibrose → rehaussement tardif multiplanaire.","5Cartographies T1 + T2 seules ? Question encore débattue."]}]},{"id":"compte-rendu","titre":"Éléments à préciser au compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez au fur et à mesure de votre lecture."]},{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Fonction","Critères T2 (Trempé)","Critères T1 (Touché)","Soutien et synthèse"]}]}]},{"id":"spondylodiscite","url":"fiches/spondylodiscite.html","titre":"Spondylodiscite infectieuse","spe":"osteo","sections":[{"id":"intro","titre":"Introduction & épidémiologie","rubriques":[{"titre":"","badge":"","ancre":"intro","blocs":["Infection du disque intervertébral et des corps vertébraux adjacents.","Urgence diagnostique et thérapeutique +++.","Rare mais grave : 2 à 4 % des ostéomyélites, séquelles fonctionnelles possibles ; 10 % des hospitalisations pour infection ostéo-articulaire en France.","Tout âge, prédominance masculine : enfant et adolescent, adulte de 40 à 60 ans.","Localisation : rachis lombaire > 50 %, rachis dorsal (tuberculose), rachis cervical."]},{"titre":"Facteurs de risque","badge":"!","ancre":"intro","blocs":["Vieillissement et comorbidités","Diabète","Alcoolisme","Immunodépression","Malnutrition","Drépanocytose","Toxicomanie","Chirurgie et traumatismes du rachis","Cancer","Cirrhose","Insuffisance rénale"]},{"titre":"Clinique trompeuse","badge":"?","ancre":"intro","blocs":["Fièvre, altération de l'état général et syndrome inflammatoire biologique souvent absents.","Rachialgies intenses, non soulagées par le repos."]},{"titre":"","badge":"","ancre":"intro","blocs":["Diagnostic sur un faisceau d'arguments : clinique, biologique, imagerie. IRM : gold standard. Diagnostic étiologique et de confirmation : bactériologie +++."]},{"titre":"Buts de l'imagerie","badge":"","ancre":"intro","blocs":["Diagnostic positif","Bilan lésionnel","Diagnostic étiologique","Guidage du prélèvement","Surveillance"]}]},{"id":"physio","titre":"Physiopathologie","rubriques":[{"titre":"Contamination hématogène +++","badge":"1","ancre":"physio","blocs":["Principal mode de contamination.","Origine artérielle : la plus fréquente.","Origine veineuse : plexus de Batson."]},{"titre":"Inoculation directe","badge":"2","ancre":"physio","blocs":["Iatrogène : actes médicaux.","Accidentelle : traumatismes."]},{"titre":"Contiguïté","badge":"3","ancre":"physio","blocs":["Escarres.","Abcès."]},{"titre":"","badge":"","ancre":"physio","blocs":["Germes impliqués","1Staphylocoque doré 2Mycobacterium tuberculosis 3Gram négatif : E. coli, Pseudomonas 4Streptocoques","L'infection débute dans le spongieux sous-chondral, près du ligament vertébral antérieur. Les plateaux inférieur et supérieur sont vascularisés par la même artère segmentaire (partie antérieure +++), d'où l'atteinte en miroir des deux plateaux.","3 voies de diffusion : trans-discale, sous-ligamentaire, vasculaire."]},{"titre":"Pyogènes","badge":"","ancre":"physio","blocs":["Voie trans-discale ++.","Voie vasculaire."]},{"titre":"Tuberculose","badge":"","ancre":"physio","blocs":["Progression sous-ligamentaire +++.","Le disque, milieu très pauvre en oxygène, est atteint tardivement.","L'infection peut sauter un ou plusieurs espaces intersomatiques."]}]},{"id":"moyens","titre":"Moyens d'exploration & protocole IRM","rubriques":[{"titre":"Radiographie","badge":"1","ancre":"moyens","blocs":["Examen de première intention.","Limite : signes tardifs (latence de 2 à 6 semaines), sensibilité faible."]},{"titre":"TDM","badge":"2","ancre":"moyens","blocs":["Étude osseuse : importance de la destruction.","Guidage du prélèvement ; alternative en cas de contre-indication ou de non-disponibilité de l'IRM."]},{"titre":"IRM","badge":"3","ancre":"moyens","blocs":["Gold standard : sensibilité et spécificité élevées."]},{"titre":"Scintigraphie","badge":"4","ancre":"moyens","blocs":["Utile dans les formes précoces : hypermétabolisme ; recherche d'autres localisations. Peu spécifique."]},{"titre":"","badge":"","ancre":"moyens","blocs":["Exploration de la totalité du rachis +++ : coupes sagittales du rachis entier à la recherche de lésions multifocales."]},{"titre":"Quand faire l'IRM ?","badge":"","ancre":"moyens","blocs":["< 6 h","En cas de signes neurologiques, sans retarder la prise en charge chirurgicale.","< 72 h","Dès la suspicion diagnostique.","Répéter l'IRM à 1 semaine si l'examen initial est normal mais que le doute persiste."]},{"titre":"Protocole IRM","badge":"","ancre":"moyens","blocs":["Sag T1","Sagittal T1 : hyposignal T1 marqué du corps vertébral.","Sag T2 FS","Sagittal T2 avec suppression de graisse (STIR, Dixon / IDEAL) : œdème des corps vertébraux et des disques.","Cor STIR","Coronal STIR grand champ : extension des lésions, diagnostic différentiel.","T1 Gado","T1 après injection de gadolinium, 2 plans : recherche d'épidurite et de collections."]}]},{"id":"semiologie","titre":"Sémiologie radiologique","rubriques":[{"titre":"","badge":"","ancre":"semiologie","blocs":["Les mêmes structures analysées avec les trois techniques.","StructureRadiographieTDMIRM","Disque intervertébral","Perte de hauteur (pincement)","Perte de hauteur","Aspect hypodense","Perte du nuclear cleft sign","Œdème : hypoT1, hyperT2 / STIR, rehaussement","Corps vertébraux","Atteinte pouvant être en miroir","Érosion d'un coin antérieur ou de tout le plateau","Liseré cortical des plateaux flou et effacé"]},{"titre":"Les signes IRM les plus sensibles","badge":"","ancre":"semiologie","blocs":["Inflammation paravertébrale ou péridurale","Hypersignal T2 du disque, mais il peut manquer","Rehaussement du disque après gadolinium","Érosions, destruction des plateaux vertébraux"]}]},{"id":"etiologie","titre":"Orientation étiologique","rubriques":[{"titre":"","badge":"","ancre":"etiologie","blocs":["Un signe radiologique ne mène pas au germe ! Deux géodes qui s'affrontent ou un abcès bilobé de l'espace épidural : pas toujours une tuberculose.","Le diagnostic de certitude reste bactériologique (± histologique), sérologique pour la brucellose."]},{"titre":"Pyogènes","badge":"P","ancre":"etiologie","blocs":["Début brutal +++, fièvre +++.","Douleurs rachidiennes, impotence fonctionnelle fréquente, rigidité segmentaire.","Complications neurologiques (compression médullaire ou radiculaire) rares.","Biologie : syndrome inflammatoire franc +++."]},{"titre":"Tuberculose (mal de Pott)","badge":"T","ancre":"etiologie","blocs":["Début progressif +++, fièvre inconstante, AEG.","Rigidité rachidienne, gibbosité, saillie et douleur d'une épineuse, abcès froid.","Compression médullaire ou radiculaire fréquente ; paraplégie (3 à 25 %), déformation rachidienne, fistules.","Biologie : syndrome inflammatoire pouvant être absent +++.","Arguments : antécédent ou contage, autre localisation tuberculeuse, IDR presque toujours positive, VS inconstante."]},{"titre":"Brucellose","badge":"B","ancre":"etiologie","blocs":["Début progressif.","Contexte : milieu rural, profession exposée, produits laitiers non pasteurisés.","Douleur peu intense, mécanique.","Biologie : syndrome inflammatoire inconstant."]},{"titre":"Le tableau comparatif","badge":"","ancre":"etiologie","blocs":["Critère Pyogènes Tuberculose Brucellose","Siège préférentiel Lombaire Thoracique / thoraco-lombaire (cervical : 4 à 15 %) Lombaire bas","Extension Habituellement ≤ 2 corps vertébraux Sous-ligamentaire, ≥ 3 corps vertébraux ; atteinte multifocale Anomalies limitées aux angles antérieurs","Disque Atteinte précoce et sévère ; abcès discal fréquent Atteinte tardive ; abcès rare Atteinte tardive","Pincement discal Précoce et modéré Tardif et marqué Tardif et modéré","Destruction vertébrale Importante, moins sévère que dans la tuberculose Fréquente et sévère Discrète","Érosions sous-chondrales Petites De grande taille, en miroir Érosion d'un angle vertébral","Condensation osseuse Précoce et marquée Tardive et modérée Précoce et marquée","Ostéophytose — — Gros ostéophytes : bec de perroquet","Vide discal Absent Absent Possible","Arc postérieur Généralement épargné Atteinte possible —","Tissus mous paravertébraux Inflammation ++, mal limitée ; ligaments non respectés Bien limité, peu d'inflammation ; ligaments respectés et soulevés ; calcifications, séquestres Petits abcès bien limités"]},{"titre":"Spondylodiscite à pyogènes","badge":"","ancre":"etiologie","blocs":["Radiographie","Sensibilité faible, temps de latence de 2 à 6 semaines.","Pincement discal ; lésions destructrices des plateaux.","Constructions osseuses ; modification des tissus mous.","Scintigraphie","Diagnostic précoce, recherche d'autres localisations ; peu spécifique.","TDM (si IRM contre-indiquée ou non disponible)","Plus sensible que la radiographie : hypodensité discale, destruction osseuse, abcès paravertébraux, calcifications, séquestres.","IRM","Disque : hauteur le plus souvent réduite (parfois normale, voire augmentée) ; hypersignal T2 avec disparition du cleft, rarement hyposignal ; iso- ou hyposignal T1 ; rehaussement périphérique, diffus ou focal.","Corps vertébraux : destruction des plateaux (sensibilité 84 %) ; œdème initialement focal, à la partie antérieure d'un ou des deux plateaux, étendu à tout le corps vertébral dans 60 % des cas ; rehaussement presque constant.","Tissus mous : masse paravertébrale et / ou épidurale vascularisée, pouvant être le premier signe de l'infection ; collection à paroi fine ou épaisse ; épidurite ne respectant pas le LVP +++."]},{"titre":"Spondylodiscite tuberculeuse (mal de Pott)","badge":"","ancre":"etiologie","blocs":["Signes de présomption","Siège : rachis thoracique ou thoraco-lombaire.","Disque : atteinte tardive et importante, longtemps respecté.","Corps vertébraux : extension sous-ligamentaire à 3 vertèbres ou plus, atteinte multifocale, destruction osseuse importante, abcès intra-osseux, limite nette de l'inflammation périosseuse.","Parties molles : respect du LVP : embrasse de rideau ; abcès à paroi fine et régulière ; abcès volumineux fusant loin du foyer.","Abcès froids : collections paravertébrales, macrocalcifications possibles, sans infiltration des parties molles adjacentes.","Formes anatomo-radiologiques","Typique : spondylodiscite ou mal de Pott.","Localisations particulières : charnière cervico-occipitale, costo-vertébrale.","Formes atypiques : arc postérieur, spondylite.","Diagnostic de certitude","Examen bactériologique et / ou histologique : liquide articulaire, pus, biopsie disco-vertébrale, biopsie synoviale."]},{"titre":"Spondylodiscite brucellienne","badge":"","ancre":"etiologie","blocs":["Radiographie","Pincement discal tardif et modéré.","Destruction d'un angle vertébral, ostéocondensation.","Gros ostéophytes : érosion + ostéophyte = bec de perroquet.","Vide discal possible : faible volume, siège périphérique.","Destruction moins importante, condensation et ostéophytose plus marquées que dans la tuberculose.","Scintigraphie, IRM et TDM","Diagnostic précoce, recherche d'autres localisations et des abcès des tissus mous.","IRM : abcès de petite taille, bien limités, assez nombreux ; préservation du LVP : embrasse de rideau.","Signes de présomption","Siège lombaire bas, abcès de petite taille, anomalies limitées aux angles antérieurs, bec de perroquet.","Diagnostic de certitude"]}]},{"id":"hydatidose","titre":"Hydatidose rachidienne & spondylodiscites mycosiques","rubriques":[{"titre":"Hydatidose : radiographie","badge":"","ancre":"hydatidose","blocs":["Siège : dorsal > lombaire > sacrum > cervical.","Corps vertébral ++ > arc postérieur.","Image lytique du corps vertébral (ou de l'arc postérieur), à développement volontiers asymétrique, conservant la forme globale de la vertèbre.","Limites nettes ++ ou floues.","Disque longtemps intact ; tassements vertébraux tardifs.","Extension aux côtes et aux os iliaques.","Collections paravertébrales : opacités paravertébrales, unilatérales, aux contours parfois calcifiés."]},{"titre":"Hydatidose : IRM","badge":"","ancre":"hydatidose","blocs":["Atteinte discale tardive.","Collection liquidienne multivésiculaire para-rachidienne.","Extension intracanalaire.","Signal normal du spongieux périlésionnel."]},{"titre":"","badge":"","ancre":"hydatidose","blocs":["« Un pédicule qui manque ! »Pédicule non visible (flèche rouge) et opacité des parties molles paravertébrale (flèche orange), bilatérale sur ce cas.","Collection multivésiculaireCollection liquidienne multivésiculaire para-rachidienne."]},{"titre":"Spondylodiscites mycosiques","badge":"","ancre":"hydatidose","blocs":["Rares, mais incidence en hausse : immunodépression, diabète, VIH, chimiothérapie.","Germes les plus fréquents : Candida, Aspergillus.","Clinique non spécifique : rachialgies inflammatoires, irritation radiculaire, déficit neurologique.","Imagerie, notamment IRM, non spécifique ; diagnostic souvent tardif.","Diagnostic : anatomopathologique sur la biopsie disco-vertébrale."]}]},{"id":"formes-rares","titre":"Formes inhabituelles","rubriques":[{"titre":"","badge":"","ancre":"formes-rares","blocs":["Atteinte exclusive du corps vertébral, respectant les plateaux et les disques adjacents.","Peut évoluer vers un tassement vertébral ou s'étendre vers le canal rachidien.","Germes : tuberculose, pyogènes, brucellose.","30 à 60 % des tuberculoses rachidiennes ; 13 % des infections rachidiennes à pyogènes."]},{"titre":"","badge":"","ancre":"formes-rares","blocs":["Spondylite : penser à","Métastase","Hémopathie","Infection à germe spécifique ou banal !"]},{"titre":"","badge":"","ancre":"formes-rares","blocs":["Radiographie / TDM","Ostéocondensation diffuse ou focale du corps vertébral.","Lésion lytique à limite nette, pouvant contenir un séquestre.","Pas d'anomalie discale associée.","Géodes centro-somatiques ; ostéolyse mouchetée.","IRM","HypoT1, hyperT2 et rehaussement, ou hypoT1 et hypoT2.","Intégrité du disque.","Abcès.","OstéocondensationOstéocondensation focale et ostéolyse d'un corps vertébral.","SéquestreLésion lytique à limite nette contenant un séquestre.","GéodeGéode centro-somatique à limite nette."]},{"titre":"","badge":"","ancre":"formes-rares","blocs":["Rare, diagnostic difficile.","Arc postérieur ou articulaire : arthrite > ostéite.","Rachis lombaire > rachis cervical.","Habituellement par voie sanguine, rarement inoculation directe.","Germes : tuberculose, pyogènes."]},{"titre":"","badge":"","ancre":"formes-rares","blocs":["ModalitéSignes observés","Radiographie / TDMRaréfaction osseuse régionale ; érosions marginales ; séquestres","ÉchographieCollection juxta-articulaire ; hypervascularisation périphérique au Doppler","IRMÉpanchement intra-articulaire ; inflammation des tissus mous adjacents ; collection épidurale ou paravertébrale possible","Érosions marginalesAtteinte de l'articulaire postérieure : érosions marginales.","SéquestreLyse de l'arc postérieur avec séquestre.","Arthrite interapophysaireÉpanchement intra-articulaire et inflammation des tissus mous adjacents.","Arthrite facettaire : voir le cas « Bacillus cereus » en annexe →"]},{"titre":"3. Vide discal","badge":"","ancre":"formes-rares","blocs":["Le vide discal n'élimine pas le diagnostic d'infection : germes spécifiques (brucellose) >> germes banals. Physiopathologie mal connue.","Vide discalGaz intradiscal au sein des lésions disco-vertébrales.","Vide discalClarté gazeuse linéaire dans l'espace discal."]}]},{"id":"differentiel","titre":"Diagnostic différentiel","rubriques":[{"titre":"Discopathie dégénérative","badge":"1","ancre":"differentiel","blocs":["Hyposignal T2 du disque, liseré graisseux.","Absence de collection liquidienne ; pas d'abcès disco-vertébral, des parties molles ou épidural.","Prise de contraste absente ou linéaire, possible dans les Modic 1.","Vide intradiscal, ostéophytes, irrégularité des plateaux, ostéocondensation +++."]},{"titre":"Spondylarthrite ankylosante / pelvispondylite","badge":"2","ancre":"differentiel","blocs":["Atteinte multi-étagée ; spondylite d'Andersson ou enthésite ; sacro-iliite.","Lésions disco-vertébrales de nature inflammatoire, traumatique.","En faveur : fracture de l'arc postérieur, hypersignal T1 du corps vertébral, absence de collection liquidienne."]},{"titre":"","badge":"","ancre":"differentiel","blocs":["Discopathie · T2Perte du signal hydrique du disque ; hypersignal à distance de la lame sous-chondrale.","Discopathie · T1Hyposignal peu marqué, graisse visible (flèches vertes).","PelvispondyliteLésions disco-vertébrales inflammatoires, sans collection liquidienne.","PelvispondyliteLésion disco-vertébrale inflammatoire, sans collection liquidienne.","Spondylarthropathie érosive de l'hémodialysé : terrain d'insuffisance rénale chronique Discopathie microcristalline : calcifications discales, ostéosclérose des plateaux Traumatisme rachidien : contexte +++ Spondylite isolée : métastase, hémopathie"]}]},{"id":"prelevement","titre":"Prélèvement & radiologie interventionnelle","rubriques":[{"titre":"","badge":"","ancre":"prelevement","blocs":["Le diagnostic de certitude est bactériologique (± histologique). Le prélèvement est généralement guidé par scopie ou TDM."]},{"titre":"Techniques","badge":"1","ancre":"prelevement","blocs":["Ponction d'abcès.","Biopsie de la paroi.","Biopsie osseuse.","Ponction-biopsie disco-vertébrale (PBDV)."]},{"titre":"Étapes préalables obligatoires","badge":"!","ancre":"prelevement","blocs":["Discussion pluridisciplinaire.","Recherche de germes (prélèvements périphériques).","Bilan d'hémostase.","Respect de la courbe d'apprentissage."]},{"titre":"Guidage","badge":"2","ancre":"prelevement","blocs":["Plusieurs options selon le cas : scopie ou TDM."]},{"titre":"Rentabilité dans la tuberculose","badge":"","ancre":"prelevement","blocs":["17-30 %Examen direct positif 42 %Culture positive sur abcès paravertébral : identifie la mycobactérie et sa sensibilité PCRRésultat rapide, mais moins sensible que la culture 80 %Aspect histologique caractéristique"]}]},{"id":"evolution","titre":"Évolution sous traitement","rubriques":[{"titre":"","badge":"","ancre":"evolution","blocs":["1-2 mois","Radiographie : stabilisation des lésions, signes de reconstruction osseuse (condensation périphérique, ostéophytes).","Long terme","Radiographie : bloc vertébral complet dans les formes destructrices, incomplet si lésions limitées ; restitution ad integrum dans les formes vues et traitées précocement.","IRM","Diminution du volume des collections ; augmentation du signal du spongieux en T1 ; diminution du signal du disque en T2 ; normalisation lente ; aggravation initiale fréquente.","Piège","Discordance clinico-radiologique : bonne évolution clinique, aggravation radiologique.","Les signes IRM persistent même après guérison.","Conduite","Ne pas se fier à l'IRM pour décider de l'arrêt de l'antibiothérapie.","Pas d'imagerie de suivi systématique : suivi clinique et biologique."]}]},{"id":"a-retenir","titre":"À retenir","rubriques":[{"titre":"","badge":"","ancre":"a-retenir","blocs":["Sensibilité et spécificité élevées de l'IRM : examen de référence, à réaliser en urgence.","Signes les plus sensibles : inflammation paravertébrale ou péridurale, hypersignal T2 et rehaussement du disque, érosions des plateaux.","Valeur relative de l'imagerie pour le diagnostic étiologique : le prélèvement fait le diagnostic.","Discordance entre évolution clinique et évolution IRM."]}]},{"id":"annexe","titre":"Annexe · Cas & images","rubriques":[{"titre":"","badge":"","ancre":"annexe","blocs":["Cas cliniques","Deux cas annotés : tuberculose rachidienne et spondylodiscite à Bacillus cereus.","IRM et TDM annotées · légendes · évolution à 1 mois"]}]}]},{"id":"avc-ischemique","url":"fiches/avc-ischemique.html","titre":"Imagerie de l'AVC ischémique","spe":"neuro","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"","badge":"","ancre":"introduction","blocs":["Définition : déficit neurologique soudain, d'étiologie vasculaire présumée.","Fréquence : 80-85 % de la pathologie vasculaire cérébrale — urgence diagnostique et thérapeutique.","Référence : IRM (1re intention, peu accessible en urgence) – TDM sans injection + perfusion + angioscanner = alternative.","Problème de santé publique : retentissement social et économique considérable — « time is brain ».","Ischémie cérébrale : le plus souvent d'origine artérielle, parfois d'origine veineuse.","Buts de l'imagerie : établir le Dg positif – éliminer un autre diagnostic (hémorragie) – évaluer l'étendue et la sévérité – évaluer la réversibilité – chercher l'étiologie → guide la prise en charge thérapeutique.","Nouvelle prise en charge : stroke center, thrombolyse, diffusion, perfusion."]}]},{"id":"etiologies","titre":"Étiologies","rubriques":[{"titre":"A. Ischémie d'origine artérielle","badge":"","ancre":"etiologies","blocs":["Accidents thrombo-emboliques : origine cardiaque.","Atteinte des vaisseaux extracrâniens : athéromatose carotidienne – dissection (plus fréquente au niveau de la carotide interne qu'au niveau de l'artère vertébrale).","Atteinte des vaisseaux intracrâniens : athérosclérose intracrânienne – vascularite intracrânienne – vasospasme – ischémie d'origine anévrysmale.","Ischémie lacunaire : HTA chronique – angiopathie des petits vaisseaux (lipohyalinose).","Autres vasculopathies : encéphalopathie postérieure réversible, CADASIL, Moya-Moya.","Par ordre de fréquence : athéromatose intra/extracrânienne > AVC lacunaires > AVC cardio-emboliques."]},{"titre":"B. Ischémie d'origine veineuse","badge":"","ancre":"etiologies","blocs":["Occlusion des sinus veineux et des veines cérébrales.","Causes infectieuses ou non infectieuses (locales et générales)."]}]},{"id":"exploration","titre":"Moyens d'exploration","rubriques":[{"titre":"1. IRM — examen clé","badge":"","ancre":"exploration","blocs":["Examen de choix.","Anomalies visibles à un stade précoce (notamment grâce à l'imagerie de diffusion).","Inconvénient : faible disponibilité surtout en urgence.","Diagnostic précoce + évaluation pronostique.","Protocole : axial T1 écho de gradient, T2 et Flair, T2*, diffusion, perfusion, ARM 3D TOF.","Diffusion : différencie œdème vasogénique / œdème cytotoxique – se positive en premier, dès 30 min – date la lésion. Faux négatifs : FCP, lésion de petite taille, lésion transitoire."]},{"titre":"","badge":"","ancre":"exploration","blocs":["Datation de l'AVC par la diffusion","AVC récent = restriction de la diffusion = ≤ 10 j (correspond à un AVC aigu ou subaigu).","ADC normal/élevé = AVC > 10 j (subaigu à chronique).","Utile pour distinguer un AVC récent chez un patient aux ATCD d'AVC.","Piège : Dc différentiel devant une restriction de la diffusion (abcès, tumeur hypercellulaire…) → s'aider des autres séquences."]},{"titre":"","badge":"","ancre":"exploration","blocs":["Évolution en diffusion","(A) Jour 1 : la tomodensitométrie sans injection de produit de contraste révèle une hypodensité du lobe temporo-pariétal droit.","(B) Jour 1 : l'imagerie de diffusion (DWI) montre un hypersignal.","(C) Jour 10 : l'imagerie de diffusion (DWI) devient isointense.","(D) Après 4 mois, l'imagerie de diffusion (DWI) montre un hyposignal."]},{"titre":"","badge":"","ancre":"exploration","blocs":["Perfusion : étude du flux microscopique capillaire – identifie la zone de pénombre (hypoperfusée, pas encore en hypersignal diffusion) – injection de gadolinium en bolus. Cartographie : MTT (temps de transit moyen), VSC (volume sanguin cérébral), DSC (débit sanguin cérébral), Time to peak.","ARM 3D TOF : toujours réalisée, recherche l'étiologie – une asymétrie de signal entre les 2 carotides évoque une pathologie carotidienne (sténose).","ARM 3D TOF intracrânienne : occlusion artérielle proximale, sélection pour fibrinolyse – pas d'analyse fiable des artères distales.","T1 écho de gradient : repérage / détection d'un hématome aigu (isosignal).","T2 écho de gradient (T2*) : Détecte un éventuel hématome - hyposignal intra-vasculaire en rapport avec un thrombus.","FLAIR : Lésions récentes/chroniques."]},{"titre":"2. TDM","badge":"","ancre":"exploration","blocs":["Avantages : disponibilité en urgence, permet de différencier AVC hémorragique/ischémique.","Inconvénients : moins sensible que l'IRM, normale à un stade précoce de l'AVC ischémique.","Recommandée si réalisée avant 6h.","TDM sans injection : topogramme de profil, C2 au vertex – acquisition hélicoïdale fine (≈1 mm), chevauchée de 50 % – reconstructions axiale, coronale, sagittale.","TDM de perfusion (+C) : identifie la zone de pénombre – 40-50 cc PDC, 5 cc/s – acquisition séquentielle de 8 coupes de 5 mm – cartographie MTT/VSC/DSC.","Angioscanner cérébral : recherche étiologique (occlusion, dissection), centres spécialisés – recommandé avant 6h."]},{"titre":"","badge":"","ancre":"exploration","blocs":["Collatéralité en angio-TDMAngio-TDM cérébrale en mode MIP axiale (A) et coronale (B) démontrant un très bon score de collatéralité, illustré par l'opacification complète du territoire de l'artère cérébrale moyenne (ACM) distale au thrombus (flèche)."]},{"titre":"3. Écho-Doppler des vaisseaux du cou","badge":"","ancre":"exploration","blocs":["But étiologique, en l'absence d'angio-TDM ou d'ARM.","Recherche : sténose, plaque d'athérome, dissection artérielle (sujet jeune)."]},{"titre":"4. Artériographie","badge":"","ancre":"exploration","blocs":["Indication quasi exclusivement thérapeutique désormais (angioplastie, stent)."]}]},{"id":"demarche","titre":"Démarche d'imagerie devant un AVC aigu","rubriques":[{"titre":"","badge":"","ancre":"demarche","blocs":["Devant tout déficit neurologique focal aigu : imagerie cérébrale immédiate, sans retarder la reperfusion.","IRM d'emblée si immédiatement disponible et réalisable sans délai."]},{"titre":"","badge":"","ancre":"demarche","blocs":["Si IRM non disponible immédiatement","TDM sans injection en 1ère intention : élimine l'hémorragie – recherche les signes précoces d'ischémie et un diagnostic différentiel.","Complétée par une angio-TDM TSA-intracrânien : recherche une occlusion proximale, une sténose ou une dissection.","± TDM de perfusion : recherche un mismatch core-pénombre."]},{"titre":"","badge":"","ancre":"demarche","blocs":["IRM secondairement, si","TDM normale ou douteuse avec forte suspicion clinique.","AVC de fosse postérieure / tronc cérébral.","Bilan étiologique ou diagnostic différentiel."]}]},{"id":"semiologie","titre":"Sémiologie par stade","rubriques":[{"titre":"","badge":"","ancre":"semiologie","blocs":["< 6 h","A. Stade suraigu","6 – 48 h","B. Stade aigu","48 h – 3 sem.","C. Stade subaigu","> 3 sem.","D. Stade chronique"]},{"titre":"A. Stade suraigu (< 6 h)","badge":"","ancre":"semiologie","blocs":["IRM = examen clé : diffusion + perfusion.","Diffusion : hypersignal, ADC diminué (œdème cytotoxique).","Perfusion : met en évidence la zone de pénombre (DSC 15-20 ml/min).","T1, T2, FLAIR : normaux (FLAIR se positive à partir de 4h30, encore négatif avant).","T2* : thrombus visible en hyposignal, si présent.","ARM : montre l'occlusion artérielle.","TDM : élimine un AVC hémorragique +++ ; le plus souvent normale à ce stade. Peut montrer : hyperdensité spontanée d'une ACM ou ACA (« aspect de la trop belle artère ») – dédifférenciation substance blanche/grise – effacement des sillons corticaux – dans le territoire sylvien : effacement du ruban insulaire, effacement du noyau lenticulaire."]},{"titre":"","badge":"","ancre":"semiologie","blocs":["Stade hyperaiguMismatch entre la séquence de diffusion (DWI) et la séquence FLAIR.","Signes précoces en TDM","(A) signe de l'artère cérébrale moyenne hyperdense (trop belle artère).","(B) signe du ruban insulaire : l'interface substance grise-substance blanche de la zone insulaire droite disparaît et le sillon cérébral devient peu profond.","(C) Hypodensité du noyau lenticulaire."]},{"titre":"B. Stade aigu (6-48 h)","badge":"","ancre":"semiologie","blocs":["IRM : diffusion (hypersignal, ADC diminué) – hyposignal T1 – hypersignal T2/FLAIR – T2* : thrombus en hyposignal si présent – ARM : occlusion artérielle.","TDM : signes retardés par rapport à l'IRM – hypodensité cortico-sous-corticale ± effet de masse."]},{"titre":"C. Stade subaigu (48 h à 3 semaines)","badge":"","ancre":"semiologie","blocs":["Œdème cytotoxique → œdème vasogénique.","IRM : diffusion – l'ADC se normalise puis augmente (persistance de l'hypersignal par effet T2 shine-through) – hyposignal T1, hypersignal T2/FLAIR – si injection : prise de contraste gyriforme (cortex) ou nodulaire/annulaire (noyaux gris) – ARM : occlusion artérielle.","TDM : majoration de l'hypodensité du territoire ischémié – apparition ou majoration de l'effet de masse – si injection : prise de contraste gyriforme. Rehaussement (règle 2 ; 2 ; 2) : débute J2, maximal S2, disparaît après M2. Effet de masse : maximal J2-J5, diminue dès J7, disparaît vers 3 semaines.","Le « fogging effect »","Disparition transitoire de l'hypodensité parenchymateuse.","Possible à partir de la 2ème ou 3ème semaine."]},{"titre":"D. Stade chronique (> 3 semaines)","badge":"","ancre":"semiologie","blocs":["Cavité porencéphalique si lésion étendue : même signal que le LCR, entourée de gliose.","Atrophie localisée si lésion limitée.","Lacune si AVC lacunaire.","Absence de rehaussement après PDC dès le 2ème mois."]}]},{"id":"topographiques","titre":"Formes topographiques","rubriques":[{"titre":"Infarctus territoriaux ou lobaires","badge":"1","ancre":"topographiques","blocs":["Occlusion d'un gros tronc artériel.","Territoire superficiel et/ou profond, total ou partiel.","ACM (50-70 %)."]},{"titre":"Infarctus lacunaires","badge":"2","ancre":"topographiques","blocs":["Lésions < 15 mm.","Occlusion d'une artère perforante (microangiopathie : HTA, diabète).","Siège NGC +++, centres ovales, pont.","Bon pronostic, peu invalidants."]},{"titre":"Infarctus jonctionnels ou hémodynamiques","badge":"3","ancre":"topographiques","blocs":["3 % des ischémies.","Bas débit.","À la jonction de 2 territoires artériels.","Peut être bilatéral."]},{"titre":"","badge":"","ancre":"topographiques","blocs":["Les territoires artériels et les zones jonctionnelles sur une IRM : espace radioanatomie →"]}]},{"id":"evolutives","titre":"Formes évolutives","rubriques":[{"titre":"Remaniements hémorragiques","badge":"1","ancre":"evolutives","blocs":["20 % des cas, plus fréquents si origine cardio-embolique.","Surviennent 24-48 h, voire jusqu'à 2 semaines après l'infarctus.","Hypersignal T1, hypoT2.","→ Fiche AVC hémorragique"]},{"titre":"Nécrose laminaire corticale","badge":"2","ancre":"evolutives","blocs":["Survient 2 semaines après l'épisode initial, régresse progressivement dès M3.","Hypersignal T1, hyperT2, T2EG normal, PDC +++.","Non visible en TDM."]},{"titre":"Dégénérescence wallérienne","badge":"3","ancre":"evolutives","blocs":["Détectée 5 à 12 semaines après le début de l'ischémie.","Hypersignal Flair et T2 de la substance blanche du tractus corticospinal."]}]},{"id":"particulieres","titre":"Étiologies particulières","rubriques":[{"titre":"Infarctus d'origine veineuse","badge":"","ancre":"particulieres","blocs":["Éléments en faveur","Absence de systématisation artérielle.","Topographie sous-corticale prédominante.","Caractère multiple.","Fréquence des remaniements hémorragiques en T2EG.","Visualisation directe du thrombus."]},{"titre":"CADASIL","badge":"","ancre":"particulieres","blocs":["Maladie héréditaire à transmission autosomique, atteinte des petits vaisseaux perforants.","Engendre des infarctus lacunaires.","Évolution vers la démence."]}]},{"id":"conclusion","titre":"Conclusion pratique","rubriques":[{"titre":"","badge":"","ancre":"conclusion","blocs":["L'IRM est l'examen de choix pour la détection très précoce de l'ischémie.","Buts : établir le Dg positif – éliminer un autre diagnostic (hémorragie) – évaluer l'étendue et la sévérité – évaluer la réversibilité – chercher l'étiologie."]},{"titre":"","badge":"","ancre":"conclusion","blocs":["Avant thrombolyse/thrombectomie, 4 questions :"]}]}]},{"id":"avc-hemorragique","url":"fiches/avc-hemorragique.html","titre":"AVC hémorragique : l'imagerie","spe":"neuro","sections":[{"id":"generalites","titre":"Généralités","rubriques":[{"titre":"","badge":"","ancre":"generalites","blocs":["Définition : saignement aigu dans le parenchyme cérébral, qui peut s'étendre aux ventricules et aux espaces sous-arachnoïdiens.","Fréquence : 10 à 15 % des AVC ; morbi-mortalité plus lourde que celle de l'AVC ischémique.","Clinique : déficit neurologique ou trouble de la conscience d'installation brutale, d'origine vasculaire présumée.","En urgence : TDM sans injection → diagnostic positif, siège et retentissement."]},{"titre":"Diagnostic positif","badge":"1","ancre":"generalites","blocs":["Affirmer l'hémorragie."]},{"titre":"Siège et retentissement","badge":"2","ancre":"generalites","blocs":["Facile en TDM sans injection."]},{"titre":"Étiologie","badge":"3","ancre":"generalites","blocs":["Démarche parfois difficile : angio-TDM, angio-IRM, artériographie."]}]},{"id":"datation","titre":"Datation TDM-IRM de l'hématome","rubriques":[{"titre":"","badge":"","ancre":"datation","blocs":["La biochimie de l'hémoglobine explique le signal IRM : c'est elle qui permet de dater l'hématome.","0 – 6 h","Hyperaigu · oxyhémoglobine (OxyHb).","6 h – 3 j","Aigu · désoxyhémoglobine (DésoxyHb).","4 – 7 j","Subaigu précoce · méthémoglobine intraglobulaire.","2 – 4 sem.","Subaigu tardif · méthémoglobine libre (extracellulaire).","> 1 mois","Chronique · ferritine et hémosidérine en périphérie.","Stade"]},{"titre":"Cas IRM : du stade aigu au stade chronique","badge":"","ancre":"datation","blocs":["Quatre hématomes à des stades différents ; cliquez sur une image pour l'agrandir.","Hématome aigu · IRM 2 jours après le début des symptômes","A · Diffusion : hématome nettement hypointense, entouré d'un anneau continu de signal élevé (flèche), qui correspond à la zone de signal élevé autour de l'hématome sur l'image pondérée en T2 (C).","B · T1 : hématome isointense dans le lobe pariétal droit.","C – F · T2 (C), FLAIR (D), écho de gradient T2* conventionnel (E) et écho de gradient T2* écho-planaire (F) : hématome nettement hypointense.","Hématome subaigu précoce · IRM 4 jours après le début des symptômes","A · Diffusion : hématome nettement hypointense, entouré d'un anneau continu de signal élevé (flèche).","B · T1 : hématome hyperintense dans le lobe pariéto-occipital gauche.","C – E · T2 (C), FLAIR (D) et écho de gradient T2* conventionnel (E) : hématome hypointense.","Hématome subaigu tardif · IRM 14 jours après le début des symptômes","A · Diffusion : hématome nettement hyperintense.","B – E · T1 (B), T2 (C), FLAIR (D) et écho de gradient T2* conventionnel (E) : hématome hyperintense des noyaux gris centraux droits."]}]},{"id":"techniques","titre":"Techniques d'imagerie","rubriques":[{"titre":"1. TDM cérébrale sans injection","badge":"","ancre":"techniques","blocs":["Intérêt","Diagnostic positif dans 90 % ; étiologie (avec l'angio-TDM) ; complications.","Hélice","Topogramme de profil, de C1 au vertex.","Acquisition","Hélicoïdale, coupes fines de 1 mm, chevauchement de 50 %, sans produit de contraste.","Reconstructions","3 plans, fenêtre parenchymateuse.","Injection","Utile au stade subaigu : rehaussement gyriforme par rupture de la BHE ; parfois utile à l'étiologie."]},{"titre":"2. Angioscanner artériel","badge":"","ancre":"techniques","blocs":["Intérêt","Diagnostic étiologique.","Hélice","Topogramme de profil, de C2 au vertex.","Injection","70 mL de produit de contraste puis 40 mL de sérum physiologique, à 4 mL/s.","Bolus tracking","ROI dans la lumière de la crosse aortique ou de l'aorte ascendante, sans prendre la paroi ; seuil habituel 100 à 150 UH ; départ automatique de l'acquisition quand l'opacification atteint le seuil.","Coupes","≈ 0,6 mm.","Reconstructions","Fenêtre vasculaire large (hauteur 300 UH) ; MIP 3D et rendu volumique (VR)."]},{"titre":"3. IRM","badge":"","ancre":"techniques","blocs":["Intérêt : diagnostic positif si la TDM est négative · bilan étiologique · complications.","Séquence","Ce qu'elle apporte","Analyse de l'hématome ; référence pour interpréter l'injection.","FLAIR","Hémorragie sus-tentorielle ; artefacts de flux (flow void).","Hémorragie de la fosse cérébrale postérieure.","T2*","Hématome et microsaignements (microbleeds).","Diffusion","Recherche d'une ischémie sous-jacente.","3D TOF"]}]},{"id":"diagnostic","titre":"Diagnostic positif en TDM","rubriques":[{"titre":"","badge":"","ancre":"diagnostic","blocs":["Hyperaigu","Hyperdense hétérogène, 40 à 60 UH ; parfois niveau liquide.","Aigu","Hyperdense homogène, 60 à 100 UH, avec un halo hypodense d'œdème ; rupture possible dans les ventricules ou les espaces sous-arachnoïdiens.","Subaigu","Devient isodense de la périphérie vers le centre ; rehaussement annulaire par des néovaisseaux dépourvus de BHE : ne pas le confondre avec une tumeur.","Chronique","Fente parenchymateuse, dilatation du ventricule et des sillons voisins ; calcifications possibles."]}]},{"id":"etiologies","titre":"Étiologies","rubriques":[{"titre":"","badge":"","ancre":"etiologies","blocs":["L'orientation repose sur la topographie de l'hématome et le terrain. Les 8 étiologies du cours, en un coup d'œil :","Étiologie","Terrain","Siège / aspect","Signe clé","HTA","Hypertendu, ≈ 50 ans","Profond : NGC (putamen) ; lobaire dans 10 %","Microbleeds profonds en T2*","Angiopathie amyloïde","Sujet âgé, non hypertendu","Lobaires multiples, récidivants"]},{"titre":"1. Hypertension artérielle","badge":"","ancre":"eti-hta","blocs":["1re cause d'AVC hémorragique ; terrain : hypertendu, ≈ 50 ans.","Mécanisme : microangiopathie des artères de petit calibre.","Hématome profond : noyaux gris centraux +++, putamen +++ ; lobaire dans 10 %.","Microbleeds : pertes de signal multiples en T2* (dépôts d'hémosidérine) : sous-cortical, NGC, thalamus, pont, cervelet.","« Black ring sign » : hyposignal T2* avec un point central en hypersignal → en faveur d'une origine hypertensive.","Pas d'examen complémentaire nécessaire."]},{"titre":"2. Angiopathie amyloïde cérébrale","badge":"","ancre":"eti-amyloide","blocs":["Dépôts amyloïdes dans les petites artères corticales et leptoméningées.","Terrain : sujet âgé, non hypertendu, sans trouble de la coagulation.","Hémorragies récidivantes ; démence possible.","Hématomes lobaires multiples : frontal +++, cortex et substance blanche sous-corticale.","Microhémorragies cortico-sous-corticales en T2*.","Épargne : NGC, thalamus, protubérance, cervelet."]},{"titre":"3. Rupture de malformation artério-veineuse (MAV)","badge":"","ancre":"eti-mav","blocs":["Sujet jeune +++ : 20 à 40 ans.","Nidus : shunt artério-veineux qui court-circuite le lit capillaire normal.","Hématome intraparenchymateux ; HSA beaucoup moins fréquente.","Révélation : découverte fortuite, épilepsie, déficit neurologique ou hémorragie — l'hémorragie est la complication la plus fréquente et justifie le traitement.","À rechercher systématiquement devant tout hématome du sujet jeune, quel que soit son siège.","Artériographie = examen de référence : nidus, artères afférentes, veines de drainage opacifiées précocement.","TDM : hyperdensités tubulées serpigineuses, rehaussement intense ± calcifications.","IRM : vides de signal serpigineux en T2 autour de l'hématome ; T1 en écho de gradient + gadolinium = séquence la plus sensible ; nidus visible si l'IRM est faite avant 48 h, avant que l'hématome ne passe en hypersignal."]},{"titre":"4. Cavernome","badge":"","ancre":"eti-cavernome","blocs":["Capillaires dilatés à paroi fine, contenant du sang thrombosé ou à flux lent, sans parenchyme sain interposé.","Congénital, révélé entre la 3e et la 5e décennie.","Forme sporadique : lésion unique ; forme familiale : lésions multiples dans 20 %.","TDM : hyper- ou isodense ± petites calcifications.","IRM = examen de choix : lésion arrondie en « pop-corn » ; hémisphères (cortico-sous-cortical) 75 %, tronc cérébral 20 % ; couronne d'hémosidérine en hyposignal sur toutes les séquences, surtout en T2* +++ ; centre de signal variable."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Les 4 types IRM (classification de Zabramski) :"]},{"titre":"Subaigu (tardif)","badge":"1","ancre":"etiologies","blocs":["Centre en hypersignal T1, hyper- ou hyposignal T2."]},{"titre":"« Poivre et sel »","badge":"2","ancre":"etiologies","blocs":["Aspect le plus fréquent : saignements et thromboses d'âges différents ; centre réticulé, signaux mixtes et hétérogènes en T1 et en T2."]},{"titre":"Chronique","badge":"3","ancre":"etiologies","blocs":["Centre en hypo- ou isosignal T1, hyposignal T2."]},{"titre":"Minuscule","badge":"4","ancre":"etiologies","blocs":["Visible seulement en T2* : hyposignal T2* punctiforme."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Logettes avec niveaux liquide-liquide : très évocatrices.","Pas d'œdème ni d'effet de masse, sauf en cas de saignement.","Rehaussement inconstant, tardif, au centre ; injecter pour rechercher une anomalie veineuse de développement associée, qui modifie la prise en charge.","Diagnostic différentiel : tumeur.","Saignement important : diagnostic difficile ; l'aspect typique réapparaît après plusieurs mois."]},{"titre":"5. Anévrysme","badge":"","ancre":"eti-anevrysme","blocs":["Surtout HSA ; parfois hématome parenchymateux, souvent lobaire.","Sujet jeune +++.","Bilan : angioscanner cérébral, puis artériographie s'il est négatif.","Diagnostic : image d'addition.","À préciser : nombre, topographie ; sac : sacculaire ou fusiforme, taille, orientation, lobulation, thrombosé ou non ; collet : rapport collet / sac et artère porteuse."]},{"titre":"6. Transformation hémorragique d'un AVC ischémique","badge":"","ancre":"eti-transformation","blocs":["Dans les premiers jours de l'ischémie, le plus souvent après revascularisation par thrombolyse.","TDM : hyperdensité spontanée dans l'infarctus, systématisée à un territoire artériel.","IRM : signal variable, souvent hypersignal T1 et T2 (méthémoglobine).","Diagnostic différentiel : infarcissement hémorragique d'une TVC."]},{"titre":"7. Infarcissement hémorragique d'une thrombose veineuse cérébrale (TVC)","badge":"","ancre":"eti-tvc","blocs":["Contexte : post-partum, déshydratation, cancer, maladie hématologique… ; hématomes multiples.","TDM : hyperdensités spontanées multinodulaires (< 2 cm) ou linéaires dans une plage d'œdème ; hématome lobaire ; HSA.","IRM :","FLAIR → infarctus veineux : hypersignal sous-cortical mal limité, non systématisé ;","T2* → pétéchies corticales et sous-corticales ; hématome en hyposignal T2*, en hypersignal T1 après 48 h ;","T1 3D + gadolinium → diagnostic de certitude de la TVC."]},{"titre":"8. Tumeurs hémorragiques","badge":"","ancre":"eti-tumeur","blocs":["Mécanismes","Nécrose tumorale rapide.","Rupture de néovaisseaux.","Envahissement des vaisseaux voisins.","Étiologies","Métastases +++ : mélanome, tumeurs germinales, carcinome papillaire de la thyroïde.","Tumeurs primitives : gliomes malins, épendymomes, méningiomes, schwannomes, tumeurs neuro-ectodermiques primitives."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Hématome sur lésion sous-jacente : les critères qui doivent faire chercher une tumeur."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Critères morphologiques (examen initial)","Portion tissulaire qui se rehausse après injection, en périphérie ou à distance de l'hématome.","Hyperperfusion de cette portion tissulaire ou de la paroi.","Paroi épaisse, irrégulière ou nodulaire (≠ fin rehaussement annulaire régulier d'un hématome subaigu).","Contours irréguliers de l'hématome.","Hétérogénéité importante du signal ou de la densité.","Niveaux liquide-liquide.","Œdème vasogénique disproportionné par rapport à la taille de l'hématome.","Œdème qui ne régresse pas, ou progresse, au contrôle.","Restriction de la diffusion d'une composante tumorale solide.","Spectroscopie évocatrice si elle est faite : choline ↑, NAA ↓, parfois lipides et lactates."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Critère en T2* / SWI","Couronne d'hémosidérine absente ou incomplète, alors qu'autour d'un hématome bénin elle devient peu à peu complète."]},{"titre":"","badge":"","ancre":"etiologies","blocs":["Critères évolutifs (évolution atypique)","Dégradation de l'hémoglobine plus lente que prévu.","Hématome qui ne se résorbe pas normalement (contrôle à 3 mois).","Lésion qui augmente de volume au suivi.","Composante tissulaire persistante après la résorption de l'hématome."]}]}]},{"id":"sclerose-en-plaques","url":"fiches/sclerose-en-plaques.html","titre":"Sclérose en plaques : l'imagerie","spe":"neuro","sections":[{"id":"introduction","titre":"Introduction","rubriques":[{"titre":"Affections démyélinisantes","badge":"","ancre":"introduction","blocs":["Destruction d'une myéline initialement normale, parfois avec atteinte axonale.","Primitives : sclérose en plaques (SEP), neuromyélite optique de Devic, sclérose de Balo, maladies de Schilder et de Marburg.","Secondaires : origine vasculaire, infectieuse, métabolique ou carentielle."]},{"titre":"Affections dysmyélinisantes","badge":"","ancre":"introduction","blocs":["= leucodystrophies : anomalie de formation ou de maintien de la myéline."]},{"titre":"","badge":"","ancre":"introduction","blocs":["SEP : affection démyélinisante primitive la plus fréquente ; étiologie probablement auto-immune, déclenchée par un facteur infectieux chez des sujets génétiquement prédisposés."]}]},{"id":"epidemiologie","titre":"Épidémiologie","rubriques":[{"titre":"Âge de survenue","badge":"2","ancre":"epidemiologie","blocs":["Pic entre 20 et 40 ans.","15 % avant 20 ans ; 10 % après 50 ans.","Exceptionnelle chez l'enfant."]}]},{"id":"localisation","titre":"Anatomopathologie & localisation","rubriques":[{"titre":"","badge":"","ancre":"localisation","blocs":["Lésions focales, multiples et diffuses, de quelques mm à plusieurs cm."]},{"titre":"","badge":"","ancre":"localisation","blocs":["Substance blanche sus- et sous-tentorielle et moelle épinière.","Prédominance juxtaventriculaire (50 % des plaques) ; jonction substance blanche / grise (20 %).","Atteinte possible de la substance grise corticale et des noyaux gris.","Fréquente : tronc cérébral, pédoncules cérébelleux moyens, substance blanche cérébelleuse.","Très fréquente sur les voies visuelles : nerfs optiques, chiasma, tractus optiques.","Moelle cervicale touchée dans 80 % des cas."]},{"titre":"Où chercher les plaques : schéma","badge":"","ancre":"localisation","blocs":["Schéma simplifié. Survolez ou touchez une zone de la légende pour l'isoler."]}]},{"id":"clinique","titre":"Clinique : signes inauguraux évocateurs","rubriques":[{"titre":"Névrite optique rétrobulbaire (NORB)","badge":"1","ancre":"clinique","blocs":["Baisse d'acuité visuelle, douleurs rétro-orbitaires."]},{"titre":"Myélite aiguë","badge":"2","ancre":"clinique","blocs":["Paraparésie et troubles sensitifs d'installation rapide."]},{"titre":"Atteinte du tronc cérébral","badge":"3","ancre":"clinique","blocs":["Paralysies oculomotrices, ophtalmoplégie internucléaire, paralysie ou névralgie faciale, syndrome vestibulaire."]}]},{"id":"semiologie","titre":"Sémiologie IRM","rubriques":[{"titre":"Topographies évocatrices","badge":"","ancre":"semiologie","blocs":["Juxtaventriculaire (zone 1 du schéma) : angles latéraux et toit des ventricules ; plaques ovoïdes, > 3 mm.","Corps calleux (zone 5) : partie inférieure, aspect en « crête de coq » sur les coupes sagittales.","Pont, substance blanche péricorticale, pédoncules cérébelleux moyens."]},{"titre":"Plaque aiguë","badge":"T2","ancre":"semiologie","blocs":["Aspect en « cible » ou « cocarde ».","Centre hyperintense.","Périphérie moins intense.","Liseré hypointense."]},{"titre":"Prise de contraste","badge":"Gd","ancre":"semiologie","blocs":["Annulaire ou nodulaire en phase active (rupture de la BHE).","« Coup d'ongle » (open ring) : très évocateur d'une plaque active."]},{"titre":"Effet de masse","badge":"!","ancre":"semiologie","blocs":["Possible en phase aiguë.","Piège : peut simuler une tumeur ou un infarctus."]},{"titre":"Plaque chronique : « black hole »","badge":"T1","ancre":"semiologie","blocs":["Hypointense T1, hyperintense T2.","Pas de rehaussement.","Souvent cerclée d'un liseré hyperintense T1 spontané, non pathologique."]},{"titre":"Plaque lacunaire","badge":"LCS","ancre":"semiologie","blocs":["Signal liquidien (LCS) = destruction axonale totale."]},{"titre":"Névrite optique (NORB)","badge":"NO","ancre":"semiologie","blocs":["Hypersignal T2 / STIR du nerf optique dans 75-90 % des cas ; rehaussement possible du nerf ou de sa gaine."]},{"titre":"","badge":"","ancre":"semiologie","blocs":["Évolution (T1 / T2) : les plaques disparaissent rarement ; de nouvelles lésions peuvent apparaître sans aucun symptôme."]},{"titre":"Plaques aiguës vs anciennes","badge":"","ancre":"semiologie","blocs":["Critère","Plaques aiguës","Plaques anciennes","Signal T2","Hyperintense, parfois en cocarde","Hyperintense modéré","Signal T1","Hypointense modéré à fort","Hypointense, parfois black holes","FLAIR","Signal hétérogène, cocarde moins visible","Hypointense ou normalisé"]}]},{"id":"mcdonald","titre":"Diagnostic IRM : critères de McDonald 2017","rubriques":[{"titre":"","badge":"","ancre":"mcdonald","blocs":["But : diagnostiquer la SEP plus tôt en gardant une bonne spécificité. Il faut démontrer une dissémination dans l'espace (DIS) ET une dissémination dans le temps (DIT), par l'IRM ou par la clinique."]},{"titre":"1. Dissémination dans l'espace (DIS)","badge":"","ancre":"mcdonald","blocs":["Au moins une lésion dans 2 des 4 localisations typiques (IRM cérébrale ou médullaire) :","juxtacorticale ou corticale ;","périventriculaire ;","infratentorielle ;","médullaire.","Depuis 2017, les lésions symptomatiques comptent aussi ; le nerf optique ne fait pas partie des 4 localisations."]},{"titre":"2. Dissémination dans le temps (DIT)","badge":"","ancre":"mcdonald","blocs":["Lésions avec ET sans rehaussement sur la même IRM, quel que soit le moment de l'examen ;","OU nouvelle lésion sur une IRM de suivi, comparée à l'IRM de référence ;","OU bandes oligoclonales dans le LCR : elles remplacent la DIT après un premier événement clinique (CIS).","L'IRM confirme le diagnostic même sans nouvelle poussée ; l'interrogatoire retrouve des signes évocateurs chez 1/3 des patients dès le premier épisode."]},{"titre":"","badge":"","ancre":"mcdonald","blocs":["Localisations des lésions (DIS)"]},{"titre":"","badge":"","ancre":"mcdonald","blocs":["Dissémination dans le temps (DIT)"]},{"titre":"","badge":"","ancre":"mcdonald","blocs":["Outil d'enseignement : le diagnostic de SEP reste clinique (tableau évocateur, autres diagnostics écartés)."]}]},{"id":"protocole","titre":"Rôle de l'IRM & protocole","rubriques":[{"titre":"Détection des lésions","badge":"1","ancre":"protocole","blocs":["Technique la plus sensible : > 97 % avec encéphale + moelle."]},{"titre":"Diagnostic initial","badge":"2","ancre":"protocole","blocs":["Dissémination spatiale et temporelle selon McDonald."]},{"titre":"Suivi thérapeutique","badge":"3","ancre":"protocole","blocs":["Efficacité des traitements sur les lésions actives."]},{"titre":"Séquences encéphaliques","badge":"","ancre":"protocole","blocs":["Séquence / plan","Utilité principale","T2 ou FLAIR sagittal","Corps calleux ; recherche de malformation (ex. Chiari).","T2, DP, FLAIR axiaux","Lésions juxtaventriculaires et sous-corticales.","FLAIR","Très sensible pour la substance blanche sus-tentorielle.","T2 FSE axial","Bonne sensibilité dans la fosse postérieure.","T1 axial avant injection","Lésions hypointenses : black holes = lésions axonales irréversibles."]},{"titre":"IRM médullaire","badge":"","ancre":"protocole","blocs":["STIR sagittal : plus sensible que le T2 pour les plaques médullaires.","T2 écho de gradient axial : meilleure résolution transversale, moins d'artefacts de flux.","T1 après gadolinium : lésions actives.","Séquences 3D peu sensibles."]},{"titre":"Nerf optique","badge":"","ancre":"protocole","blocs":["T2 coronal STIR ou Fat Sat : inflammation.","T1 gadolinium avec suppression de graisse : prise de contraste pathologique."]},{"titre":"Gadolinium : indications & précautions","badge":"","ancre":"protocole","blocs":["Prise de contraste = rupture de la BHE = meilleur marqueur de l'activité inflammatoire.","Dose : dose simple, 0,1 mmol/kg (recommandations actuelles) ; acquisition retardée (5-15 min) dans certains cas.","Toujours des coupes T1 avant injection, pour éviter les faux positifs."]}]},{"id":"diffusion","titre":"Imagerie de diffusion dans la SEP","rubriques":[{"titre":"","badge":"","ancre":"diffusion","blocs":["La diffusion mesure les mouvements de l'eau, plus grands quand l'eau est libre. Dans la substance blanche normale, elle est anisotrope (surtout parallèle aux axones).","Situation","Diffusion","À retenir","Démyélinisation","↑ eau libre · ↓ anisotropie","Destruction axonale.","Plaque non active","↑ ADC","Corrélé à l'hypointensité T1 ; augmentation proportionnelle à la sévérité de la maladie.","Plaque active","↓ ADC possible"]}]},{"id":"pronostic","titre":"Facteurs pronostiques & critères de gravité IRM","rubriques":[{"titre":"","badge":"","ancre":"pronostic","blocs":["Signe IRM","Signification","Charge lésionnelle sus-tentorielle (T2)","Corrélée à la gravité ; faible corrélation globale avec le handicap.","Lésions multiples très hypointenses T1 / black holes","Atrophie corticale marquée ; gravité et progression.","Lésions lacunaires","Perte axonale, gliose centrale ; même pronostic que les black holes.","Sillons élargis, ventricules dilatés","Évolution vers des formes avancées.","Noyaux gris très hypointenses en T2","Formes anciennes, surcharge en fer."]}]}]},{"id":"nodule-pulmonaire","url":"fiches/nodule-pulmonaire.html","titre":"Conduite à tenir devant un nodule pulmonaire","spe":"thorax","sections":[{"id":"introduction","titre":"Introduction – définition, enjeux et contexte","rubriques":[{"titre":"1. Définition","badge":"","ancre":"introduction","blocs":["Un nodule pulmonaire est une opacité focale ronde, bien ou moyennement bien définie, de 3 mm à 3 cm de diamètre maximal. Il peut être solide, en verre dépoli ou mixte.","Solide","Verre dépoli","Mixte","Malin","Surtout métastase ou cancer bronchopulmonaire primitif.","Bénin","80 % sont des granulomes ou ganglions intrapulmonaires ; l'hamartochondrome est la tumeur bénigne la plus fréquente.","Enjeu : ne pas méconnaître une lésion maligne curable, sans multiplier les explorations invasives ou irradiantes pour une lésion bénigne."]},{"titre":"2. Contexte clinique indispensable","badge":"Découverte : fortuitedépistage organisésurveillance d'un patient cancéreux","ancre":"introduction","blocs":["Âge, sexe, tabagismeExposition à l'amiante, au radium ou à l'uraniumAntécédents familiaux de cancer pulmonaire Fibrose pulmonaire/UIP, emphysèmeImmunodépressionSymptômesAntécédent personnel de néoplasie","Une localisation au lobe supérieur majore la probabilité de malignité."]},{"titre":"3. Objectifs de l'imagerie","badge":"","ancre":"introduction","blocs":["Reconnaîtrele nodule et éliminer un faux positif radiographique ou scanographique.","Identifier d'embléeune lésion typiquement bénigne ou, à l'inverse, hautement suspecte.","Nodule indéterminéproposer une stratégie cohérente : surveillance, TEP, biopsie ou résection."]}]},{"id":"exploration","titre":"Moyens d'exploration","rubriques":[{"titre":"","badge":"","ancre":"exploration","blocs":["Faux nodules en radiographie"]},{"titre":"1. Radiographie thoracique","badge":"","ancre":"exploration","blocs":["Face + profil. Environ 20 % des images nodulaires sont des faux nodules : mamelon, opacité cutanée ou structure osseuse."]},{"titre":"2. TDM multicoupes = examen de référence","badge":"","ancre":"exploration","blocs":["Coupes millimétriques, basse dose avec CTDIvol < 3 mGy, thorax entier, inspiration profonde ; TAP selon le contexte.","MIP pour la détection ; images natives indispensables à l’analyse fine, surtout du verre dépoli ; MPR et volumétrie.","Filtre standard pour les calcifications ; filtre poumon pour mesurer précisément un nodule < 10 mm.","Pas d'injection systématique : contraste réservé à l'étude du rehaussement ou au bilan d'extension."]},{"titre":"3. Autres examens","badge":"","ancre":"exploration","blocs":["Fibroscopie bronchiqueTEP-scanIRMBiopsie transpariétale ou transbronchique"]}]},{"id":"caracterisation","titre":"Caractérisation TDM et classement initial","rubriques":[{"titre":"1. Caractérisation systématique","badge":"","ancre":"caracterisation","blocs":["Densité","solide, verre dépoli ou mixte.","Forme","à analyser sur MPR et reconstructions volumiques.","Contours","réguliers, lobulés ou spiculés.","Contenu","graisse, calcifications, bronchogramme ou clartés aériques.","Localisation","et rapports ; mesure précise du diamètre ou du volume ; comparaison avec tous les examens antérieurs, surtout le plus ancien."]},{"titre":"Atélectasie ronde : 3 critères","badge":"Condensation linéaireImpaction mucoïde/bronchocèleMalformation artério-veineuseNodule pleuralNodule transitoire disparaissant au contrôle","ancre":"caracterisation","blocs":["contact avec un épaississement pleural","+ perte de volume lobaire","+ enroulement des axes broncho-vasculaires."]},{"titre":"","badge":"","ancre":"caracterisation","blocs":["Atélectasie ronde"]},{"titre":"Bénin","badge":"","ancre":"caracterisation","blocs":["critères caractéristiques → arrêt des investigations."]},{"titre":"Hautement suspect","badge":"","ancre":"caracterisation","blocs":["bilan d’extension puis preuve/résection."]},{"titre":"Indéterminé","badge":"","ancre":"caracterisation","blocs":["intégrer risque, taille, densité et croissance pour choisir surveillance, TEP ou histologie."]}]},{"id":"benignite","titre":"Arguments de bénignité","rubriques":[{"titre":"Hamartochondrome","badge":"","ancre":"benignite","blocs":["Amas graisseux internes de densité < -40 UH et calcifications en pop-corn.","Analyser en filtre standard ; attention au volume partiel, qui peut masquer une petite plage graisseuse ou une calcification."]},{"titre":"Ganglion intrapulmonaire","badge":"","ancre":"benignite","blocs":["Triangulaire ou en béret basque, lisse, parfois concave, généralement < 1 cm et situé à moins de 1 cm de la plèvre ou en sous-carénaire.","Peut augmenter de taille sans que cette croissance soit obligatoirement maligne."]},{"titre":"Calcifications bénignes","badge":"","ancre":"benignite","blocs":["Type 1 calcification en masse","Type 2 nidus central","Type 3 strates concentriques","Type 4 pop-corn (hamartochondrome).","2 ans","Nodule solide stable 2 ans : TD > 730 jours, argument majeur de bénignité."]}]},{"id":"malignite","titre":"Signes morphologiques de malignité","rubriques":[{"titre":"1. Contours","badge":"","ancre":"malignite","blocs":["Réguliers","Lobulations : croissance anarchique, présentes dans 40 % des nodules malins.","Spiculations : VPP d’environ 90 %, mais possibles dans la granulomatose avec polyangéite (Wegener) et la pneumonie organisée.","En cas d'emphysème, une spiculation peut correspondre à une cicatrice fibreuse et perd de sa valeur prédictive."]},{"titre":"2. Structure interne","badge":"","ancre":"malignite","blocs":["bronchogramme aérique dans 30 % des nodules malins contre 5 % des bénins : clartés centrales, bubble-like lucencies ou pseudo-cavitation. Différentiel : pneumonie organisée.","Excavation : paroi > 15 mm associée à une malignité dans 95 % des cas.","Calcifications suspectes : excentrées (type 5)","ou microcalcifications (type 6)."]},{"titre":"3. Taille, siège et distribution","badge":"","ancre":"malignite","blocs":["Le risque augmente avec le diamètre et un siège supérieur. Plusieurs nodules groupés dans un secteur évoquent plutôt infection ou granulomatose.","En contexte oncologique, même un nodule < 4 mm peut être évolutif.","À retenir : aucun signe isolé ne suffit. L'orientation repose sur la combinaison du contexte, de la densité, des contours, du contenu, de la taille et surtout de l'évolution."]}]},{"id":"croissance","titre":"Nodules non solides et évaluation de la croissance","rubriques":[{"titre":"1. Nodules non solides","badge":"","ancre":"croissance","blocs":["Leur probabilité de malignité est supérieure à celle des nodules solides et leur croissance peut être très lente : surveillance jusqu'à 5 ans.","Verre dépoli : éliminer une origine inflammatoire/infectieuse par un contrôle ; s'il persiste, discuter fibrose, pneumonie interstitielle desquamative et spectre de l'adénocarcinome.","Hyperplasie adénomateuse atypique","Carcinome in situ","Adénocarcinome mini-invasif","Nodule mixte : plus suspect qu'un verre dépoli pur. Après traitement éventuel, contrôle à 1-3 mois ; s'il persiste, suspicion forte : 80-90 % des nodules mixtes < 20 mm sont des adénocarcinomes.","Synthèse par type de nodule","Solide","Croissance plus rapide ; stabilité 2 ans rassurante. Point décisif : taille, contours, TD, TEP si > 8 mm.","Verre dépoli pur","Croissance lente ; spectre pré-invasif possible. Point décisif : persistance et apparition d'un contingent solide.","Mixte"]},{"titre":"2. Évaluation de la croissance","badge":"","ancre":"croissance","blocs":["Moyenne (grand axe + petit axe)/2, arrondie au millimètre ; ne pas inclure les spiculations.","Mesure : coupes < 1,5 mm en filtre poumon ; mesurer en zoom ou par volumétrie ; moyenne (grand axe + petit axe)/2, arrondie au millimètre.","Ne pas inclure les spiculations. Toujours comparer à l'examen le plus ancien disponible.","Critères d'un nodule évolutif : augmentation du diamètre d’au moins 2 mm ou croissance asymétrique.","Pour un non-solide : croissance/apparition de la composante solide, ou transformation d'un verre dépoli pur en nodule mixte.","Augmentation du diamètre ≥ 2 mm","Croissance asymétrique","Verre dépoli pur → nodule mixte"]}]},{"id":"tep","titre":"TEP, biopsie et chirurgie","rubriques":[{"titre":"TEP-scan","badge":"","ancre":"tep","blocs":["Recommandé pour un nodule solide > 8 mm ; intérêt majeur pour le bilan d'extension thoracique et extrathoracique.","Faux négatifs","nodule < 8 mm et nodule non solide/adénocarcinome lent peu métabolique.","Faux positifs","tuberculose, sarcoïdose et granulomes."]},{"titre":"Biopsie et résection","badge":"","ancre":"tep","blocs":["Biopsie sous TDM : sa valeur repose surtout sur sa positivité ; une biopsie négative n’exclut pas la malignité. Discussion en RCP ; limite pratique souvent > 1 cm.","Nodule mixte : cibler impérativement la portion solide.","Pour un petit nodule/non solide : repérage préopératoire possible par harpon ou coil avant résection wedge."]},{"titre":"","badge":"","ancre":"tep","blocs":["Nodule mixte : cibler la portion solide"]}]},{"id":"fleischner","titre":"Surveillance — Fleischner 2017 (découverte fortuite)","rubriques":[{"titre":"","badge":"","ancre":"fleischner","blocs":["1. Nodules solides","< 6 mm (unique ou multiples) : pas de suivi si faible risque ; TDM à 12 mois optionnelle si haut risque.","6-8 mm unique : TDM 6-12 mois +/- 18-24 mois (faible risque) ; TDM 6-12 mois + 18-24 mois (haut risque).","6-8 mm multiples : TDM 3-6 mois +/- 18-24 mois (faible risque) ; TDM 3-6 mois puis 18-24 mois (haut risque).","> 8 mm unique : TDM à 3 mois, PET-TDM et/ou biopsie selon le contexte (même stratégie, faible ou haut risque).","> 8 mm multiples : TDM 3-6 mois +/- 18-24 mois (faible risque) ; TDM 3-6 mois +/- 18-24 mois (haut risque).","2. Nodules non solides","< 6 mm, unique : pas de suivi. < 6 mm, multiples : TDM 3-6 mois, puis à 2 ans et 4 ans.","Verre dépoli pur ≥ 6 mm : TDM 6-12 mois, puis tous les 2 ans jusqu'à 5 ans.","Mixte ≥ 6 mm ; solide < 6 mm : TDM 3-6 mois pour confirmer, puis annuelle pendant 5 ans.","Mixte ≥ 6 mm ; solide ≥ 6 mm : histologie.","Multiples : TDM 3-6 mois, puis conduite basée sur le nodule le plus suspect."]},{"titre":"Facteurs de haut risque","badge":"","ancre":"fleischner","blocs":["TabagismeÂge et sexeAmiante/radium/uraniumAntécédents familiauxLobe supérieurEmphysème ou fibrose/UIP"]},{"titre":"Champ des recommandations","badge":"","ancre":"fleischner","blocs":["Les tableaux Fleischner concernent les nodules de découverte fortuite. Chez un patient déjà suivi pour un cancer, la conduite est individualisée et même un nodule de moins de 4 mm peut être évolutif."]},{"titre":"","badge":"","ancre":"fleischner","blocs":["Dans l'éditeur des comptes rendus, l'outil « Fleischner » rédige la phrase du nodule et la conduite à tenir."]}]},{"id":"compte-rendu","titre":"Compte rendu TDM standardisé et synthèse","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["1. Compte rendu TDM standardisé — cochez au fil de la lecture :","0 / 7 rubriques"]},{"titre":"Faux nodule et MIP seules","badge":"Radio","ancre":"compte-rendu","blocs":["Confondre une image nodulaire radiographique avec un vrai nodule ; oublier les images natives au profit des seules MIP."]},{"titre":"Spiculations et comparaison","badge":"Mesure","ancre":"compte-rendu","blocs":["Mesurer avec les spiculations, comparer seulement au dernier contrôle ou conclure à la bénignité d'un non-solide stable pendant 2 ans."]},{"titre":"Faux réconfort","badge":"TEP / biopsie","ancre":"compte-rendu","blocs":["Interpréter une TEP négative comme rassurante pour un nodule < 8 mm ou non solide ; considérer une biopsie négative comme une exclusion formelle de malignité."]},{"titre":"Mauvaise cible","badge":"Mixte","ancre":"compte-rendu","blocs":["Dans un nodule mixte, biopsier le verre dépoli au lieu du contingent solide."]},{"titre":"Synthèse ultime","badge":"","ancre":"compte-rendu","blocs":["Solide stable 2 ans = bénignité. Mixte persistant = le plus inquiétant. Croissance ≥ 2 mm = évolutif. TEP > 8 mm. Non-solide : suivi 5 ans."]}]}]},{"id":"masses-mediastinales","url":"fiches/masses-mediastinales.html","titre":"Imagerie des masses médiastinales","spe":"thorax","sections":[{"id":"introduction","titre":"Introduction – généralités","rubriques":[{"titre":"1. Définition","badge":"","ancre":"introduction","blocs":["Médiastin : espace central du thorax, région complexe, zone de transit, organes nobles, limites, communications ; apparaît très tôt dans l'embryogénèse.","Masse médiastinale : processus expansif développé dans le médiastin et responsable d'un syndrome médiastinal clinique et/ou radiologique."]},{"titre":"Englobe / exclues","badge":"","ancre":"introduction","blocs":["Englobe : tumeurs, ADP, pseudo-tumeurs vasculaires, liquidiennes/méningocèles, graisseuses/hernies, infectieuses/collections.","Exclues : masses médiastinales de l'enfant, anévrysmes, collections."]},{"titre":"2. L'imagerie intervient à toutes les étapes","badge":"","ancre":"introduction","blocs":["Diagnostic positif","diagnostic topographique","diagnostic de nature (étiologique)","bilan d'extension","diagnostic de certitude en guidant la ponction-biopsie transpariétale sous contrôle échographique ou TDM","suivi post-opératoire"]},{"titre":"3. Présentation clinique","badge":"","ancre":"introduction","blocs":["50 %","Découverte systématique : 50 %","Emprunt","Symptomatologie d'emprunt : compression médiastinale ; signes respiratoires, digestifs, neurologiques, vasculaires."]}]},{"id":"exploration","titre":"Moyens d'exploration et protocoles","rubriques":[{"titre":"1. Moyens d'exploration","badge":"Sécrétion de peptides → carcinoïde Anticorps antiacétylcholine → myasthénie Hypercalcémie","ancre":"exploration","blocs":["Radiographie du thorax (face + profil) TDM hélicoïdale ++++ Échographie thoracique +/-IRMTransit œsophagienPonction-biopsie Scintigraphie : iode marqué, MIBG, MIBI, octréotidePET scanETO","Volume thoracique complet étendu aux frontières ; SPC basse dose.","Injection : bras gauche, débit variable (+/- thyroïde), pour opacifier le tronc veineux innominé gauche : étudier sa perméabilité et baliser le médiastin de gauche vers la droite, séparant la chaîne médiastinale antérieure du plan artériel en arrière.","Acquisition au temps précoce +/- temps tardif : syndrome cave, 80 s, 2 cc/s ; masse kystique, 2 min. Reconstructions.","Avantages : résolution spatiale ; accessibilité (urgences)."]}]},{"id":"compartiments","titre":"Anatomie radiologique et démarche diagnostique","rubriques":[{"titre":"1. Compartiments de Felson","badge":"","ancre":"compartiments","blocs":["Cliquez un compartiment : il s'allume dans la vue 3D."]},{"titre":"2. Compartiments de Heitzman — en 3D","badge":"","ancre":"compartiments","blocs":["Médiastin para-orificiel : les compartiments qui communiquent","OCM → cou ACPA, ACPP, EIMP → étage supérieur de l'abdomen EPTO → hiles GCV → canal rachidien"]},{"titre":"Diagnostic positif","badge":"","ancre":"compartiments","blocs":["Opacité ; anomalie des contours du médiastin ; lignes déplacées ; bandes élargies ; contours déformés.","Radiographie normale + symptômes cliniques = TDM."]},{"titre":"Diagnostic topographique","badge":"","ancre":"compartiments","blocs":["Une fois repérée, l'opacité médiastinale doit être localisée ; la topographie représente l'une des bases de la discussion diagnostique ; signe de la silhouette et signes dérivés ; si l'opacité est volumineuse, son siège devient difficile à préciser."]},{"titre":"","badge":"","ancre":"compartiments","blocs":["Diagnostic différentiel — retournez les cartes :"]},{"titre":"4. Démarche étiologique","badge":"","ancre":"compartiments","blocs":["Biologie/clinique occasionnellement contributives. Associez chaque indice à sa piste :","1Compartiment où siège la masse","2Comportement de la masse en TDM et en IRM → orientation tissulaire","3Âge, sexe, fréquence"]}]},{"id":"orientation","titre":"Orientation tissulaire TDM / IRM","rubriques":[{"titre":"","badge":"","ancre":"orientation","blocs":["Hydrique","autour de 0 UH ; non rehaussée ; hypo T1, hyper T2.","Tissulaire","15 à 50 UH ; iso T1 ; rehaussée.","Graisseuse","< -40 UH ; hyper T1 et T2.","Vasculaire","Rehaussement de type vasculaire.","Composite","Densités mixtes."]}]},{"id":"anterieur","titre":"Médiastin antérieur","rubriques":[{"titre":"","badge":"","ancre":"anterieur","blocs":["Tissulaire","goitres thyroïdiens ; lymphomes ; thymomes ; tératomes ; adénome parathyroïdien.","Kystique/kystisée","kyste pleuropéricardique ; thymome kystique ; kyste thymique ; lymphangiome kystique ; kyste hydatique ; tératome kystique.","Graisseuse","hernie de Larrey/Morgagni ; tératome ; thymolipome ; lipome/liposarcome.","Réfléchir en fonction de la fréquence."]},{"titre":"2. Goitre endothoracique","badge":"","ancre":"anterieur","blocs":["13 %","13 % des tumeurs du médiastin antérieur.","80 %","Migration antérieure classique : 80 %.","Rare","Goitre hétérotopique ; goitre ectopique exceptionnel.","Densité spontanée élevée ; calcifications ; rehaussement immédiat, intense et prolongé.","SPC si traitement par iode marqué ou TSH basse - ou goitre malin, cancer papillaire ou folliculaire différencié - pour ne pas saturer les sites iodophiles.","Types et grades du goitre","TDM, préciser :","extension pré- ou rétrovasculaire","prolongement rétrotrachéal"]}]},{"id":"moyen","titre":"Médiastin moyen","rubriques":[{"titre":"","badge":"","ancre":"moyen","blocs":["Masses tissulaires","ADP ; tumeurs œsophagiennes ; tumeurs trachéales ; tumeurs neurogènes.","Masses kystiques/kystisées","kyste bronchogénique ; kyste entérogène/duplication digestive ; ADP nécrosées ; lymphangiome ; goitre kystisé ; tératome kystique ; kyste hydatique.","Masses graisseuses","hernie ; lipome ; liposarcome."]},{"titre":"Kyste bronchogénique","badge":"","ancre":"moyen","blocs":["Dérivé kystique de l'intestin primitif antérieur ; 10 % des masses médiastinales et 60 % des kystes congénitaux.","EPTO ; espace sous- et rétro-carinaire ; siège ubiquitaire, parfois diaphragmatique.","Le plus souvent asymptomatique ; complications : hémorragie, surinfection.","TDM : masse liquidienne à paroi fine ; densité variable 0 à 100 UH ; mucus protéique, hémorragie, calcifications possibles.","IRM : signal variable ; hyper T2 ; T1 variable. Traitement : chirurgie - complications, dégénérescence."]},{"titre":"Maladie de Castleman","badge":"","ancre":"moyen","blocs":["Désordre lymphoprolifératif ; forme hyaline vasculaire localisée, PDC ++ ; forme plasmocytaire multicentrique ; tous les compartiments peuvent être atteints.","TDM - forme unicentrique : masse ganglionnaire unique, bien limitée, de densité tissulaire, homogène si petite ; rehaussement intense et précoce, parfois proche de celui des structures vasculaires ; possibles vaisseaux nourriciers hypertrophiés péri- ou intralésionnels.","Les grosses masses peuvent devenir hétérogènes par fibrose, nécrose ou calcifications.","Forme multicentrique : adénopathies multiples dans plusieurs territoires, souvent associées à une splénomégalie ; peut simuler un lymphome."]},{"titre":"Autres masses du médiastin moyen","badge":"Autres","ancre":"moyen","blocs":["Léiomyome œsophagien ; goitre plongeant type C ; tumeur trachéale.","Goitre endothoracique plongeant de type C : migration à droite plus facile ; à gauche, migration gênée par la crosse aortique : en arrière de l'axe trachéo-œsophagien ou entre trachée et œsophage.","Liposarcome : 6 % ; homme > 40 ans ; symptomatique ; lipome myxoïde de bas grade/intermédiaire dans 50 %, médiastin antérieur +++ ; autres : lipome, kyste dermoïde ; DD lipomatose ou hernie graisseuse."]}]},{"id":"posterieur","titre":"Médiastin postérieur","rubriques":[{"titre":"","badge":"","ancre":"posterieur","blocs":["Tissulaire","tumeurs neurogènes ; hématopoïèse extramédullaire ; lymphome ; tumeurs osseuses.","Kystique","spondylodiscite ; méningocèle ; kyste hydatique.","Graisseuse","lipome/liposarcome ; hernie de Bochdalek."]},{"titre":"Tumeurs neurogènes","badge":"","ancre":"posterieur","blocs":["20 %","des tumeurs médiastinales de l'adulte","90 %","dans le médiastin postérieur","75 %","des tumeurs du médiastin postérieur","95 %","bénignes chez l'adulte","40 %","souvent malignes chez l'enfant","Arguments : masse bien limitée de la gouttière costo-vertébrale, ronde, ovalaire ou en sablier ; prolongement le long d'un trajet nerveux ; élargissement foraminal.","TDM : densité tissulaire avec rehaussement ; recherche de calcifications, kystisation ou nécrose ; étude des foramens, du canal rachidien et des structures osseuses."]},{"titre":"Schwannome kystique, tumeur des gaines nerveuses","badge":"Bénin","ancre":"posterieur","blocs":["Bénin, adulte 20-50 ans ; IRM +++ : SE T1 intermédiaire +/- zone centrale d'hyposignal ; SE T2 hypersignal diffus non homogène +/- zone centrale en hypersignal ; kystisation, calcification."]},{"titre":"Neurofibrome","badge":"Signe","ancre":"posterieur","blocs":["Aspect en cible."]},{"titre":"Ganglioneurome","badge":"Adolescent","ancre":"posterieur","blocs":["Tumeur bénigne de l'adolescent ou de l'adulte jeune ; ganglions sympathiques ou exceptionnellement ganglions des racines médullaires ; rare sécrétion de VIP."]},{"titre":"Paragangliome","badge":"« Poivre et sel »","ancre":"posterieur","blocs":["Sécrétant ou non ; bénin ou malin ; médiastin moyen - aorte, OG - ou postérieur 80 % ; IRM : hyper T2, prise de contraste intense avec hyposignaux de flux, « poivre et sel »."]},{"titre":"Hématopoïèse extramédullaire","badge":"Hémopathie","ancre":"posterieur","blocs":["Hémopathie avec remplacement médullaire ou anémie hémolytique ; masses tissulaires des GCV, uni-/bilatérales, rehaussées, parfois graisseuses ; scintigraphie aux colloïdes marqués au 99mTc."]},{"titre":"Chondrosarcome","badge":"Os","ancre":"posterieur","blocs":["Masse tissulaire de la GCV avec calcifications lobulées et ostéolyse de l'arc postérieur costal ; IRM T1 hétérogène, hyper T2 intense, contours lobulés, compression trachée/VCS."]},{"titre":"Kyste hydatique","badge":"Ubiquitaire","ancre":"posterieur","blocs":["Masse liquidienne multivésiculaire ; 0,1-0,5 % des localisations et 4 % des masses médiastinales ; siège ubiquitaire, médiastin postérieur +++."]}]},{"id":"conclusion","titre":"Conclusion / certitude étiologique","rubriques":[{"titre":"","badge":"","ancre":"conclusion","blocs":["Point de départradiographie du thorax","TDM/IRMcompartiment, comportement et bilan d'extension","Certitudeimagerie, prélèvement ou chirurgie."]},{"titre":"Techniques invasives","badge":"","ancre":"conclusion","blocs":["Ponction transbronchique, sous écho-endoscopie ou sous médiastinoscopie ; ponctions percutanées : interposition possible de vaisseaux, cœur, arbre trachéobronchique et poumon ; abords particuliers, artifices techniques."]}]}]},{"id":"amylose-thoracique","url":"fiches/amylose-thoracique.html","titre":"Amylose thoracique : une affection bénigne mais déroutante","spe":"thorax","sections":[{"id":"objectifs","titre":"Objectifs pédagogiques","rubriques":[{"titre":"","badge":"","ancre":"objectifs","blocs":["Décrire les caractéristiques en imagerie de l’amylose thoracique et les corréler aux données anatomopathologiques.","Mettre en lumière les difficultés diagnostiques liées au mimétisme de cette affection avec d’autres pathologies thoraciques."]}]},{"id":"contexte","titre":"Contexte","rubriques":[{"titre":"","badge":"","ancre":"contexte","blocs":["L’amylose correspond au dépôt extracellulaire de protéines amyloïdes dans divers organes, incluant les poumons.","L’amylose thoracique peut être isolée ou s’inscrire dans le cadre d’un processus systémique, et reste souvent sous-diagnostiquée en raison de la diversité de ses présentations.","Le diagnostic de certitude repose sur l'anatomopathologie, mettant en évidence une biréfringence vert-jaune après coloration par le rouge Congo.","Les aspects en imagerie comprennent des atteintes trachéobronchiques, parenchymateuses, médiastinales, ganglionnaires et pleurales, simulant fréquemment des lésions malignes."]}]},{"id":"resultats","titre":"Résultats (Observations)","rubriques":[{"titre":"","badge":"","ancre":"resultats","blocs":["L’amylose pulmonaire se manifeste sous différents aspects radiologiques, incluant des formes parenchymateuses nodulaires, alvéolo-septales diffuses, kystiques et trachéobronchiques."]}]},{"id":"pulmonaire","titre":"Amylose pulmonaire","rubriques":[{"titre":"","badge":"","ancre":"pulmonaire","blocs":["L’amylose pulmonaire est plus souvent un processus localisé qu'une atteinte systémique. Elle se présente selon deux aspects radiologiques distincts : l’amylose pulmonaire nodulaire et l’amylose alvéolo-septale. Cependant, les constatations en imagerie sont souvent non spécifiques, nécessitant des investigations complémentaires pour un diagnostic de certitude."]},{"titre":"","badge":"","ancre":"pulmonaire","blocs":["La présentation typique est observée chez un adulte asymptomatique, le plus souvent au cours de la sixième décennie, à l’occasion d’anomalies fortuites découvertes sur une radiographie thoracique.","En scanner (TDM), l’amylose nodulaire (AN) se présente sous la forme de nodules pulmonaires solitaires ou multiples et peut mimer diverses pathologies, notamment des infections granulomateuses et des tumeurs malignes.","L’AN est communément associée aux formes localisées d’amylose.","Des dépôts pseudotumoraux solitaires, appelés amyloïdomes en l’absence de maladie systémique, sont identifiés dans environ 60 % des cas. Des nodules pulmonaires multiples sont fréquemment observés, prédominant dans les lobes supérieurs, présentant les caractéristiques suivantes :","Des contours lisses, lobulés ou spiculés pouvant faire suspecter une malignité.","Des calcifications centrales ou punctiformes parfois présentes.","De rares cavités.","Avec le temps, ces nodules peuvent croître et évoluer vers des masses plus volumineuses, atteignant jusqu’à 15 cm.","Une condensation au sein du parenchyme pulmonaire peut également être observée, pouvant évoquer d'autres affections telles qu'une infection ou une inflammation.","En raison de la variabilité de la présentation en imagerie, l’obtention d’un diagnostic de certitude basé uniquement sur l’imagerie est difficile. Bien qu’une évaluation clinique détaillée puisse éveiller les soupçons, une confirmation histopathologique par biopsie est souvent nécessaire, la plupart des dépôts étant constitués d’amylose AL.","L’évolution naturelle de l’amylose parenchymateuse nodulaire est généralement indolente, les lésions augmentant lentement en taille et en nombre. Malgré cela, le pronostic global demeure excellent et un traitement est rarement requis."]},{"titre":"","badge":"","ancre":"pulmonaire","blocs":["Fig. 1Amylose nodulaire. TDM thoracique avec injection de produit de contraste iodé montrant deux nodules au contact de la plèvre médiastinale, l'un apical et l'autre dans le lobe inférieur gauche flèches.","Fig. 2Amylose parenchymateuse se présentant sous la forme d'une masse. TDM thoracique sans injection montrant une masse du lobe inférieur gauche contenant des calcifications."]},{"titre":"","badge":"","ancre":"pulmonaire","blocs":["L’amylose pulmonaire alvéolo-septale, bien que moins fréquente, a souvent un impact clinique plus significatif que la forme parenchymateuse nodulaire. Les patients atteints de ce type sont plus fréquemment symptomatiques et présentent un risque accru d’évolution vers une hypertension pulmonaire et une insuffisance respiratoire. …","Des réticulations.","Un épaississement des septa interlobulaires.","Un épaississement de l'interstitium péri-bronchovasculaire.","Des micronodules pouvant présenter une distribution lymphatique, aléatoire ou centrilobulaire.","Des opacités en verre dépoli.","Des condensations.","Les micronodules peuvent être périlymphatiques, mimant les aspects observés dans la lymphangite carcinomateuse.","Plus rarement, on observe des remaniements kystiques, des calcifications et des signes d’emphysème basal, ces derniers étant secondaires à la destruction des parois alvéolaires.","Le diagnostic différentiel en imagerie inclut :","La silicose","La sarcoïdose"]},{"titre":"","badge":"","ancre":"pulmonaire","blocs":["Fig. 3Amylose parenchymateuse se présentant sous la forme d'une pneumopathie interstitielle diffuse (PID). TDM thoracique en fenêtre parenchymateuse montrant des micronodules de distribution aléatoire.","Fig. 4Amylose se présentant sous la forme d'un manchon péri-bronchovasculaire. TDM thoracique en fenêtre parenchymateuse montrant un manchon péri-bronchovasculaire débutant au niveau des bronches souches et entraînant un rétrécissement des bronches lobaires supérieures et de la bronche apicale du lobe inférieur gauche flèches."]}]},{"id":"tracheobronchique","titre":"Amylose trachéobronchique","rubriques":[{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["L’amylose trachéobronchique (ATB) est principalement caractérisée par des dépôts amyloïdes sous-muqueux focaux, multifocaux ou diffus touchant la trachée et les bronches souches, l’atteinte des bronches segmentaires étant rare. Bien qu’elle soit le plus souvent isolée, une atteinte des voies aériennes peut s'observer au cours de l’amylose systémique, mais de façon moins fréquente. …","L’atteinte des voies aériennes, y compris de la trachée, se présente habituellement sous forme de plaques sous-muqueuses, mais peut occasionnellement prendre l’aspect de dépôts solitaires mimant un néoplasme endobronchique. Les symptômes associent fréquemment dyspnée, toux, sibilants (wheezing), hémoptysie et pneumopathies récidivantes."]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["Les signes scanographiques typiques comprennent :","Un épaississement nodulaire de la paroi trachéale (60 %)","Des calcifications (53 %)","Une obstruction des voies aériennes (47 %)"]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["La paroi bronchique ou trachéale atteinte peut présenter une hyperatténuation en rapport avec des calcifications ou des ossifications. La mise en évidence d’un épaississement pariétal hyperdense associé à un sténose (rétrécissement) sur un long segment de la lumière doit fortement faire suspecter une amylose.","Fig. 5Amylose trachéale. TDM thoracique avec injection de produit de contraste, en fenêtres médiastinale et parenchymateuse, et reconstruction sagittale, montrant un épaississement circonférentiel étendu et un rehaussement de la paroi trachéale, réduisant sa lumière flèches, chez un patient consultant pour une dyspnée. Confirmation obtenue par biopsie endoscopique."]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["Trois schémas d’atteinte des voies aériennes ont été décrits :","Proximale (atteinte trachéale haute), se manifestant souvent par des symptômes des voies aériennes supérieures.","Moyenne ou distale (atteinte de la trachée et des bronches principales), entraînant des symptômes des voies aériennes inférieures, un collapsus lobaire ou des pneumopathies récidivantes."]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["Le diagnostic différentiel comprend :","La granulomatose avec polyangéite","Les affections granulomateuses (telles que la tuberculose ou la sarcoïdose)","Les maladies inflammatoires chroniques intestinales (MICI)"]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["Les principaux éléments permettant de la différencier d’autres pathologies (telles que la trachéobronchopathie ostéo-chondroplastique ou la polychondrite atrophiante) incluent l’atteinte de la membrane trachéale postérieure dans l’ATB, une anomalie absente dans les affections cartilagineuses.","Par conséquent, devant une imagerie montrant :","Un épaississement hyperdense de la paroi des voies aériennes","Un rétrécissement étendu (long-segmentaire)","Le diagnostic d’amylose doit être vigoureusement évoqué."]},{"titre":"","badge":"","ancre":"tracheobronchique","blocs":["Atteinte diffuse ± sténosante de la paroi trachéobronchique","Membrane trachéale postérieure","Épaissie","Amylose Granulomatose avec polyangéite (Wegener) Tuberculose","Calcifications","Présentes","Amylose","Absentes ou tardives","Granulomatose avec polyangéite (Wegener) Tuberculose","Respectée","Polychondrite atrophiante Trachéobronchopathie ostéo-chondroplastique","Trachéobronchopathie ostéo-chondroplastique"]}]},{"id":"mediastinale","titre":"Amylose médiastinale","rubriques":[{"titre":"","badge":"","ancre":"mediastinale","blocs":["L’atteinte médiastinale est le plus fréquemment observée dans le cadre d’une amylose systémique et peut se présenter sous forme de :","Adénopathies multi-stations ou atteinte localisée à des régions anatomiques spécifiques.","Lésions tuméfactives isolées (amyloïdomes) pouvant siéger dans n’importe quel compartiment médiastinal.","Un épaississement périvasculaire."]},{"titre":"","badge":"","ancre":"mediastinale","blocs":["Les symptômes dépendent de la localisation de la lésion et de sa proximité avec les structures adjacentes. L’atteinte médiastinale se révèle souvent par des adénopathies asymptomatiques, constituant la troisième manifestation thoracique de l’amylose, après les atteintes des voies aériennes et parenchymateuses nodulaires.","Les adénopathies médiastinales peuvent présenter des calcifications punctiformes, diffuses ou en « coquille d’œuf »."]},{"titre":"","badge":"","ancre":"mediastinale","blocs":["Fig. 8TDM thoracique avec injection, en fenêtre médiastinale, montrant un conglomérat d'adénopathies paratrachéales droites formant une masse flèches blanches, engainant la trachée et la veine cave supérieure, qui apparaît rétrécie flèche jaune.","Fig. 9Amylose ganglionnaire. TDM thoracique sans injection montrant des ganglions médiastinaux à calcifications centrales flèches.","Fig. 10Amylose ganglionnaire. TDM thoracique avec injection, en fenêtre médiastinale, montrant des adénopathies hilaires et interbronchiques bilatérales, ainsi que des ganglions sous-carénaires et de la fenêtre aorto-pulmonaire hypodenses avec rehaussement périphérique flèches.","Fig. 11Amylose médiastinale extraganglionnaire. TDM thoracique avec injection, en fenêtre médiastinale, montrant un manchon de densité tissulaire péri-aortique infiltrant le tronc de l'artère pulmonaire et l'artère pulmonaire droite flèches.","Fig. 12Amylose médiastinale extraganglionnaire. Patient de 67 ans consultant pour une toux, avec sur la radiographie thoracique une opacité médiastinale effaçant la ligne para-aortique flèche noire. La TDM thoracique avec injection montre un manchon péri-aortique bifocal flèches jaunes."]}]},{"id":"pleural","titre":"Épanchement pleural au cours de l’amylose","rubriques":[{"titre":"Prévalence et types","badge":"A","ancre":"pleural","blocs":["Les épanchements pleuraux surviennent dans environ 20 % des cas d’amylose AL.","Un tiers de ces épanchements sont abondants et réfractaires aux diurétiques.","Ils sont rares dans les amyloses de type AA et ATTR."]},{"titre":"Considérations en imagerie","badge":"B","ancre":"pleural","blocs":["Les épanchements peuvent être unilatéraux ou bilatéraux, transudatifs ou exsudatifs.","Des épanchements pleuraux persistants (EPP) doivent faire suspecter un dépôt amyloïde pleural direct, en particulier en l’absence de dysfonctionnement cardiaque ou rénal."]},{"titre":"Implications diagnostiques et pronostiques","badge":"C","ancre":"pleural","blocs":["La TDM et l’échographie aident à évaluer les caractéristiques de l’épanchement.","La biopsie pleurale peut confirmer l’infiltration amyloïde.","Les épanchements pleuraux persistants au cours de l’amylose AL sont associés à un mauvais pronostic en l’absence de traitement."]}]},{"id":"conclusion","titre":"Conclusion","rubriques":[{"titre":"","badge":"","ancre":"conclusion","blocs":["L’amylose thoracique présente des aspects radiologiques variés pouvant simuler d’autres pathologies pulmonaires. La connaissance de ces caractéristiques clés est indispensable pour le radiologue afin de permettre un diagnostic précoce et une prise en charge adaptée, évitant ainsi des interventions chirurgicales inutiles et une aggravation des lésions d’organes."]}]}]},{"id":"fractures-radius-distal","url":"fiches/fractures-radius-distal.html","titre":"Fractures de l'extrémité distale du radius","spe":"trauma","sections":[{"id":"pratique","titre":"Le profil nomme, trois mesures gradent","rubriques":[{"titre":"","badge":"","ancre":"pratique","blocs":["Lecture en deux temps","Face et profil stricts, avant et après réduction. Le profil donne le type : fragment distal basculé en dorsal, en palmaire, ou fracture du rebord articulaire. Les trois mesures (inclinaison radiale, hauteur radiale, inclinaison palmaire) disent si l'alignement est acceptable.","Fracture","Sur le profil","Pouteau-Colles","Fragment distal basculé et déplacé en dorsal ; fracture extra-articulaire.","Goyrand-Smith","Fragment distal déplacé en palmaire : le « Pouteau-Colles inversé ».","Barton","Fracture du rebord articulaire (palmaire ou dorsal), le carpe subluxé avec le fragment."]}]},{"id":"anatomie-3d","titre":"Os de la main et du poignet en 3D","rubriques":[{"titre":"","badge":"","ancre":"anatomie-3d","blocs":["Main droite. Survolez ou cliquez un os pour son nom. Les mesures sont tracées sur le radius du modèle ; les repères de lecture allument les os à contrôler sur chaque poignet."]}]},{"id":"fractures","titre":"Les trois fractures","rubriques":[{"titre":"","badge":"","ancre":"fractures","blocs":["Fracture 1"]},{"titre":"Pouteau-Colles","badge":"","ancre":"fractures","blocs":["Profil et face. Clichés : Kirchberg et al., West J Emerg Med 2026, CC BY 4.0 ; recadrés.","Extra-articulaire, fragment distal basculé en dorsal.","Mécanisme : chute sur la paume, poignet en extension.","Profil : bascule dorsale, déformation en « dos de fourchette ».","Souvent : fracture de la styloïde ulnaire associée."]},{"titre":"","badge":"","ancre":"fractures","blocs":["Fracture 2"]},{"titre":"Goyrand-Smith","badge":"","ancre":"fractures","blocs":["Profil et face. Clichés : Kirchberg et al., West J Emerg Med 2026, CC BY 4.0 ; recadrés.","Le « Pouteau-Colles inversé » : fragment distal déplacé en palmaire.","Mécanisme : chute sur le poignet en flexion.","Profil : bascule palmaire, déformation en « ventre de fourchette ».","Instable : souvent fixée par une plaque palmaire."]},{"titre":"","badge":"","ancre":"fractures","blocs":["Fracture 3"]},{"titre":"Barton","badge":"","ancre":"fractures","blocs":["Profil et face. Clichés : Kirchberg et al., West J Emerg Med 2026, CC BY 4.0 ; recadrés.","Fracture du rebord articulaire, le carpe subluxé avec le fragment.","Palmaire ou dorsale : la forme palmaire est la plus fréquente.","Fracture-luxation : le carpe suit le rebord.","TDM : taille du fragment et marche articulaire."]}]},{"id":"mesures","titre":"Les trois mesures","rubriques":[{"titre":"","badge":"","ancre":"mesures","blocs":["Sur des incidences de face et de profil strictes, avant et après réduction. Les deux premières se mesurent de face, la troisième de profil.","≈ 22°Inclinaison radialeFace : ligne pointe de la styloïde radiale → coin ulnaire de la surface articulaire, comparée à la perpendiculaire à l'axe du radius.","≈ 11 mmHauteur radialeFace : écart, le long de l'axe, entre la pointe de la styloïde et le coin ulnaire de la surface articulaire.","≈ 11°Inclinaison palmaireProfil : ligne rebord dorsal → rebord palmaire, comparée à la perpendiculaire à l'axe. Négative = bascule dorsale.","Face : inclinaison radiale (vert) et hauteur radiale (orange).","À gauche : bascule dorsale (Pouteau-Colles) ; au-delà de 10° de bascule dorsale, le trait passe au rouge."]},{"titre":"Sur des clichés","badge":"","ancre":"mesures","blocs":["Face : inclinaison radiale (normale ≈ 22°) et hauteur radiale (normale ≈ 11 mm).","Profil : inclinaison palmaire (normale ≈ 11°), entre la ligne des rebords et la perpendiculaire à l'axe.","Clichés : Kirchberg et al., West J Emerg Med 2026, CC BY 4.0 ; recadrés, annotations d'origine retirées et remplacées par nos tracés."]}]},{"id":"seuils","titre":"L'alignement est-il acceptable ?","rubriques":[{"titre":"","badge":"","ancre":"seuils","blocs":["Seuils qui orientent vers une fixation.","Mesure","Normale","Fixation si","Hauteur radiale","≈ 11 mm","raccourcissement > 3 mm","Inclinaison palmaire","≈ 11°","bascule dorsale > 10°","Surface articulaire","congruente"]}]},{"id":"differentiels","titre":"Autres fractures du radius","rubriques":[{"titre":"","badge":"","ancre":"differentiels","blocs":["Nommer le type, puis vérifier les articulations."]},{"titre":"Fracture de Hutchinson (« du chauffeur »)","badge":"1","ancre":"differentiels","blocs":["Trait passant par la styloïde radiale, articulaire."]},{"titre":"Fracture « die-punch »","badge":"2","ancre":"differentiels","blocs":["Le lunatum enfonce la fossette lunarienne du radius : marche articulaire."]},{"titre":"Fracture de Galeazzi","badge":"3","ancre":"differentiels","blocs":["Fracture diaphysaire du radius avec luxation radio-ulnaire distale."]},{"titre":"Chez l'enfant","badge":"4","ancre":"differentiels","blocs":["Fracture en motte de beurre (torus), en bois vert, et décollement épiphysaire Salter-Harris II."]},{"titre":"","badge":"","ancre":"differentiels","blocs":["Sur chaque poignet : scaphoïde et alignement du carpe."]}]},{"id":"pieges","titre":"Piège : la satisfaction de recherche","rubriques":[{"titre":"","badge":"","ancre":"pieges","blocs":["Une fracture trouvée, la seconde manquée","Lisez le carpe comme si le radius était normal. Cliquez un point pour l'allumer en 3D."]}]},{"id":"compte-rendu","titre":"Compte rendu","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Le type, les chiffres, les articulations.","Résultats","Poignet gauche, face et profil. Fracture extra-articulaire de l'extrémité distale du radius, à 2 cm de l'interligne, avec bascule dorsale de 25°, raccourcissement radial de 4 mm et inclinaison radiale de 15°. Fracture de la styloïde ulnaire. Alignement du carpe conservé. Pas de fracture du scaphoïde.","Conclusion","Fracture extra-articulaire de l'extrémité distale du radius à bascule dorsale, de type Pouteau-Colles, associée à une fracture de la styloïde ulnaire.","Chiffres : inclinaison sagittale, hauteur, inclinaison radiale, avant et après réduction.","Articulations : marche radio-carpienne, radio-ulnaire distale, carpe."]}]}]},{"id":"cancer-du-cavum","url":"fiches/cancer-du-cavum.html","titre":"Cancer du cavum : l'imagerie","spe":"orl","sections":[{"id":"generalites","titre":"Généralités & clinique","rubriques":[{"titre":"","badge":"","ancre":"generalites","blocs":["Fossette de Rosenmüller","Récessus situé en haut et en arrière du cavum, au-dessus et en arrière du torus tubaire : siège de naissance principal du cancer du nasopharynx."]},{"titre":"Terrain et histologie","badge":"","ancre":"generalites","blocs":["Le nasopharynx est un carrefour : fosses nasales, VADS, espaces profonds, base du crâne et endocrâne ; tumeurs surtout malignes. Bilan locorégional par IRM +++.","UCNT (carcinome indifférencié du nasopharynx) = 90 % des cas, associé à l'EBV (anticorps anti-EBV élevés).","Autres : carcinomes épidermoïdes ± différenciés, adénocarcinome, carcinome adénoïde kystique, sarcome, lymphome.","Formes bénignes plus rares : hypertrophie lymphoïde, kystes (dont le kyste de Tornwaldt)."]},{"titre":"Clinique","badge":"","ancre":"generalites","blocs":["Signes souvent tardifs et discrets : délai diagnostique moyen 8 à 10 mois.","Premiers signes : otalgie, oreille bouchée, otite séreuse (trouble du drainage tubaire).","Formes évoluées : céphalées, atteinte des nerfs crâniens (trijumeau), obstruction nasale + épistaxis, adénopathie cervicale."]},{"titre":"Évolution type","badge":"","ancre":"generalites","blocs":["Naissance à la fossette de Rosenmüller","Développement ± exophytique","Infiltration sous-muqueuse rapide (élévateur du voile ++)","Franchissement du fascia pharyngo-basilaire → espaces profonds","Réflexe majeur","Toute otite séromuqueuse récidivante de l'adulte impose une imagerie du cavum, même si l'endoscopie est normale."]}]},{"id":"imagerie","titre":"Imagerie : modalités & protocole","rubriques":[{"titre":"IRM ou TDM ?","badge":"","ancre":"imagerie","blocs":["IRM plus sensible pour l'atteinte périnerveuse, médullaire osseuse et l'extension endocrânienne (staging T et N).","TDM meilleure pour les petites érosions corticales de la base du crâne.","Recommandation : TDM hélicoïdale fine HR (fenêtre osseuse, base du crâne) + IRM base du crâne et cou.","Tumeur T4 volumineuse non curable : la TDM seule peut définir grossièrement les marges."]},{"titre":"Stratégie pratique","badge":"","ancre":"imagerie","blocs":["Point de départ","Tumeur suspectée (clinique, anamnèse)","IRMpérinerveux, endocrâne, médullaire, ganglions","ADP cervicales isolées, sans tumeur VADS connue","TDM cervicale injectée + TAP","IRMsi tumeur du cavum suspectée"]},{"titre":"Protocole IRM","badge":"","ancre":"imagerie","blocs":["Séquence","Objectif","Installation","Antenne tête-cou ; axial parallèle au palais, coronal perpendiculaire ; matrice 352 × 256, au moins 256 × 256.","T1 sans FS ni Gd","Moelle du clivus : perte de l'hypersignal T1 si infiltration.","TSE T2 HR","Signal et limites tumorales.","T2 cervical","Toutes les chaînes ganglionnaires.","T1 Gd + FS","Axial + coronal ± sagittal : espaces profonds, foramens, extension périnerveuse, endocrâne."]}]},{"id":"extension","titre":"Extension locorégionale : les espaces et les foramens en 3D","rubriques":[{"titre":"","badge":"","ancre":"extension","blocs":["Lecture systématique : extensions antérieure, latérale, postérieure, inférieure et supérieure, puis les ganglions. Choisissez une direction : ses trajets s'animent depuis la fossette de Rosenmüller (tumeur schématique, côté droit) et les foramens traversés s'allument."]},{"titre":"1Antérieure","badge":"","ancre":"dir-anterieure","blocs":["Cavités nasales : continuité directe, sans barrière anatomique.","Fosse ptérygopalatine (FPP) par le foramen sphénopalatin : remplacement de la graisse normale, bien vu en T1 sans injection."]},{"titre":"2Latérale","badge":"","ancre":"dir-laterale","blocs":["Espace parapharyngé : voie directe (franchissement du fascia pharyngo-basilaire) ou indirecte par l'orifice d'Eustache (fosse infratemporale / espace masticateur → V3 → foramen ovale → endocrâne).","Foramen lacerum : destruction du fibrocartilage → extension intracrânienne.","À signaler : espaces parapharyngé et carotidien, ptérygoïdiens, fosse infratemporale, extension périnerveuse V2 / V3 / vidien, sinus caverneux."]},{"titre":"3Postérieure","badge":"","ancre":"dir-posterieure","blocs":["Espace rétropharyngé → muscles prévertébraux ; extension possible à l'espace carotidien.","Formes avancées : lyse vertébrale.","Plus latéralement : foramen jugulaire, canal de l'hypoglosse ; rarement fosse postérieure."]},{"titre":"4Inférieure","badge":"","ancre":"dir-inferieure","blocs":["Muqueuse oropharyngée et loge amygdalienne.","Extension parfois uniquement sous-muqueuse, invisible à l'endoscopie."]},{"titre":"5Supérieure / intracrânienne","badge":"","ancre":"dir-superieure","blocs":["Environ 30 % des cas.","Voies : foramen lacerum, foramen ovale, fissure orbitaire inférieure puis supérieure, lyse directe de la base du crâne.","Souvent périnerveuse et extracérébrale (sinus caverneux, méninge de la fosse temporale)."]},{"titre":"La fosse ptérygopalatine, carrefour vers 4 voies","badge":"","ancre":"extension","blocs":["FPP","Foramen rondExtension périnerveuse le long du V2.","Fissure orbitaire inférieureApex orbitaire, puis orbite ± fissure orbitaire supérieure et endocrâne.","Fosse infratemporaleLyse du processus ptérygoïde ; trajet du V3 vers le foramen ovale puis l'endocrâne.","Canal ptérygoïdienExtension périnerveuse le long du nerf vidien.","Piège","La tumeur peut cheminer dans les espaces profonds et le long des nerfs avant qu'une lyse osseuse soit évidente : IRM +++."]}]},{"id":"ganglions","titre":"Ganglions & métastases","rubriques":[{"titre":"Adénopathies","badge":"","ancre":"ganglions","blocs":["Très fréquentes : ≈ 90 % des cas ; motif révélateur fréquent.","1er relais : ganglions rétropharyngés (65 %), pathologiques si petit axe > 8 mm.","2e relais : chaînes cervicales, surtout jugulaires hautes.","Critères suspects : forme ronde, nécrose, petit axe > 1 cm, rupture capsulaire, infiltration de la graisse péri-ganglionnaire.","Staging : une atteinte bilatérale ou sous le bord inférieur du cricoïde modifie le stade N."]},{"titre":"Métastases","badge":"","ancre":"ganglions","blocs":["Fréquence 5 à 41 % ; risque accru si ADP basses ou extension importante aux espaces profonds.","Bilan à distance : TDM thoraco-abdominale ; en cas d'ADP isolées, TDM cervico-thoraco-abdomino-pelvienne injectée.","Os20 %","Poumon13 %","Foie9 %"]}]},{"id":"tnm","titre":"Classification TNM 8e édition (2018)","rubriques":[{"titre":"","badge":"","ancre":"tnm","blocs":["Cliquez sur un stade T pour l'afficher dans le modèle 3D ; composez T, N et M pour obtenir le stade.","N1ADP cervicales unilatérales et/ou ganglions rétropharyngés uni- ou bilatéraux, ≤ 6 cm, au-dessus du bord inférieur du cricoïde.","N2ADP cervicales bilatérales ≤ 6 cm, au-dessus du bord inférieur du cricoïde.","N3ADP uni- ou bilatérales > 6 cm et/ou sous le bord inférieur du cricoïde.","Calculer le stade","T N M","Regroupement en stades : AJCC / UICC 8e édition (nasopharynx). N0 : pas d'adénopathie ; M1 : métastase(s) à distance.","Bilan initial","IRM = staging locorégional T + N ; TDM thoraco-abdominale = bilan à distance M."]}]},{"id":"differentiels","titre":"Diagnostics différentiels & suivi","rubriques":[{"titre":"Hypertrophie adénoïde (bénigne)","badge":"1","ancre":"differentiels","blocs":["Pas de déformation des contours : reliefs comblés mais respectés.","Pas d'infiltration profonde ; espaces parapharyngés non refoulés ; rehaussement homogène.","TDM : hypodense avec trappage aérique ; IRM : aspect discrètement strié."]},{"titre":"Kyste de Tornwaldt","badge":"2","ancre":"differentiels","blocs":["Strictement médian, bien limité, contenu liquidien sans rehaussement interne.","Signal variable ± protidique : peut être spontanément hyperT1 et hyperT2."]},{"titre":"Kystes adénoïdiens","badge":"3","ancre":"differentiels","blocs":["Petites structures kystiques enchâssées dans les végétations, bien limitées.","HyperT2 ± discret hyperT1, sans rehaussement pathologique."]},{"titre":"Pseudotumeur inflammatoire","badge":"4","ancre":"differentiels","blocs":["Rare, peut mimer une tumeur maligne : infiltration mal limitée, rehaussée, espaces profonds, extensions périnerveuses.","Diagnostic par biopsie ; réponse initiale fréquente aux corticoïdes, mais récidives fréquentes."]},{"titre":"","badge":"","ancre":"differentiels","blocs":["Piège","Toujours éliminer une composante tissulaire intrakystique rehaussée : tumeur maligne pseudokystique."]},{"titre":"Suivi IRM","badge":"","ancre":"differentiels","blocs":["2 à 3 moisBilan post-thérapeutique de référence (recul des remaniements inflammatoires).","1re annéeTous les 4 mois.","2e annéeTous les 6 mois.","Au-delàUne fois par an.","Pour la récidive, le TEP-scanner est plus sensible que l'IRM et la TDM."]},{"titre":"Compte rendu en 6 étapes","badge":"","ancre":"differentiels","blocs":["1Siège, volume et signal.","2Extension selon les 5 directions.","3Espaces profonds et voies périnerveuses.","4Base du crâne et endocrâne.","5Ganglions.","6Stade TNM.","Conclusion","L'imagerie peut poser le diagnostic quand l'endoscopie est normale, précise les champs d'irradiation et assure la surveillance. L'IRM reste l'examen de référence du bilan d'extension."]}]}]},{"id":"cholesteatome","url":"fiches/cholesteatome.html","titre":"Cholestéatome : l'imagerie","spe":"orl","sections":[{"id":"essentiel","titre":"L'essentiel","rubriques":[{"titre":"","badge":"","ancre":"essentiel","blocs":["Définition","Masse épidermique kératinisante de l'oreille moyenne, agressive et ostéolytique. C'est l'otite moyenne chronique « dangereuse » : rare, mais le traitement est chirurgical et l'imagerie est systématique."]},{"titre":"Comment naît un cholestéatome","badge":"","ancre":"essentiel","blocs":["Dysfonction tubaireÉchanges gazeux accrus","Dépression dans la caissePression intratympanique basse","Rétraction du tympanPars flaccida surtout","CholestéatomeInvagination et prolifération épidermique, ou perforation et migration de l'épiderme"]},{"titre":"Quand y penser ?","badge":"","ancre":"essentiel","blocs":["Otorrhée fétide et surdité de transmission ou mixte.","Mots de l'ORL : poche de rétraction non contrôlable, perforation marginale, atticite, atticotomie spontanée, épidermose, polype sentinelle.","Vertige ou paralysie faciale périphérique : complication jusqu'à preuve du contraire."]},{"titre":"Qui fait quoi ?","badge":"","ancre":"essentiel","blocs":["Otoscopie : pose le diagnostic.","TDM (systématique) : confirme l'agressivité, cartographie l'extension, signale variantes et complications.","IRM (ciblée) : doute, extension labyrinthique ou intracrânienne, résidu ou récidive après chirurgie."]}]},{"id":"rocher-3d-section","titre":"Le rocher en 3D","rubriques":[{"titre":"","badge":"","ancre":"rocher-3d-section","blocs":["Oreille droite. Rendez l'os transparent, suivez un parcours, ou faites descendre une coupe axiale comme sur la TDM. Cliquez une structure : ce qu'il faut regarder s'affiche."]},{"titre":"Les étages de la caisse","badge":"","ancre":"rocher-3d-section","blocs":["Attique (épitympan)au-dessus du manche du marteau : tête du marteau, corps de l'enclume ; mur de la logette en dehors, tegmen au-dessus. Siège classique.","Mésotympanen dedans du tympan tendu : manche du marteau, longue apophyse de l'enclume, étrier, fenêtres, promontoire, VII2.","Hypotympansous le promontoire, plancher de la caisse : rapports avec le golfe jugulaire.","Rétrotympanumrécessus du facial, éminence pyramidale, sinus tympani (mal vu du chirurgien).","Aditus → antre → mastoïdevoie d'extension postérieure depuis l'attique.","Rétrotympanum (coupe axiale), de dehors en dedans : récessus du facial, éminence pyramidale (muscle stapédien à son sommet), sinus tympani : le recoin où le cholestéatome résiduel se cache."]}]},{"id":"technique","titre":"Technique","rubriques":[{"titre":"","badge":"","ancre":"technique","blocs":["TDM des rochers — 1re intention","0,5 mm","Volumique, bilatérale, sans injection.","Coupes de 0,5 mm, petit champ, matrice ≥ 512, filtre osseux.","Axial parallèle au canal semi-circulaire latéral ; reconstructions coronales, sagittales et obliques (chaîne ossiculaire, étrier, articulation incudo-malléaire)."]},{"titre":"","badge":"","ancre":"technique","blocs":["IRM — question ciblée","b 1000","T1 axial sans injection.","Diffusion non-EPI (TSE), axiale + coronale, b 800–1000 (parfois 1300) : moins d'artéfacts de la base du crâne que l'EPI.","T2 haute résolution 3D (CISS / FIESTA) ; T1 FS gadolinium tardif (≈ 30 min) ; FLAIR tardif et séquence veineuse si besoin."]},{"titre":"","badge":"","ancre":"technique","blocs":["IRM : quand la demander ?","Doute clinique ou TDM, comblement diffus (surtout chez l'enfant)","Suspicion d'atteinte labyrinthique","Suspicion d'atteinte cérébro-méningée, thrombose, abcès","Recherche de résidu ou récidive après chirurgie"]}]},{"id":"omc","titre":"Le terrain : stigmates d'otite moyenne chronique","rubriques":[{"titre":"","badge":"","ancre":"omc","blocs":["Toute otite moyenne évoluant depuis plus de 3 mois. Ces signes sont communs à l'OMC simple et au cholestéatome : ils ne font pas le diagnostic.","Sclérose ± hypopneumatisation mastoïdienne : l'inflammation du mucopérioste produit de l'os néoformé.","Épaississement ± calcifications de la membrane tympanique (normalement quasi invisible).","Opacités diffuses de l'oreille moyenne : déclives ou non, bords non convexes, sans effet de masse.","Faites glisser : de la mastoïde normale à la sclérose","Mastoïde normale : la pneumatisation progresse d'avant en arrière jusqu'à la suture temporo-occipitale.","Sclérose et interruption de la pneumatisation.","Opacités « non spécifiques » : pas de lyse, pas d'effet de masse.","Chaîne ossiculaire « noyée » : même densité que l'épanchement ou la muqueuse épaissie.","Tympanosclérose : plaques pseudo-cartilagineuses ± calcifiées, ankylose possible de la chaîne.","Information capitale","BDE (branche descendante de l'enclume) : zone la plus fragile. Elle est atteinte même en cas d'OMC non cholestéatomateuse : une lyse de la BDE ne suffit pas à affirmer un cholestéatome."]}]},{"id":"tdm-diagnostic","titre":"TDM : diagnostic positif","rubriques":[{"titre":"","badge":"","ancre":"tdm-diagnostic","blocs":["Quatre critères. Les deux qui comptent le plus : la masse à bords convexes et l'ostéolyse.","1Masse","Opacité nodulaire ou polylobée, homogène, non calcifiée, à bords convexes dans les 3 plans.","2Siège","Typiquement attical supéro-latéral (attique externe), puis aditus et antre.","3Effet de masse","Refoule le bloc incudo-malléaire vers le dedans.","4Ostéolyse","À front lisse : mur de la logette, osselets, parois de la caisse, labyrinthe, tegmen.","Opacité polylobée à bords convexes, mur de la logette lysé, chaîne englobée ; petite extension probable par un polype sentinelle au fond du conduit.","Effet de masse — repère : l'enclume se projette normalement sur la bissectrice tracée depuis la fossa incudis.","Effet de masse : l'enclume est refoulée hors de la bissectrice."]},{"titre":"Forme « évacuée »","badge":"","ancre":"tdm-diagnostic","blocs":["Pas de masse visible. Le diagnostic repose sur l'otoscopie et les séquelles d'agressivité : atticotomie spontanée, lyse du mur de la logette, érosion ossiculaire, cavité anormale."]},{"titre":"","badge":"","ancre":"tdm-diagnostic","blocs":["Atticotomie spontanée.","Cavité anormale de l'attique, sans masse."]}]},{"id":"extension","titre":"Cartographie d'extension","rubriques":[{"titre":"","badge":"","ancre":"extension","blocs":["Le bilan préopératoire précise : côté, siège d'origine, dimensions dans les 3 plans, trajet de compartiment en compartiment, structures détruites, variantes qui changent l'abord. Cliquez un compartiment.","Siège classique. Décrire la lyse du mur de la logette, le refoulement en dedans ou l'érosion du bloc incudo-malléaire, puis vérifier l'ouverture de l'aditus."]}]},{"id":"risques","titre":"Structures à risque et complications","rubriques":[{"titre":"","badge":"","ancre":"risques","blocs":["Une structure par ligne : ce qu'il faut chercher, sur quelle image."]},{"titre":"Chaîne ossiculaire","badge":"","ancre":"risques","blocs":["La longue apophyse de l'enclume est la plus fragile ; puis corps de l'enclume, tête du marteau, superstructure de l'étrier. Une déminéralisation nette a la même valeur qu'une lyse franche.","Lyse ossiculaire."]},{"titre":"Mur de la logette","badge":"","ancre":"risques","blocs":["Émoussement puis amputation de son bord inférieur : quasi spécifique. Mais un mur intact n'exclut pas un cholestéatome, surtout chez l'enfant."]},{"titre":"Tegmen tympani et antri","badge":"","ancre":"risques","blocs":["Une brèche doit être vue sur plusieurs coupes contiguës, au contact de la masse, et comparée au côté opposé. Vraie brèche : méningocèle, réaction méningée, complication intracrânienne.","Lyse du tegmen."]},{"titre":"Labyrinthe : fistule","badge":"","ancre":"risques","blocs":["Disparition de la coque osseuse au contact du cholestéatome, surtout du canal semi-circulaire latéral (labyrinthe membraneux à nu). Préciser le canal et la longueur. IRM : amputation du signal liquidien en T2 ; rehaussement = labyrinthite. Un vertige justifie l'IRM même si la TDM est douteuse.","Canal semi-circulaire latéral.","Canal semi-circulaire postérieur.","Promontoire (tour basal de la cochlée).","Promontoire, autre plan."]},{"titre":"Canal facial","badge":"","ancre":"risques","blocs":["Dénudations surtout au plancher du segment tympanique (VII2), parfois VII3. Une bande osseuse absente est seulement suspecte : ne pas affirmer l'envahissement du nerf en TDM (volume partiel), confirmer sur plusieurs plans.","VII2 (coronal).","VII3 (axial)."]},{"titre":"Canaux vasculaires","badge":"","ancre":"risques","blocs":["Continuité de la coque du canal carotidien, du golfe jugulaire et de la plaque sigmoïdienne. Toute anomalie du sinus sigmoïde ou latéral : chercher une thrombose (séquence veineuse).","Canal carotidien.","Sinus sigmoïde.","Fonctionnelleslyse ossiculaire ; fistule (vertiges) ; labyrinthite (surdité de perception) ; dénudation du VII (paralysie faciale)","Cérébro-méningéesméningocèle, méningite, empyème extradural, abcès cérébral → IRM cérébrale injectée avec diffusion","Vasculairesthrombophlébite du sinus sigmoïde ou latéral","Infectieusescholestéatome surinfecté, mastoïdite extériorisée, abcès"]}]},{"id":"variantes","titre":"Variantes à signaler au chirurgien","rubriques":[{"titre":"Mastoïde","badge":"","ancre":"variantes","blocs":["Pneumatisation, sclérose, accès à l'antre : une mastoïde éburnée change l'abord.","Mastoïde complètement scléreuse."]},{"titre":"Golfe jugulaire","badge":"","ancre":"variantes","blocs":["Procident s'il monte haut dans l'hypotympan ; déhiscent si aucune coque ne le sépare de la caisse : risque de plaie vasculaire.","Procident.","Déhiscent."]},{"titre":"Sinus sigmoïde antérieur et superficiel","badge":"","ancre":"variantes","blocs":["La mastoïde se sclérose, le sinus s'avance dans l'espace perdu. En axial : procidence si une tangente à son bord antérieur traverse l'oreille interne.","Sinus sigmoïde antérieur.","Antérieur et superficiel."]},{"titre":"Tegmen et canal facial","badge":"","ancre":"variantes","blocs":["Tegmen bas ou très aminci : comparer au côté opposé avant de parler de lyse. Canal facial procident ou déhiscence préexistante. Préciser séparément les rapports avec le cholestéatome."]}]},{"id":"irm","titre":"IRM : caractériser le comblement","rubriques":[{"titre":"","badge":"","ancre":"irm","blocs":["Tissu","Diffusion b1000","Gadolinium","Cholestéatome","hypo","hyper","hyper (ADC bas)","pas de prise, même tardive (liseré périphérique possible)","Tissu fibro-inflammatoire","prise tardive (≈ 30 min)","Granulome à cholestérine","hyper spontané"]}]},{"id":"post-op","titre":"Après chirurgie","rubriques":[{"titre":"Technique fermée","badge":"","ancre":"post-op","blocs":["Cholestéatome limité. Abord mastoïdien postérieur, paroi postérieure et supérieure du conduit conservée, greffe tympanique souvent cartilagineuse. Résidu possible : surveillance.","Technique fermée (axial) : paroi postérieure du conduit conservée (CAE), abord mastoïdien postérieur.","Technique fermée (coronal) : greffe tympanique, paroi supérieure du conduit conservée."]},{"titre":"Technique ouverte","badge":"","ancre":"post-op","blocs":["Cholestéatome étendu. Cavité d'évidement pétro-mastoïdienne (paroi du conduit enlevée), souvent avec micro-caisse.","Cavité d'évidement pétro-mastoïdienne (vert).","Micro-caisse (orange) et cavité d'évidement pétro-mastoïdienne (vert).","Autre plan : micro-caisse (orange), cavité d'évidement (vert)."]},{"titre":"","badge":"","ancre":"post-op","blocs":["TDM","Première imagerie après chirurgie si question d'ossiculoplastie, de tegmen, de complication osseuse.","Récidive / résidu : opacité ronde (perle), bords convexes dans tous les plans.","Pas de cholestéatome : aucune opacité, ou opacité en cadre / localisée à bords concaves.","Les reconstructions coronales et sagittales départagent."]},{"titre":"","badge":"","ancre":"post-op","blocs":["IRM — surveillance","Diffusion non-EPI + T1 sans injection ± T1 gadolinium tardif (30 min), T2 axial et coronal.","Premier bilan et suivi à long terme sans réintervention.","Corréler au compte rendu opératoire."]},{"titre":"","badge":"","ancre":"post-op","blocs":["Perle : bords convexes.","Perle, autre patient.","Piège : greffe tympanique horizontalisée.","Récidive : aucune prise, même tardive."]},{"titre":"Cas : extension intrapétreuse","badge":"","ancre":"post-op","blocs":["Cholestéatome étendu au labyrinthe (CSC latéral) avec lyse du tegmen : chirurgie complexe, plastie du tegmen, lambeau graisseux. Au contrôle, opacité non rehaussée et en hypersignal de diffusion : récidive."]},{"titre":"","badge":"","ancre":"post-op","blocs":["Extension au CSC latéral.","Plastie du tegmen, lambeau graisseux."]}]},{"id":"compte-rendu","titre":"Compte rendu guidé","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Cochez ce que vous avez vu : le texte se construit."]}]}]},{"id":"eu-tirads","url":"fiches/eu-tirads.html","titre":"Nodule thyroïdien : EU-TIRADS 2017","spe":"orl","sections":[{"id":"reperes","titre":"Repères","rubriques":[{"titre":"","badge":"","ancre":"reperes","blocs":["< 5 mm","On n'en tient pas compte, sauf signe de forte suspicion.","10–30 %","grossissent ; 15–25 % diminuent.","≈ 1 mm/an","croissance habituelle de la portion solide ; 6 mm/an = très rapide.","+2 mm · +50 %","variation significative : +2 mm dans au moins 2 diamètres et/ou +50 % de volume.","Grossir n'est pas un signe de malignité ; rester stable n'affirme pas la bénignité."]},{"titre":"L'EU-TIRADS, c'est…","badge":"","ancre":"reperes","blocs":["un lexique standardisé ;","un compte rendu avec schéma ;","des catégories chiffrées en risque de cancer ;","des recommandations de prise en charge."]},{"titre":"Et les ganglions ?","badge":"","ancre":"reperes","blocs":["Une adénopathie ne change pas le score du nodule, mais impose sa propre prise en charge (ponction avec thyroglobuline in situ)."]}]},{"id":"atelier","titre":"Construire un nodule : le lexique en action","rubriques":[{"titre":"","badge":"","ancre":"atelier","blocs":["Changez chaque critère : le nodule se redessine et sa catégorie se recalcule. La bande sombre du haut est le muscle : la référence de l'hypoéchogénicité marquée."]}]},{"id":"categories","titre":"Les 5 catégories","rubriques":[{"titre":"","badge":"","ancre":"categories","blocs":["Algorithme","Chercher d'abord au moins un signe de forte suspicion. S'il n'y en a aucun, classer selon l'échogénicité et les aspects spécifiques.","≥ 1 signe fort ?forme non ovale, contours irréguliers, microcalcifications, hypoéchogénicité marquéeoui → 5","Kyste pur ou spongiforme ?entièrementoui → 2","Composante hypoéchogène modérée ?même partielleoui → 4","Sinonovale, réguliers, entièrement iso/hyperéchogène→ 3","1Normal","Examen normal.","2Bénin","Kyste simple ou nodule entièrement spongiforme.","≈ 0 %","3Faible risque"]}]},{"id":"signes-forts","titre":"Les 4 signes de forte suspicion","rubriques":[{"titre":"","badge":"","ancre":"signes-forts","blocs":["Un seul suffit pour classer EU-TIRADS 5. Plus il y en a, plus le risque monte, sans changer de catégorie.","Forme non ovale","Plus épais que long et/ou large.","Contours irréguliers","Spiculés ou lobulés, au moins 3 lobulations. Flou ≠ irrégulier.","Microcalcifications","Ponctuations < 1 mm, sans ombre ni queue de comète ; compter les groupements (≥ 5).","Hypoéchogénicité marquée","Nodule solide plus sombre que les muscles superficiels.","Plus épais que large Vassallo et al., Eur Radiol 2026, source, CC BY 4.0","Contours irréguliers Vassallo et al., Eur Radiol 2026, source, CC BY 4.0","Microcalcifications Vassallo et al., Eur Radiol 2026, source, CC BY 4.0"]},{"titre":"Signes accessoires : ils modulent le risque, pas la catégorie","badge":"","ancre":"signes-forts","blocs":["Augmentent le risque","Diminuent le risque","Macrocalcifications périphériques discontinues","Halo fin complet","Forme arrondie ; orientation oblique","Composante kystique ; granulations colloïdales","Extension extracapsulaire","Forme très aplatie (longueur > 2,5 × épaisseur)"]}]},{"id":"ponctuations","titre":"Ponctuations hyperéchogènes : ne pas confondre","rubriques":[{"titre":"","badge":"","ancre":"ponctuations","blocs":["Cliquez sur une vignette pour voir de quoi il s'agit.","Colloïde (queue de comète) Vassallo et al., Eur Radiol 2026, source, CC BY 4.0","Macrocalcification (cône d'ombre) Vassallo et al., Eur Radiol 2026, source, CC BY 4.0"]}]},{"id":"compte-rendu","titre":"Compte rendu standardisé","rubriques":[{"titre":"","badge":"","ancre":"compte-rendu","blocs":["Rubrique","Contenu indispensable","Motif","Histoire clinique et biologique ; gêne et ancienneté ; examens et cytoponctions antérieurs ; antécédent familial de cancer ou irradiation cervicale dans l'enfance.","Technique","Sonde, appareil ; difficultés liées au patient.","Glande","Volume, goitre ou goitre plongeant, retentissement trachéal ; échogénicité et vascularisation.","Nodules","Localisation ; 3 diamètres ; caractéristiques ; score EU-TIRADS ; évolution ; numérotation + cartographie. Ne jamais changer le numéro.","Ganglions","Secteurs II, III, IV, VI et tractus thyréoglosse ; au minimum III et VI."]}]},{"id":"cytoponction","titre":"Cytoponction : le seuil de taille","rubriques":[{"titre":"","badge":"","ancre":"cytoponction","blocs":["Faites varier la taille du nodule : les catégories à ponctionner s'allument.","Adénopathie suspecte : ponction ganglionnaire avec dosage de thyroglobuline in situ, systématique."]}]},{"id":"suivi","titre":"Surveillance et chirurgie","rubriques":[{"titre":"","badge":"","ancre":"suivi","blocs":["1 anpremier contrôle","+2 anssi stable","+3 ans","+5 ans","Ne pas trop espacer un nodule complexe : 2 à 3 ans.","Arrêt possible si seuls des nodules EU-TIRADS 3 ≤ 10 mm ou EU-TIRADS 4 ≤ 5 mm."]},{"titre":"Chirurgie ou alternatives","badge":"","ancre":"suivi","blocs":["Toute cytoponction maligne ou suspecte.","Macronodule > 40 mm ou signes compressifs : indication à discuter ; thermo-ablation possible.","Éventuellement quand la surveillance devient trop contraignante."]}]},{"id":"pieges","titre":"Multinodulaire, pièges et limites","rubriques":[{"titre":"Thyroïde multinodulaire : dans quel ordre chercher ?","badge":"","ancre":"pieges","blocs":["Les EU-TIRADS 5","Puis les EU-TIRADS 4décrire si > 5 mm","Puis les EU-TIRADS 3 volumineux (> 20 mm)décrire si > 10 mm","Sans nodule à risque élevé ou intermédiaire, 96 % des cancers sont éliminés."]},{"titre":"Kyste colloïde en involution","badge":"Faux positif","ancre":"pieges","blocs":["Tuméfaction apparue vite, parfois sensible, puis qui régresse ; avasculaire ; diminue en quelques mois. Cytoponction ne ramenant que de la colloïde : prélèvement représentatif, pas « non significatif »."]},{"titre":"Nodule majoritairement kystique","badge":"Faux négatif","ancre":"pieges","blocs":["1–3 % des carcinomes, la moitié des faux négatifs. Dans la partie solide, chercher hypoéchogénicité et microcalcifications : la portion solide devrait être iso/hyperéchogène, toute hypoéchogénicité, même modérée, est suspecte. Ponctionner la portion solide.","Nodule mixte : analyser la portion solide Vassallo et al., Eur Radiol 2026, source, CC BY 4.0"]},{"titre":"Nodule solide isoéchogène","badge":"Faux négatif","ancre":"pieges","blocs":["Sans signe fort : 1–3 % des carcinomes, l'autre moitié des faux négatifs ; surtout carcinome papillaire, variante folliculaire, plus rarement folliculaire."]},{"titre":"Place limitée","badge":"Doppler","ancre":"pieges","blocs":["Non recommandé en routine pour le score. Dans un solide isoéchogène > 20 mm : vascularisation centrale augmente un peu le risque, périphérique diminue celui de carcinome folliculaire. Utile pour distinguer colloïde épaisse et nodule solide, et guider les gestes."]},{"titre":"Thyroïde trop complexe","badge":"Limite","ancre":"pieges","blocs":["Cartographie peu fiable, nodule suspect masqué : le dire au clinicien."]}]},{"id":"entrainement","titre":"Entraînement : classez ces nodules","rubriques":[{"titre":"","badge":"","ancre":"entrainement","blocs":["Regardez le nodule et sa description, choisissez la catégorie. 0 / 6"]}]}]},{"id":"otospongiose","url":"fiches/otospongiose.html","titre":"Otospongiose : la TDM des rochers","spe":"orl","sections":[{"id":"essentiel","titre":"L'essentiel","rubriques":[{"titre":"","badge":"","ancre":"essentiel","blocs":["Définition","Ostéodystrophie primitive de la capsule otique. Le foyer naît en avant de la platine, à la fissula ante fenestram, puis fixe l'étrier : ankylose stapédo-vestibulaire.","Fissula ante fenestramfoyer en avant de la platine","Pôle antérieur de la fenêtre ovaleforme fenestrale","Platine épaissie, ligament annulaire calcifiéfixation de l'étrier","Ankylose stapédo-vestibulairesurdité de transmission"]},{"titre":"Phase active : otospongiose","badge":"","ancre":"essentiel","blocs":["Foyer hypodense, à limites floues (spongieux). C'est lui que la TDM montre."]},{"titre":"Phase inactive : otosclérose","badge":"","ancre":"essentiel","blocs":["Reminéralisation incomplète : foyers plus denses, moins visibles. Une TDM sans foyer n'exclut pas une forme infraradiologique."]}]},{"id":"clinique","titre":"Clinique","rubriques":[{"titre":"","badge":"","ancre":"clinique","blocs":["0,1–2 %","incidence selon les études","60 % ♀","de 20 à 40 ans ; aggravée par la grossesse (œstrogènes)","49–58 %","transmission autosomique dominante","bilatérale","fréquente, souvent asymétrique dans le temps","Examen","Résultat","Otoscopie","tympan normal"]}]},{"id":"technique","titre":"Technique : TDM haute résolution des rochers","rubriques":[{"titre":"","badge":"","ancre":"technique","blocs":["0,5 mm","coupes submillimétriques","≥ 512","matrice, petit champ, filtre osseux","3000 / 900","fenêtre / niveau (UH)","sans","injection (surdité de transmission isolée)","Volumique, bilatérale, en 1re intention.","Axial parallèle au canal semi-circulaire latéral ; reconstructions coronales, sagittales et obliques ciblées sur la chaîne, l'étrier et l'articulation incudo-malléaire."]}]},{"id":"veillon","titre":"Classification TDM de Veillon","rubriques":[{"titre":"","badge":"","ancre":"veillon","blocs":["Cliquez un type : le foyer (gris, flou) se place sur le schéma en coupe axiale. Plus on s'éloigne de la fenêtre ovale vers la cochlée et le labyrinthe, plus le type monte.","Type","Description TDM","Atteinte isolée de la platine, épaissie > 0,6 mm et hypodense.","Hypodensité pré-stapédienne ≤ 1 mm, sans extension à la couche labyrinthique.","Hypodensité pré-stapédienne > 1 mm, sans contact avec la lumière cochléaire.","Hypodensité > 1 mm au contact de la lumière cochléaire.","Hypodensités en avant, en dedans ou en dessous de la cochlée, dans la couche moyenne de la capsule. Sans extension endostée : lamelle d'os sain conservée ; avec : envahissement irrégulier de la lumière.","Atteinte des canaux semi-circulaires et/ou du vestibule."]}]},{"id":"fraysse","titre":"Fenêtre ronde : classification de Fraysse","rubriques":[{"titre":"","badge":"","ancre":"fraysse","blocs":["Son atteinte assombrit le pronostic opératoire : à mentionner impérativement. Faites glisser.","Grade 1 normale","Grade 2 foyers sur les berges externe ou interne","Grade 3 obstruction complète","Grade 4 ossification de la rampe tympanique"]}]},{"id":"formes","titre":"Formes et extensions à connaître","rubriques":[{"titre":"Forme oblitérante","badge":"Fenêtre ovale","ancre":"formes","blocs":["Les limites de la fenêtre ovale s'effacent ; forme oblitérante complète : bloc otospongieux comblant toute la fenêtre, impossible de loger une prothèse sans fraisage large."]},{"titre":"Comblement partiel ou complet","badge":"Fenêtre ronde","ancre":"formes","blocs":["Parfois isolé. Moins bon pronostic opératoire : toujours le signaler."]},{"titre":"Péricochléaire, vestibule, canaux","badge":"Rétrofenestrale","ancre":"formes","blocs":["Foyers autour de la cochlée, du vestibule et des canaux semi-circulaires (types 3–4)."]},{"titre":"Rampe tympanique","badge":"Intracochléaire","ancre":"formes","blocs":["Hypodensité dans la rampe tympanique, parfois ossification secondaire : forme évoluée, souvent avec cophose ou surdité mixte profonde."]},{"titre":"Sans paralysie","badge":"Canal facial","ancre":"formes","blocs":["Le foyer entoure le nerf sans l'envahir : hypodensité péricanalaire du segment tympanique, sans déformation."]},{"titre":"Ankylose ossiculaire","badge":"Chaîne","ancre":"formes","blocs":["Rare, souvent mal identifiée ; cause de surdité mixte."]},{"titre":"En avant du méat acoustique interne","badge":"MAI","ancre":"formes","blocs":["Hypodensité devant le méat : forme rare, à ne pas confondre avec d'autres lésions du MAI."]},{"titre":"Sans surdité","badge":"Infraclinique","ancre":"formes","blocs":["Foyers visibles sans traduction auditive, souvent controlatéraux."]}]},{"id":"preop","titre":"Bilan préopératoire : ce que veut le chirurgien","rubriques":[{"titre":"","badge":"","ancre":"preop","blocs":["Position du nerf facial","Taille du récessus de la fenêtre ovale","Environnement du marteau et de l'enclume","Ventilation de l'oreille moyenne","Couverture osseuse des canaux semi-circulaires"]},{"titre":"Artère stapédienne persistante","badge":"","ancre":"preop","blocs":["Petite opacité canalaire entre les branches de l'étrier, souvent avec absence de foramen épineux. Peut croiser la platine : risque hémorragique, simule un foyer."]},{"titre":"Enclume","badge":"","ancre":"preop","blocs":["Intégrité de la longue apophyse : c'est le plus souvent là que se fixera le piston."]},{"titre":"Marteau","badge":"","ancre":"preop","blocs":["Ponts osseux entre la tête et la paroi latérale de l'attique ; fixation de la tête (congénitale, infectieuse, otospongieuse)."]},{"titre":"Malformations","badge":"","ancre":"preop","blocs":["Oreille interne : vestibule, CSC latéral, cochlée. Oreille moyenne : étrier en fourche, sténose du récessus de la fenêtre ronde."]},{"titre":"Otospongiose + otite chronique","badge":"","ancre":"preop","blocs":["Lyse de la longue apophyse de l'enclume, fixation malléaire, calcifications ossiculaires."]},{"titre":"Caisse du tympan","badge":"","ancre":"preop","blocs":["État de ventilation."]}]},{"id":"differentiels","titre":"Diagnostics différentiels : qui suis-je ?","rubriques":[{"titre":"","badge":"","ancre":"differentiels","blocs":["Lisez l'indice, cliquez pour découvrir."]}]},{"id":"post-op","titre":"Après chirurgie : quel examen, que chercher ?","rubriques":[{"titre":"","badge":"","ancre":"post-op","blocs":["TDM : piston mal positionné, appui incorrect sur l'enclume, tête du marteau restée fixée."]}]}]},{"id":"tumeurs-glandes-salivaires","url":"fiches/tumeurs-glandes-salivaires.html","titre":"Tumeurs des glandes salivaires : l'IRM","spe":"orl","sections":[{"id":"principes","titre":"Principes généraux et types tumoraux","rubriques":[{"titre":"","badge":"","ancre":"principes","blocs":["Message central","L'IRM est la meilleure modalité de caractérisation, et la seule à utiliser en routine. L'échographie sert surtout à guider la cytoponction."]},{"titre":"Risque de malignité","badge":"","ancre":"principes","blocs":["Plus élevé hors de la parotide.","Plus la glande est petite, plus le risque augmente.","Dans la parotide : plus la tumeur est profonde, plus le risque est élevé.","Sublingualerisque +++","Submandibulairerisque ++","Parotiderisque +","plus la glande est petite, plus le risque monte"]},{"titre":"Objectifs de l'imagerie","badge":"","ancre":"principes","blocs":["Confirmer la situation intraparotidienne.","Caractérisation possible dans 90 % des cas ; décrire chaque lésion selon la trame du compte rendu (§ VI).","Limites : distinguer lobe profond et espace parapharyngé ; durée de l'examen."]},{"titre":"Principaux types","badge":"","ancre":"principes","blocs":["Catégorie","Types","Parotide : 3 groupes majeurs","Adénome pléomorphe (AP) ; tumeur de Warthin ; tumeurs épithéliales malignes (CAK, CME, CCA, carcinome ex-AP).","Autres diagnostics","Lymphome non hodgkinien et métastases."]}]},{"id":"strategie","titre":"Stratégie diagnostique : échographie, IRM et cytoponction","rubriques":[{"titre":"Échographie","badge":"","ancre":"strategie","blocs":["Pas en première ligne","Elle ne différencie pas de façon fiable lésion kystique et tissulaire, ne permet pas la caractérisation et explore mal le lobe profond et l'espace parapharyngé.","Lésion superficielle : intraglandulaire ou sous-cutanée ?","Reconnaître l'architecture ganglionnaire normale.","La cytoponction à l'aiguille fine doit être échoguidée ++."]},{"titre":"IRM avant la ponction","badge":"","ancre":"strategie","blocs":["Ordre des examens","Faire l'IRM avant la cytoponction : la ponction peut saigner, créer un hypersignal T1 et fausser la caractérisation.","Avant d'interpréter (checklist)","Localisation ; lésion solitaire, multiple ou bilatérale.","Taille, contours, lobulations, composante solide."]},{"titre":"Diagramme : IRM + cytoponction (FNAC) dans la prise en charge","badge":"","ancre":"strategie","blocs":["Survolez une case pour suivre son chemin ; un clic sur une conclusion mène à la partie de la fiche.","IRM puis cytoponction (FNAC)","IRM et FNAC concordantes","Lésion bénigne à potentiel de transformation, ou malignité intermédiaire / haute","Chirurgie","Warthin ou lésion kystique","Suivi clinique","Discordance","retenir le critère le plus péjoratif","Faible certitude technique","Surveillance Chirurgie","Règle de sécurité"]}]},{"id":"protocole","titre":"Protocole IRM et morphologie","rubriques":[{"titre":"","badge":"","ancre":"protocole","blocs":["Séquence","Analyse","Axial FSE T1","Localisation, limites et lobulations, hypersignal spontané ; impérativement avant la cytoponction.","Axial FSE T2 sans FS","Signal par rapport à la glande ; reflet de la cellularité.","Diffusion b0 / b1000","ADC de la lésion, mesuré par une ROI sur la composante solide.","Perfusion","ROI sur la composante solide présumée ; courbe dynamique.","T1 après gadolinium, tardif","Axial ± coronal si nécessaire, 5 à 10 min après la perfusion."]},{"titre":"T1 axial FSE","badge":"","ancre":"protocole","blocs":["Morphologie : confirmer la localisation intraglandulaire, superficielle ou profonde ; décrire l'étage, les contours (bien ou mal définis) et les lobulations.","Distinguer une tumeur parotidienne d'un ganglion subdigastrique ou d'une lésion de l'espace carotidien.","Hypersignal T1 : contenu protéique ou hémorragique ; possible spontanément dans une tumeur de Warthin."]},{"titre":"T2 axial sans Fat Sat","badge":"","ancre":"protocole","blocs":["Pourquoi sans FS ?","Le signal tumoral se compare au parenchyme normal et dépend de la cellularité. Avec Fat Sat, les lésions paraissent toutes hyperintenses."]},{"titre":"Signal T2 (sans FS) et orientation","badge":"","ancre":"protocole","blocs":["BéninTrès hyperintenseAP, parfois multiloculé avec capsule.","IntermédiaireIso ou peu hypointenseAP cellulaire ou tumeur de grade intermédiaire.","MalinHypointenseMalignité.","Limite","Le T2 oriente mais ne suffit jamais seul : intégrer diffusion, perfusion et morphologie."]}]},{"id":"perfusion","titre":"Diffusion et perfusion","rubriques":[{"titre":"Diffusion : où placer la ROI","badge":"","ancre":"perfusion","blocs":["Dans la portion solide : rehaussée et plutôt hypoT2.","Éviter sang et contenu protéique : exclure les zones hyperT1.","Mesure : ADC de la lésion elle-même, en × 10⁻³ mm²/s."]},{"titre":"Perfusion : où placer la ROI","badge":"","ancre":"perfusion","blocs":["Choix limité de coupes, et non récupérable si la ROI est mal placée.","ROI uniquement sur une composante solide présumée hypoT2, hors zones hémorragiques."]},{"titre":"ADC de la lésion : seuils publiés","badge":"","ancre":"perfusion","blocs":["Seuils de Pietragalla et al. (Radiol Med 2020), qui lisent l'ADC avec la courbe de perfusion. Attention : l'ADC ne classe pas « du moins au plus malin », le Warthin (0,8 à 1,2) chevauche le carcinome et le lymphome (< 0,7) est le plus bas : entre 0,8 et 1,4, la courbe tranche.","ADC de la lésion (× 10⁻³ mm²/s) + courbe","Orientation (Pietragalla 2020)","≥ 1,4 + courbe A","Tumeur bénigne (adénome pléomorphe) : association observée uniquement dans des tumeurs bénignes. L'AP cellulaire peut descendre jusqu'à ≈ 1,2 : il chevauche alors la zone des carcinomes, la courbe et la morphologie tranchent.","0,9 à 1,4 + courbe C","Carcinome (tumeur épithéliale maligne) : spécificité 94,9 %.","0,8 à 1,2 + courbe B","Tumeur de Warthin : ADC bas + courbe B, précision 94,6 % dans l'étude. Ne descend jamais sous 0,8 ; peut monter jusqu'à 1,2, donc chevauche le carcinome : la courbe tranche.","< 0,8","Pas un Warthin : versant malin.","< 0,7 + courbe C"]},{"titre":"Les 3 courbes de perfusion","badge":"","ancre":"perfusion","blocs":["Signal dans la ROI en fonction du temps, de l'injection à la fin de l'acquisition (5 min). Le pic précoce survient dans les 120 premières secondes (zone jaune). Le wash-out se mesure par rapport à la prise de contraste au pic : un wash-out de 30 % correspond à la ligne « 30 % sous le pic ».","A monte sans pic précoce (Tpeak > 120 s) · B pic ≤ 120 s puis redescend sous la ligne « 30 % sous le pic » · C pic ≤ 120 s puis reste au-dessus de cette ligne."]},{"titre":"AAscendante, Tpeak > 120 s","badge":"","ancre":"perfusion","blocs":["Sans pic précoce → AP myxoïde ou cellulaire."]},{"titre":"BPic précoce, wash-out > 30 %","badge":"","ancre":"perfusion","blocs":["Warthin ; courbe la moins spécifique (aussi tumeur maligne ou AP)."]},{"titre":"CPic précoce, wash-out < 30 %","badge":"","ancre":"perfusion","blocs":["Tumeur maligne."]},{"titre":"","badge":"","ancre":"perfusion","blocs":["Repères de la littérature","Pic précoce : temps jusqu'au pic (Tpeak) ≤ 120 s ; au-delà de 120 s, pas de pic précoce (courbe A).","Wash-out : seuil de 30 %, sur une acquisition dynamique de 5 min ; il sépare la courbe B de la courbe C.","Dans une série récente : adénomes pléomorphes en courbe A sans wash-out, Warthin en courbe B (wash-out moyen 59 %), courbe C majoritaire dans les tumeurs malignes (54,5 %) mais aussi dans d'autres tumeurs bénignes.","Gökçe E, Beyhan M. World J Radiol 2023;15(1):20-31, doi:10.4329/wjr.v15.i1.20 · Pietragalla M et al. Radiol Med 2020;125(9):851-63, doi:10.1007/s11547-020-01182-2"]},{"titre":"Discordance perfusion / morphologie : qui l'emporte ?","badge":"","ancre":"perfusion","blocs":["Morphologie bénigne+ Courbe C La perfusion l'emporte : malignité","Morphologie maligne+Courbe A ou B La morphologie l'emporte : malignité"]}]},{"id":"algorithme","titre":"Algorithme décisionnel des lésions de plus de 1 cm","rubriques":[{"titre":"","badge":"","ancre":"algorithme","blocs":["Point de départ","Lésion de plus de 1 cm avec signes morphologiques de bénignité → rechercher d'abord un hypersignal T1.","Lésion salivaire en IRM","Moins de 1 cm","Cytoponction + suivi","> 1 cm, morphologie bénigne : hypersignal T1 ?","Pas d'hypersignal T1 → se fier à la perfusion","Courbe A","Adénome pléomorphemyxoïde ou cellulaire","Courbe B","Malin > bénindiagnostic incertain ; possible AP cellulaire","Courbe C"]},{"titre":"Séquences tardives après gadolinium","badge":"","ancre":"algorithme","blocs":["5 à 10 min après la perfusion ; apport faible à la caractérisation : surtout architecture interne et composante myxoïde.","Un rehaussement hétérogène n'est pas en soi un signe de malignité : possible composante myxoïde d'une tumeur bien différenciée.","Faible rehaussement : wash-out d'une tumeur de Warthin. Absence de rehaussement : AP très myxoïde.","Lésion infiltrante : malignité +++ ; si envahissement suspecté, suivre le trajet intrapétreux du VII."]},{"titre":"Limites de la caractérisation","badge":"","ancre":"algorithme","blocs":["Lésions infracentimétriques : cytoponction + suivi.","Discordances T2 / diffusion / perfusion : rares (< 5 %)."]}]},{"id":"synthese","titre":"Parotide opérée et synthèse","rubriques":[{"titre":"Parotide opérée","badge":"","ancre":"synthese","blocs":["Examen raccourci : diffusion et perfusion inutiles pour la caractérisation.","Objectif : détecter une récidive, surtout d'adénome pléomorphe, en s'affranchissant de la graisse.","Séquence clé : T2 avec Fat Sat.","Si récidive : repérer le nerf facial +++."]},{"titre":"Compte rendu pratique","badge":"","ancre":"synthese","blocs":["1Siège intraglandulaire ; superficiel ou profond ; solitaire, multiple ou bilatéral.","2Taille, contours, lobulations, composante solide ou kystique, infiltration.","3Signal T1 avant ponction ; signal T2 sans FS.","4Diffusion : ROI solide, ADC de la lésion et éventuelle exception Warthin.","5Perfusion : type A / B / C et wash-out.","6Concordance finale ; en cas de conflit, retenir le caractère péjoratif."]},{"titre":"Adénome pléomorphe","badge":"","ancre":"synthese","blocs":["Très hyperT2","ADC","≥ 1,4 avec courbe A (souvent ≈ 2) ; AP cellulaire jusqu'à ≈ 1,2","Perfusion","Type A","Tardif","Possible absence de rehaussement si très myxoïde"]},{"titre":"Warthin","badge":"","ancre":"synthese","blocs":["Possible hyperT1","ADC","0,8 à 1,2 avec courbe B ; jamais < 0,8","Perfusion","Type B","Tardif","Faible rehaussement par wash-out"]},{"titre":"Tumeur maligne","badge":"","ancre":"synthese","blocs":["HypoT2 ou infiltration","ADC","0,9 à 1,4 avec courbe C ; lymphome < 0,7","Perfusion","Type C","Piège","Une courbe A ou B ne neutralise jamais une morphologie maligne"]},{"titre":"Synthèse décisionnelle","badge":"","ancre":"synthese","blocs":["IRM avant FNAC","Morphologie","T2 sans FS","ADC","PerfusionA / B / C","Confrontation à la cytologie","Règle finale Si les critères discordent, le caractère péjoratif l'emporte."]}]}]}]});
